import React from "react"
import { Typography } from "@/components/atoms/text/Typography"
import { Button } from "@/components/atoms/buttons/Button"
import { SectionCard } from "@/components/blocks/cards/SectionCard"
import { Skeleton } from "@/components/blocks/skeleton/Skeleton"
import { StackV } from "@/components/frames/Stack"
import { Grid, type GridItem } from "@/components/frames/Grid"
import { ResumeCard } from "./ResumeCard"
import { RESUME_LIMIT, type ResumeItem } from "@/hooks/useResumeItems"

/** All display text, already localized by the connected `ContinueLearning`; a story passes i18n keys. */
export interface ContinueLearningLabels {
    /** Shown when the viewer has joined a course but has nothing to resume yet. */
    resumeEmpty: string
    /** Shown when the viewer has joined no course at all. */
    coursesEmpty: string
    /** Onboarding CTA label ("Browse courses"). */
    browseCourses: string
}

/** Props for {@link _ContinueLearning} ΓÇö presentational; all data resolved, no fetch/store/i18n. */
export interface ContinueLearningProps {
    /** First load, nothing in hand ΓåÆ the resume grid shimmers in place (co-located). Owned by the connected file. */
    isSkeleton?: boolean
    /** Resume targets, in-progress challenges first, capped + de-duplicated. */
    resumeItems?: Array<ResumeItem>
    /** Whether the viewer has joined at least one course ΓÇö picks which onboarding copy shows. */
    hasCourses?: boolean
    /** Fires when the onboarding CTA is pressed ΓÇö the connected file resolves the route. */
    onBrowseCourses: () => void
    labels: ContinueLearningLabels
}

/**
 * "Continue learning" content ΓÇö the single most important next-action slot: a capped
 * set of resume cards, CONTENT-FIRST (recently-read lessons lead, mixed with at
 * most one in-progress challenge as a nudge). When the viewer has nothing to resume
 * it shows an onboarding CTA instead of an empty void ΓÇö a DESIGNED case, not
 * `AsyncContent`'s generic empty branch, so it stays in the content tree. `isSkeleton`
 * threads to the grid; while shimmering it shows {@link RESUME_LIMIT} placeholder
 * cards in the SAME grid shape as the loaded state. `ResumeCard` (its own connected
 * component under `./ResumeCard`, split.md) forwards no `isSkeleton` of its own ΓÇö it
 * has none yet ΓÇö so the loading cards are mirrored inline with `Skeleton.*` right
 * where it sits instead (loading-and-skeleton.md).
 * @param props - {@link ContinueLearningProps}
 */
export const _ContinueLearning = ({
    isSkeleton = false,
    resumeItems = [],
    hasCourses = false,
    onBrowseCourses,
    labels,
}: ContinueLearningProps) => {
    // missingSkeletonSupport: ResumeCard/ContinueCard take no `isSkeleton` prop, so the
    // loading cards are a hand-mirrored `SectionCard` shell echoing ContinueCard's `item`
    // anatomy (title + subtitle column, then the CTA on its own row, no progress meter).
    const gridItems: ReadonlyArray<GridItem> = isSkeleton
        ? Array.from({ length: RESUME_LIMIT }, (_unused, index) => ({
            key: `pending-${index}`,
            content: () => (
                <SectionCard fillHeight>
                    <StackV gap={3} items={[
                        () => (
                            <StackV gap={1} items={[
                                () => <Skeleton.Typography type="body-sm" width="3/4" />,
                                () => <Skeleton.Typography type="body-xs" width="1/2" />,
                            ]} />
                        ),
                        () => <Skeleton.Typography type="body-sm" width="1/3" />,
                    ]} />
                </SectionCard>
            ),
        }))
        : resumeItems.map((item) => ({
            key: item.globalId,
            content: () => <ResumeCard item={item} />,
        }))

    return isSkeleton || resumeItems.length > 0 ? (
        <Grid
            items={gridItems}
            columns={{ sm: 2, lg: 3 }}
            principle="sibling-stack"
            explain="Same-kind peer stack ΓÇö not group-boundary, because these items are repeating siblings rather than section groups."
            isSkeleton={isSkeleton}
            identity={{ tier: "block", component: "ContinueLearning" }}
        />
    ) : (
        // empty / onboarding: a real card so it matches the framed sibling sections
        // (the parent LabeledCard is `frameless` for the self-framed resume cards).
        // unownedRoot: SectionCard (composite tier) always names itself and takes no
        // `identity` prop ΓÇö no sibling frame wraps it here, so this branch keeps no
        // `data-tier`/`data-component` for ContinueLearning itself (see _identity.ts).
        <SectionCard contentAlign="start">
            <Typography
                size="sm"
                color="muted"
                text={hasCourses ? labels.resumeEmpty : labels.coursesEmpty}
            />
            <Button variant="primary" label={labels.browseCourses} onPress={onBrowseCourses} />
        </SectionCard>
    )
}

"use client"

import React, {
    useCallback,
} from "react"
import {
    useLocale,
    useTranslations,
} from "next-intl"
import {
    useRouter,
} from "next/navigation"
import {
    pathConfig,
} from "@/resources/path"
import {
    useResumeItems,
} from "@/hooks/useResumeItems"
import { _ContinueLearning } from "./component"

/**
 * "Continue learning" content ΓÇö the CONNECTED half (see `tiers/split.md`): self-fetches
 * its leaf queries via {@link useResumeItems}, resolves every label, and hands them to
 * the presentational {@link _ContinueLearning}. Content only (the parent
 * {@link import("@/components/blocks").LabeledCard} frames it; the greeting lives
 * in the identity column). Takes no props ΓÇö self-contained, no escape hatch (BLOCK-4).
 */
export const ContinueLearning = () => {
    const t = useTranslations()
    const locale = useLocale()
    const router = useRouter()
    const {
        resumeItems,
        hasCourses,
        isLoading,
    } = useResumeItems()

    /** Onboarding CTA ΓÇö jumps to the course catalog. */
    const onBrowseCourses = useCallback(
        () => router.push(pathConfig().locale(locale).course().build()),
        [router, locale],
    )

    return (
        <_ContinueLearning
            isSkeleton={isLoading}
            resumeItems={resumeItems}
            hasCourses={hasCourses}
            onBrowseCourses={onBrowseCourses}
            labels={{
                resumeEmpty: t("DashboardPage.continueResumeEmpty"),
                coursesEmpty: t("DashboardPage.emptyCourses"),
                browseCourses: t("DashboardPage.browseCourses"),
            }}
        />
    )
}

"use client"

import React from "react"
import { Tabs } from "@heroui/react"
import {
    HouseIcon,
    CompassIcon,
    GraduationCapIcon,
    TrophyIcon,
} from "@phosphor-icons/react"
import { useTranslations } from "next-intl"
import { DASHBOARD_TABS } from "@/modules/types/dashboard-tabs"
import type { DashboardTab } from "@/modules/types/dashboard-tabs"
import { ExtendedTabs } from "@/components/blocks/navigation/ExtendedTabs"
import { useDashboardTabStore } from "@/hooks/zustand/dashboardTab/store"
import { Box } from "@/components/frames/Box"
import { StackH } from "@/components/frames/Stack"

/** Leading icon shown on each DashboardPage tab, keyed by tab id. */
const TAB_ICONS: Record<DashboardTab, typeof HouseIcon> = {
    overview: HouseIcon,
    explore: CompassIcon,
    courses: GraduationCapIcon,
    community: TrophyIcon,
}

/** Props for {@link DashboardTabsBar}. */
export type DashboardTabsBarProps = Record<string, never>
/**
 * Full-width DashboardPage tab strip (mirror of the profile page's `ProfileTabsBar`).
 * Registered as the global Navbar's bottom layer ({@link useRegisterNavbarBottomLayer}),
 * so the Navbar renders it flush under its primary row and owns the single bottom
 * border + sticky ΓÇö this strip carries none of its own. Native HeroUI secondary
 * Tabs (foreground text + accent underline); the open tab lives in the shared
 * store so panels stay in sync. Mobile = icon only; label shows from `md` up.
 * @param props - optional root class name (placement only)
 */
export const DashboardTabsBar = () => {
    const t = useTranslations()
    const { tab, setTab } = useDashboardTabStore()

    return (
        <div className={"w-full"}>
            {/* page-pad owns the horizontal inset; py stays 0 so the strip hugs the navbar */}
            <Box principle="page-pad" className="w-full px-6"
                explain="Page chrome inset ΓÇö not card-padding, because this pads the whole page rather than a nested card surface.">
                <ExtendedTabs
                    selectedKey={tab}
                    onSelectionChange={(key) => setTab(key as DashboardTab)}
                >
                    <Tabs.ListContainer>
                        <Tabs.List aria-label={t("DashboardPage.title")}>
                            {DASHBOARD_TABS.map((tabId) => {
                                const TabIcon = TAB_ICONS[tabId]
                                return (
                                    <Tabs.Tab
                                        key={tabId}
                                        id={tabId}
                                        aria-controls={`DashboardPage-panel-${tabId}`}
                                    >
                                        <StackH
                                            principle="icon-text"
                                            explain="Icon beside its label ΓÇö not name-handle, because this pairs a glyph with text rather than a name/handle identity."
                                            items={[
                                                () => (
                                                    <TabIcon
                                                        aria-hidden
                                                        focusable="false"
                                                        className="size-5 shrink-0"
                                                    />
                                                ),
                                                () => (
                                                    <span className="hidden @app-md:inline">
                                                        {t(`DashboardPage.tabs.${tabId}`)}
                                                    </span>
                                                ),
                                            ]}
                                        />
                                        <Tabs.Indicator />
                                    </Tabs.Tab>
                                )
                            })}
                        </Tabs.List>
                    </Tabs.ListContainer>
                </ExtendedTabs>
            </Box>
        </div>
    )
}

import React from "react"
import { AsyncContentError } from "@/components/composites/async/AsyncContent"
import { ProgressMeter } from "@/components/composites/stats/ProgressMeter"
import { StatGridCard, type StatGridCardItem } from "@/components/composites/stats/StatGridCard"
import { Typography } from "@/components/atoms/text/Typography"
import { StackV } from "@/components/frames/Stack"
import { KPI_ICON_MAP } from "@/modules/utils/weekly-goals-map"
import type { KpiKey } from "@/modules/api/graphql/queries/types/my-kpis"

/** One weekly-metric row, already resolved by the connected {@link import("./index").WeeklyGoals}. */
export interface WeeklyGoalsItem {
    /** Which weekly metric this row is. */
    key: KpiKey
    /** Already-localized metric label. */
    label: string
    /** This week's value so far. */
    current: number
    /** Effective target ΓÇö the learner's custom goal, or the sensible default. */
    target: number
    /** Already-localized coin-reward hint; omitted when no target is set server-side. */
    coinRewardText?: string
    /** `true` ΓåÆ this metric's reward can be claimed right now. */
    canClaim: boolean
}

/** All display text, already localized by the connected `WeeklyGoals`; a story passes i18n keys. */
export interface WeeklyGoalsLabels {
    /** Title on the error branch. */
    errorTitle: string
    /** Retry-button label, paired with `onRetry`. */
    retry: string
}

/** Props for {@link _WeeklyGoals} ΓÇö presentational; all data resolved, no fetch/store/i18n. */
export interface WeeklyGoalsProps {
    /** First load, nothing in hand ΓåÆ the whole tree shimmers in place (co-located). Owned by the connected file. */
    isSkeleton?: boolean
    /** Truthy ΓåÆ the error message (beats a stale loading flag). The connected file passes its settled fetch error. */
    error?: unknown
    /** Retry handler, paired with `labels.retry` to show a retry button on the error branch. */
    onRetry?: () => void
    /** All six weekly metrics, in display order. No empty state ΓÇö this is always the fixed six-metric set. */
    items: Array<WeeklyGoalsItem>
    /** The composite summary sentence (percent/completed/total, plus the reset countdown when known), already interpolated. */
    summaryText?: string
    labels: WeeklyGoalsLabels
}

/**
 * One metric cell's content: a `ProgressMeter` carrying the icon+label / ratio row in its own
 * `leading`/`trailing` slots (same idiom as the sibling `AiQuotaCard` block), then an optional
 * coin-reward hint below it.
 */
const renderGoalCell = (item: WeeklyGoalsItem, isSkeleton: boolean) => (
    <StackV gap={3} principle="sibling-stack"
        explain="Same-kind peer stack ΓÇö not group-boundary, because these items are repeating siblings rather than section groups."
        isSkeleton={isSkeleton} items={[
        // ATOM GAP: `ProgressMeter`'s discriminated `isSkeleton` union needs a literal branch
        // to narrow at compile time ΓÇö a runtime boolean can't satisfy it directly.
            () => (isSkeleton
                ? (
                    <ProgressMeter
                        isSkeleton
                        leading={() => <Typography size="sm" prefixIcon={KPI_ICON_MAP[item.key]} isSkeleton text={item.label} />}
                        trailing={() => <Typography size="xs" color="muted" tabularNums isSkeleton text={`${item.current}/${item.target}`} />}
                    />
                )
                : (
                    <ProgressMeter
                        value={item.current}
                        max={item.target > 0 ? item.target : 1}
                        color="accent"
                        leading={() => <Typography size="sm" prefixIcon={KPI_ICON_MAP[item.key]} text={item.label} />}
                        trailing={() => <Typography size="xs" color="muted" tabularNums text={`${item.current}/${item.target}`} />}
                    />
                )),
            // coin-reward hint ΓÇö only once a REAL target is set server-side, and never while
            // shimmering (unknown yet whether this row will show one ΓÇö same as the loaded shape
            // it mirrors, `WeeklyGoalsProps.items` never carries a reward while `isSkeleton`).
            ...(!isSkeleton && item.coinRewardText ? [() => (
                <Typography
                    size="xs"
                    color={item.canClaim ? "accent-soft" : "muted"}
                    text={item.coinRewardText}
                />
            )] : []),
        ]} />
)

/**
 * "Weekly goals" content ΓÇö the presentational half of {@link import("./index").WeeklyGoals}: the
 * composite weekly-goal summary + a per-metric breakdown (lessons / study-days / challenges /
 * coding / flashcards / milestones), each with a progress meter against its effective target.
 * Content only ΓÇö the caller's `LabeledCard` frames it.
 *
 * `error` beats a stale loading flag (BLOCK-8): it falls to the shared `AsyncContentError` frame,
 * otherwise the fixed six-metric tree renders with `isSkeleton` threaded to every leaf so the
 * shimmer mirrors the loaded shape (loading-and-skeleton.md). No `isEmpty` state ΓÇö `items` is
 * always the fixed six-metric set, so there is nothing to be empty. See `tiers/split.md` ΓÇö the
 * connected `index.tsx` owns the fetch and i18n.
 *
 * @param props - {@link WeeklyGoalsProps}
 */
export const _WeeklyGoals = ({
    isSkeleton = false,
    error,
    onRetry,
    items,
    summaryText,
    labels,
}: WeeklyGoalsProps) => {
    if (error) {
        return <AsyncContentError title={labels.errorTitle} onRetry={onRetry} retryLabel={labels.retry} />
    }

    const gridItems: Array<StatGridCardItem> = items.map((item) => ({
        key: item.key,
        content: () => renderGoalCell(item, isSkeleton),
    }))

    return (
        <StackV gap={3} isSkeleton={isSkeleton} identity={{ tier: "block", component: "WeeklyGoals" }} items={[
            () => <Typography size="sm" weight="medium" isSkeleton={isSkeleton} text={summaryText} />,
            () => <StatGridCard items={gridItems} />,
        ]} />
    )
}

"use client"

import React, {
    useMemo,
} from "react"
import {
    useTranslations,
} from "next-intl"
import {
    _WeeklyGoals,
    type WeeklyGoalsItem,
} from "./component"
import {
    DEFAULT_KPI_TARGETS,
    KPI_ORDER,
} from "@/modules/utils/weekly-goals-map"
import { useQueryMyKpisSwr } from "@/hooks/swr/api/graphql/queries/useQueryMyKpisSwr"
import type { KpiKey, QueryKpiItemData } from "@/modules/api/graphql/queries/types/my-kpis"

/**
 * "Weekly goals" content ΓÇö the CONNECTED half of {@link _WeeklyGoals}: self-fetches the
 * viewer's weekly KPI snapshot, folds it against the sensible per-metric defaults so the
 * summary + meters always track this week's activity (even before a custom goal is set),
 * resolves every label, and hands the resolved rows to the presentational `_WeeklyGoals`.
 * Content only ΓÇö the parent {@link import("@/components/blocks").LabeledCard} frames it.
 * See `tiers/split.md`.
 */
export const WeeklyGoals = () => {
    const t = useTranslations()
    const {
        data: kpis,
        error,
        mutate,
    } = useQueryMyKpisSwr()

    /** Index KPI items by key for O(1) lookup while building rows in display order. */
    const itemByKey = useMemo(
        () => {
            const map = new Map<KpiKey, QueryKpiItemData>()
            for (const item of kpis?.items ?? []) {
                map.set(item.key, item)
            }
            return map
        },
        [
            kpis,
        ],
    )

    /** Days/hours left until the weekly reset (computed from `resetAt`). Mirrors WeeklyBoard. */
    const countdown = useMemo(
        () => {
            if (!kpis) {
                return null
            }
            const remaining = Math.max(0, new Date(kpis.resetAt).getTime() - Date.now())
            return {
                days: Math.floor(remaining / 86_400_000),
                hours: Math.floor((remaining % 86_400_000) / 3_600_000),
            }
        },
        [kpis],
    )

    // composite over EFFECTIVE targets (custom OR default) so the summary + meters
    // always track this week's activity, even before a custom goal is set.
    const composite = useMemo(() => {
        let completed = 0
        let sumCurrent = 0
        let sumTarget = 0
        for (const key of KPI_ORDER) {
            const item = itemByKey.get(key)
            const current = item?.current ?? 0
            const target = item?.target ?? DEFAULT_KPI_TARGETS[key]
            sumTarget += target
            sumCurrent += Math.min(current, target)
            if (current >= target) {
                completed += 1
            }
        }
        return {
            completed,
            total: KPI_ORDER.length,
            percent: sumTarget > 0 ? Math.round((sumCurrent / sumTarget) * 100) : 0,
        }
    }, [itemByKey])

    const items: Array<WeeklyGoalsItem> = KPI_ORDER.map((key) => {
        const item = itemByKey.get(key)
        const current = item?.current ?? 0
        // effective target = the learner's custom goal, or a sensible default
        // (so the meter tracks this week's activity out of the box)
        const target = item?.target ?? DEFAULT_KPI_TARGETS[key]
        return {
            key,
            label: t(`DashboardPage.kpi.labels.${key}`),
            current,
            target,
            // only once a REAL target is set server-side (the client-only default above
            // doesn't persist a floor/reward)
            coinRewardText: item?.coinReward != null
                ? t("DashboardPage.kpi.coinReward", { count: item.coinReward })
                : undefined,
            canClaim: item?.canClaim ?? false,
        }
    })

    const summaryText = `${t("DashboardPage.kpi.summary", {
        percent: composite.percent,
        completed: composite.completed,
        total: composite.total,
    })}${countdown
        ? ` ┬╖ ${t("DashboardPage.kpi.resetIn", {
            days: countdown.days,
            hours: countdown.hours,
        })}`
        : ""}`

    return (
        <_WeeklyGoals
            // first load, nothing in hand ΓåÆ shimmer; settled (data OR error) stops it (loading-and-skeleton.md)
            isSkeleton={!kpis && !error}
            error={error}
            onRetry={() => { void mutate() }}
            items={items}
            summaryText={summaryText}
            labels={{
                errorTitle: t("DashboardPage.loadError"),
                retry: t("DashboardPage.retry"),
            }}
        />
    )
}

"use client"

import React, {
    useMemo,
} from "react"
import {
    useDashboardTabUrlSync,
} from "@/hooks/useDashboardTabUrlSync"
import {
    DashboardTabsBar,
} from "./DashboardTabsBar"
import {
    DashboardIdentity,
} from "./DashboardIdentity"
import {
    OverviewTab,
} from "./OverviewTab"
import {
    ExploreTab,
} from "./ExploreTab"
import {
    CoursesTab,
} from "./CoursesTab"
import {
    CommunityTab,
} from "./CommunityTab"
import { useDashboardTabStore } from "@/hooks/zustand/dashboardTab/store"
import { useRegisterNavbarBottomLayer } from "@/hooks/zustand/navbarBottomLayer/store"
import { Container } from "@/components/frames/Container"
import { RailShell } from "@/components/frames/RailShell"

/** Props for {@link DashboardPage}. */
export type DashboardPageProps = Record<string, never>
/**
 * Logged-in home ΓÇö rebuilt on the proven PROFILE page layout: a tab strip rendered
 * as the navbar's bottom layer, then a centered 2-column body ΓÇö left = the viewer's identity +
 * standing (bare, stable across tabs), right = the selected tab's content. Tabs:
 * Overview (cockpit) ┬╖ Explore (feed) ┬╖ Courses ┬╖ Community. The open tab lives in
 * the shared store and mirrors `?tab=` (shareable); only the active panel mounts,
 * so each tab's leaf queries fetch lazily. Mobile stacks the identity then the
 * content (no rail, no drawer). `"use client"` for the tab store + URL sync.
 * @param props - optional className for the root element
 */
export const DashboardPage = () => {
    useDashboardTabUrlSync()
    const tab = useDashboardTabStore((state) => state.tab)
    // the DashboardPage tab strip renders as the global Navbar's bottom layer
    const tabsNode = useMemo(() => <DashboardTabsBar />, [])
    useRegisterNavbarBottomLayer(tabsNode)

    // RailShell owns the identity<->content layout seam (stack -> row at md, gap-8).
    const rail = () => <DashboardIdentity />
    const body = () => {
        if (tab === "overview") {
            return (
                <div
                    id="DashboardPage-panel-overview"
                    role="tabpanel"
                    aria-labelledby="overview"
                >
                    <OverviewTab />
                </div>
            )
        }
        if (tab === "explore") {
            return (
                <div
                    id="DashboardPage-panel-explore"
                    role="tabpanel"
                    aria-labelledby="explore"
                >
                    <ExploreTab />
                </div>
            )
        }
        if (tab === "courses") {
            return (
                <div
                    id="DashboardPage-panel-courses"
                    role="tabpanel"
                    aria-labelledby="courses"
                >
                    <CoursesTab />
                </div>
            )
        }
        if (tab === "community") {
            return (
                <div
                    id="DashboardPage-panel-community"
                    role="tabpanel"
                    aria-labelledby="community"
                >
                    <CommunityTab />
                </div>
            )
        }
        return null
    }

    return (
        <div className={"flex w-full flex-col"}>
            {/* tab strip is registered as the Navbar bottom layer above (not here) */}
            <Container
                size="xl"
                padding={6}
                identity={{ tier: "block", component: "DashboardPage" }}
                body={() => (
                    <RailShell
                        at="md"
                        principle="layout-split"
                        explain="Major layout split ΓÇö not block-boundary, because this separates primary page regions rather than adjacent blocks."
                        rail={rail}
                        body={body}
                    />
                )}
            />
        </div>
    )
}

"use client"

import React from "react"
import useSWR from "swr"
import { useLocale, useTranslations } from "next-intl"
import { useRouter } from "next/navigation"
import { DUE_REVIEW_LIMIT } from "@/modules/utils/flashcards"
import { useStartFlashcardDueReviewSession } from "@/hooks/useStartFlashcardDueReviewSession"
import { queryMyDueFlashcards } from "@/modules/api/graphql/queries/query-my-due-flashcards"
import { useAppSelector } from "@/redux/hooks"
import { useQueryMyInProgressFlashcardDueReviewSessionSwr } from "@/hooks/swr/api/graphql/queries/useQueryMyInProgressFlashcardDueReviewSessionSwr"
import { pathConfig } from "@/resources/path"
import { _DueReviewHero } from "./component"

/**
 * The flashcards home hero: the spaced-repetition queue. Shows how many cards are due today
 * across every enrolled course and offers the page's PRIMARY action ΓÇö starting a review
 * session. When nothing is due it collapses to a caught-up empty state. This is the
 * CONNECTED half ΓÇö it fetches the due queue (and the resumable cross-deck run) directly from
 * the shared `myDueFlashcards` SWR key, resolves every label, and hands them to the
 * presentational {@link _DueReviewHero}. See `tiers/split.md`.
 *
 * Takes no props: the previous `className` was never used by its one call site
 * (`FlashcardsPage/index.tsx`, `<DueReviewHero />`) and a block hands out no `className` escape
 * hatch once it composes entirely through frames (`ContinueCard`'s own doc makes the same
 * call) ΓÇö see `apiChanged` in this migration's report.
 */
export const DueReviewHero = () => {
    const t = useTranslations()
    const locale = useLocale()
    const router = useRouter()
    // scope the due queue to THIS course (the count must reflect this course's
    // decks, not every deck system-wide); shared SWR key with {@link DueReview}.
    const courseId = useAppSelector((state) => state.course.entity?.id)
    const displayId = useAppSelector((state) => state.course.displayId)

    const { data, error, mutate } = useSWR(
        ["my-due-flashcards", courseId ?? null, DUE_REVIEW_LIMIT],
        async () => {
            const response = await queryMyDueFlashcards({ request: { courseId, limit: DUE_REVIEW_LIMIT } })
            return response.data?.myDueFlashcards.data ?? null
        },
    )

    // eager resolve-or-start right from the CTA (per the teacher's note, 2026-07-11:
    // "pressing the learn button should show isPending right on that button, reviewing
    // 55 cards is also isPending, and once the session is created it routes into the
    // same page as quick-learn") ΓÇö the button stays
    // ON this screen, pending, until a real sessionId comes back; no more
    // instant navigation to the bare `?session=due` shim + full-page skeleton.
    const { start: startDueReview, starting } = useStartFlashcardDueReviewSession(courseId)
    const onPressStart = async () => {
        if (!displayId) {
            return
        }
        const cardIds = (data?.cards ?? []).map((dueCard) => dueCard.cardId)
        const sessionId = await startDueReview(cardIds)
        if (sessionId) {
            router.push(pathConfig().locale(locale).course(displayId).learn().flashcards().due(sessionId).build())
        }
    }

    // resumable cross-deck "Due today" run ΓÇö mirrors QuizSession's own "Zone 0" resume
    // card. Renders like the mock-interview resume card (per the teacher's note, 2026-07-17:
    // "render exactly like Mock Interview"): a progress meter (`value`), NO clock watermark ΓÇö
    // the `card {current}/{total}` progress carries "in progress".
    const resumeSwr = useQueryMyInProgressFlashcardDueReviewSessionSwr(courseId)
    const resumeData = resumeSwr.data

    const dueCount = data?.dueCount ?? 0
    const dueReviewCount = data?.dueReviewCount ?? 0
    const newCount = data?.newCount ?? 0

    return (
        <_DueReviewHero
            // first load, nothing in hand ΓåÆ shimmer; settled (data OR error) stops it (loading-and-skeleton.md)
            isSkeleton={!data && !error}
            isEmpty={dueCount === 0}
            error={error}
            onRetry={() => { void mutate() }}
            starting={starting}
            onPressStart={() => { void onPressStart() }}
            resume={resumeData && displayId ? {
                title: t("flashcard.due.resumeTitle"),
                subtitle: t("flashcard.due.resumeSubtitle", {
                    current: resumeData.currentIndex + 1,
                    total: resumeData.cardIds.length,
                }),
                value: resumeData.currentIndex + 1,
                max: resumeData.cardIds.length,
                ctaLabel: t("flashcard.due.resumeCta"),
                onPress: () => router.push(
                    pathConfig().locale(locale).course(displayId).learn().flashcards().due(resumeData.sessionId).build(),
                ),
            } : undefined}
            labels={{
                sectionLabel: t("flashcard.due.label"),
                // NOTE: reuses the "no flashcards for this course" copy for the error title ΓÇö
                // carried over verbatim from the pre-migration code, which had no dedicated
                // `flashcard.due.error` key either; not this migration's call to fix.
                errorTitle: t("flashcard.empty"),
                allCaughtTitle: t("flashcard.due.allCaught"),
                allCaughtHint: t("flashcard.due.allCaughtHint"),
                count: t("flashcard.due.count", { count: dueCount }),
                countBreakdown: dueReviewCount > 0 && newCount > 0
                    ? t("flashcard.due.countBreakdown", { overdue: dueReviewCount, newCapped: newCount })
                    : undefined,
                start: t("flashcard.due.start", { count: dueCount }),
            }}
        />
    )
}

"use client"

import React, { useCallback, useEffect, useMemo, useRef, useState } from "react"
import useSWR, { useSWRConfig } from "swr"
import { useTranslations } from "next-intl"
import { usePathname, useRouter } from "next/navigation"
import { DUE_REVIEW_LIMIT, SM2_GRADES } from "@/modules/utils/flashcards"
import { _DueReview, type DueReviewCard, type DueReviewLabels } from "./component"
import { mutateReviewFlashcard } from "@/modules/api/graphql/mutations/mutation-review-flashcard"
import { queryMyDueFlashcards } from "@/modules/api/graphql/queries/query-my-due-flashcards"
import { GraphQLHeadersKey, type GraphQLHeaders } from "@/modules/api/graphql/types"
import { useQueryFlashcardCardsByIdsSwr } from "@/hooks/swr/api/graphql/queries/useQueryFlashcardCardsByIdsSwr"
import { useMutateStartFlashcardDueReviewSessionSwr } from "@/hooks/swr/api/graphql/mutations/useMutateStartFlashcardDueReviewSessionSwr"
import { useMutateSyncFlashcardDueReviewSessionProgressSwr } from "@/hooks/swr/api/graphql/mutations/useMutateSyncFlashcardDueReviewSessionProgressSwr"
import { useMutateCompleteFlashcardDueReviewSessionSwr } from "@/hooks/swr/api/graphql/mutations/useMutateCompleteFlashcardDueReviewSessionSwr"
import { useQueryMyInProgressFlashcardDueReviewSessionSwr } from "@/hooks/swr/api/graphql/queries/useQueryMyInProgressFlashcardDueReviewSessionSwr"
import { useQueryMyFlashcardReviewSessionBySessionIdSwr } from "@/hooks/swr/api/graphql/queries/useQueryMyFlashcardReviewSessionBySessionIdSwr"
import { useGraphQLWithToast } from "@/modules/toast/hooks"
import { useAppSelector } from "@/redux/hooks"

/** Props for {@link DueReview}. */
export interface DueReviewProps {
    /** Leave the session and return to the flashcards home. */
    onExit: () => void
    /**
     * Present when reached via the dedicated `flashcards/review/sessions/[sessionId]`
     * route ΓÇö this component then hydrates straight from THAT session (no
     * resolve-or-start call) instead of resolving one itself. Absent when
     * reached via the bare `review?session=due` route (teacher's 2026-07-11
     * correction: "due review should also create a new session" ΓÇö that bare route is now a
     * RESOLVE-ONLY shim: it resolves-or-starts a session then `router.push`es
     * into the sessioned URL (teacher: keep the history entry, don't use `.replace`),
     * mirroring `FlashcardReviewer`'s own idiom).
     * Mirrors `FlashcardReviewerProps.sessionId`.
     */
    sessionId?: string
}

/**
 * The spaced-repetition (SM-2) review session over the viewer's due cards, drawn
 * across every enrolled course ΓÇö the CONNECTED half: it fetches the due queue,
 * runs the resolve-or-start/resume state machine, resolves every label (incl.
 * interpolation), and hands them to the presentational {@link _DueReview}. The
 * due count is the page's primary loop, so this is the main entry from the home
 * hero. See `tiers/split.md`.
 * @param props - {@link DueReviewProps}
 */
export const DueReview = ({ onExit, sessionId }: DueReviewProps) => {
    const t = useTranslations()
    const router = useRouter()
    const pathname = usePathname()
    const runGraphQL = useGraphQLWithToast()
    const { mutate: globalMutate } = useSWRConfig()
    // scope the due queue to THIS course; shared SWR key with the hero (DueReviewHero)
    const courseId = useAppSelector((state) => state.course.entity?.id)
    const dueKey = useMemo(
        () => ["my-due-flashcards", courseId ?? null, DUE_REVIEW_LIMIT] as const,
        [courseId],
    )
    // index of the card currently shown + whether its answer is revealed
    const [currentIndex, setCurrentIndex] = useState(0)
    const [revealed, setRevealed] = useState(false)
    // true while a grade is in flight (blocks the rating bar)
    const [reviewing, setReviewing] = useState(false)
    // how many cards were graded this session (shown in the summary)
    const [reviewedCount, setReviewedCount] = useState(0)
    // WHICH card positions have been graded this session (0-indexed, order-
    // independent) ΓÇö drives the progress bar's per-segment green so a card
    // graded out of order (free-nav jump ahead ΓåÆ grade ΓåÆ jump back) still
    // reads green (2026-07-12, teacher: free-nav "both before and after"). A Set for
    // O(1) membership; persisted as an array via `gradedIndexes` sync so a
    // resume rehydrates it.
    const [gradedIndexes, setGradedIndexes] = useState<Set<number>>(() => new Set())
    // explicit "Finish" ΓÇö end the session now regardless of position, distinct
    // from reaching the last card. Feeds `done` below.
    const [finished, setFinished] = useState(false)

    // the due queue (count + first batch of cards), shared key with the hero
    const { data, isLoading, error, mutate } = useSWR(dueKey, async () => {
        const response = await queryMyDueFlashcards({ request: { courseId, limit: DUE_REVIEW_LIMIT } })
        return response.data?.myDueFlashcards.data ?? null
    })

    const cards = data?.cards ?? []

    // session-persistence (mirrors QuizSession's/FlashcardReviewer's resumable-session
    // idiom, scoped cross-deck by enrollment only ΓÇö no deckId, unlike the single-deck
    // reviewer): each rating is already saved immediately via `reviewFlashcard` (safe),
    // but WHICH batch/position within it was not persisted, so leaving mid-batch used
    // to lose the in-batch progress. `startFlashcardDueReviewSession` /
    // `syncFlashcardDueReviewSessionProgress` / `completeFlashcardDueReviewSession`
    // wrap that sequence with a resumable cursor, now with its OWN resumable URL too
    // (teacher's 2026-07-11 correction: "due review should also create a new session" ΓÇö parity with
    // `FlashcardReviewer`'s own 2026-07-11 correction; superseding the earlier same-day
    // "silently, no new UI/route" note).
    const courseHeaders = useMemo<GraphQLHeaders | undefined>(
        () => (courseId ? { [GraphQLHeadersKey.XCourseId]: courseId } : undefined),
        [courseId],
    )
    const runStartSession = useMutateStartFlashcardDueReviewSessionSwr()
    const runSyncSession = useMutateSyncFlashcardDueReviewSessionProgressSwr()
    const runCompleteSession = useMutateCompleteFlashcardDueReviewSessionSwr()
    // no-`sessionId` shim route only: MRU "is there a resumable draw at all"
    // lookup, used to resolve-or-start before a sessioned URL exists yet.
    const inProgressSessionSwr = useQueryMyInProgressFlashcardDueReviewSessionSwr(courseId)
    // sessioned route: resolve THIS EXACT session by id (not an MRU guess) ΓÇö
    // mirrors the identical fix in `FlashcardReviewer` (2026-07-12: "this one
    // glitches too"). The old code reused `inProgressSessionSwr` here too and
    // manually checked `resumeData.sessionId === sessionId` as a workaround for
    // using the wrong query.
    const sessionByIdSwr = useQueryMyFlashcardReviewSessionBySessionIdSwr(sessionId, courseId)
    // whichever of the two above is the resumable-session SOURCE OF TRUTH for
    // this render ΓÇö by-id when we have a concrete sessionId, MRU otherwise.
    const resumableSessionData = sessionId ? sessionByIdSwr.data : inProgressSessionSwr.data
    const resumableSessionLoading = sessionId ? sessionByIdSwr.isLoading : inProgressSessionSwr.isLoading
    // status-agnostic re-fetch of the resumable session's OWN cards, by exact id ΓÇö
    // NOT filtered by "due today" like `cards` above. Feeds `applyResume` below: a
    // card already graded THIS run gets rescheduled (SM-2) and drops out of the due
    // queue instantly, so matching purely against `cards` silently lost it on resume
    // (misaligning `currentIndex`, or failing resume outright once enough cards had
    // been graded ΓÇö 2026-07-12, teacher: "why is it rendering this page" ΓåÆ traced to a
    // reload-after-grading orphaning the session). `nextIntervals` isn't part of this
    // shape (only the live due query carries it) ΓÇö `applyResume` falls back to
    // `undefined` for a card resolved this way, which `RatingBar`'s optional `hint`
    // already renders as "no preview" instead of crashing.
    const resumeCardIds = resumableSessionData?.cardIds ?? []
    const resumeCardsByIdSwr = useQueryFlashcardCardsByIdsSwr(resumeCardIds, courseId)
    // when a resumable session is found, the fetched due batch is reordered/filtered
    // to match its persisted `cardIds` (never re-drawn) ΓÇö null while resuming didn't
    // apply (fresh draw, or no resumable session), in which case the raw fetched
    // `cards` above is used as-is. `nextIntervals` optional (not `QueryMyDueFlashcardData`'s
    // own required field) ΓÇö see `resumeCardsByIdSwr` comment above.
    const [resumedCards, setResumedCards] = useState<Array<DueReviewCard> | null>(null)
    // server-issued id for the current batch ΓÇö set once on start OR resume
    const sessionIdRef = useRef<string | null>(null)
    // guards the one-shot resolve-or-start effect to run its work at most once
    // per mount (prevents a duplicate `start` call on re-render).
    const resolveAttemptedRef = useRef(false)
    // STATE, separate from the ref above ΓÇö `isSkeleton` below reads THIS, so the
    // shimmer stays up until the resumed cards/cursor are ACTUALLY applied, not
    // just until the underlying query settled (2026-07-12 fix: closes a 1-frame
    // flash ΓÇö card 1 appears, then jumps to the real resume position). Stays
    // false on the redirect-away paths (fresh session / no-sessionId shim) ΓÇö the
    // shimmer correctly holds through the navigation.
    const [resolveApplied, setResolveApplied] = useState(false)
    // guards the one-shot completion call on reaching `done`
    const completedRef = useRef(false)

    const effectiveCards = resumedCards ?? cards
    const card = effectiveCards[currentIndex]
    // complete when the learner explicitly ends it ("Finish") OR steps past
    // the last card. With free navigation "past the last card" is no longer the
    // only finish path, so the explicit `finished` flag is the primary one.
    const done = effectiveCards.length > 0 && (finished || currentIndex >= effectiveCards.length)

    /**
     * Hydrate from an in-progress session's persisted batch/cursor; false if none
     * of its cards resolve. Looks up the LIVE due queue FIRST (carries
     * `nextIntervals`), falling back to the status-agnostic by-id fetch
     * (`resumeCardsByIdSwr`) for a card already graded this run ΓÇö grading
     * reschedules a card (SM-2) OUT of "due" immediately, so a due-only lookup
     * silently dropped it, corrupting the resumed order/cursor (2026-07-12 fix).
     */
    const applyResume = useCallback(
        (resumeData: { sessionId: string, cardIds: Array<string>, currentIndex: number, reviewedCount: number, gradedIndexes?: Array<number> }): boolean => {
            const dueById = new Map(cards.map((dueCard) => [dueCard.cardId, dueCard]))
            const byId = new Map((resumeCardsByIdSwr.data ?? []).map((idCard) => [idCard.cardId, idCard]))
            const ordered = resumeData.cardIds
                .map((cardId): DueReviewCard | undefined => dueById.get(cardId) ?? byId.get(cardId))
                .filter((resolvedCard): resolvedCard is DueReviewCard => Boolean(resolvedCard))
            if (ordered.length === 0) {
                return false
            }
            sessionIdRef.current = resumeData.sessionId
            setResumedCards(ordered)
            setResolveApplied(true)
            // every card in the batch was already graded (`reviewedCount` reaches
            // the batch size) but `status` never flipped to "completed" ΓÇö the
            // earlier completion call never landed (2026-07-12, same root cause
            // traced in `QuizSession`: "already submitted but F5 goes back to the last question"). Clamping
            // `currentIndex` to `ordered.length - 1` here would ALWAYS re-show the
            // last card (an index at the last position can't tell "about to
            // answer" from "just answered" apart) ΓÇö set it to the FULL length
            // instead so `done` computes true immediately and the "finish" effect
            // below retries completion, instead of clamping into the last card
            // every time this session gets revisited.
            setCurrentIndex(
                resumeData.reviewedCount >= ordered.length
                    ? ordered.length
                    : Math.min(resumeData.currentIndex, ordered.length - 1),
            )
            setReviewedCount(resumeData.reviewedCount)
            // rehydrate the graded-set from the resumed session; fall back to
            // "first N contiguous" when the backend didn't send it (older row
            // synced before `gradedIndexes` existed) so green isn't lost.
            setGradedIndexes(
                resumeData.gradedIndexes && resumeData.gradedIndexes.length > 0
                    ? new Set(resumeData.gradedIndexes)
                    : new Set(Array.from({ length: resumeData.reviewedCount }, (_, i) => i)),
            )
            completedRef.current = false
            return true
        },
        [cards, resumeCardsByIdSwr.data],
    )

    // start a fresh session over the batch just drawn, then redirect into its
    // sessioned URL ΓÇö mirrors `FlashcardReviewer`'s own `startSessionAndRedirect`.
    // Routed through `runGraphQL` (toast on failure, no success toast) instead of a
    // silent catch (teacher, 2026-07-11: "FE shouldn't swallow errors, use runGraphQL").
    // the bare `.../review` base, with any existing `/sessions/<id>` segment
    // stripped ΓÇö so redirecting into a session NEVER appends a second
    // `/sessions/...` when we're already on a sessioned URL (the revisit-crash:
    // `.../sessions/A//sessions/B`). Reached via either route, this resolves to
    // the same base.
    const reviewBasePath = pathname.replace(/\/sessions\/[^/]+\/?$/, "")

    const startSessionAndRedirect = useCallback(async () => {
        if (!courseId) {
            return
        }
        const ok = await runGraphQL(
            async () => {
                const started = await runStartSession.trigger({
                    request: { courseId, cardIds: cards.map((dueCard) => dueCard.cardId) },
                    headers: courseHeaders as GraphQLHeaders,
                })
                const response = started.data?.startFlashcardDueReviewSession
                if (response?.data?.sessionId) {
                    sessionIdRef.current = response.data.sessionId
                }
                return response ?? { success: false, message: t("flashcard.review.error") }
            },
            { showSuccessToast: false },
        )
        if (ok && sessionIdRef.current) {
            router.replace(`${reviewBasePath}/sessions/${sessionIdRef.current}`)
        }
    }, [courseId, cards, courseHeaders, runStartSession, runGraphQL, router, reviewBasePath, t])

    // resolve-or-start, once the batch + the in-progress query have both settled ΓÇö TWO
    // routes into this component (mirrors `FlashcardReviewer`'s own 2026-07-11 shim):
    // (a) reached via the dedicated `review/sessions/[sessionId]` route (`sessionId`
    //     prop set) ΓåÆ hydrate straight from THAT session; a stale/invalid id falls
    //     back to (b) instead of getting stuck.
    // (b) reached via the bare `review?session=due` route (`sessionId` absent) ΓåÆ
    //     resume the caller's existing draw if one exists, otherwise start a fresh
    //     one, THEN redirect into the sessioned URL.
    useEffect(() => {
        if (
            resolveAttemptedRef.current
            || !courseId
            || cards.length === 0
            || resumableSessionLoading
            // there IS a session to resume ΓÇö wait for its status-agnostic by-id
            // cards to settle too, so `applyResume` can fall back to them for an
            // already-graded card the due queue no longer carries (see
            // `resumeCardsByIdSwr` above).
            || (resumableSessionData && resumeCardsByIdSwr.isLoading)
        ) {
            return
        }
        resolveAttemptedRef.current = true
        const resumeData = resumableSessionData

        if (sessionId) {
            // `resumableSessionData` was resolved BY id when `sessionId` is set
            // (see `sessionByIdSwr` above) ΓÇö no need to re-check `.sessionId`.
            if (resumeData && applyResume(resumeData)) {
                return
            }
            // stale/invalid session id ΓÇö start a fresh one and correct the URL
            void startSessionAndRedirect()
            return
        }

        if (resumeData && applyResume(resumeData)) {
            router.replace(`${reviewBasePath}/sessions/${resumeData.sessionId}`)
            return
        }
        void startSessionAndRedirect()
    }, [
        sessionId,
        courseId,
        cards,
        resumableSessionLoading,
        resumableSessionData,
        resumeCardsByIdSwr.isLoading,
        applyResume,
        startSessionAndRedirect,
        router,
        reviewBasePath,
    ])

    // finish: record the finished batch once (guarded), best-effort ΓÇö a failed
    // complete call only means the row stays "in_progress" (still resumable),
    // it never blocks the learner from leaving. Routed through `runGraphQL`
    // (teacher, 2026-07-11: "FE shouldn't swallow errors, use runGraphQL") instead of a
    // silent catch.
    useEffect(() => {
        if (!done || completedRef.current || !sessionIdRef.current) {
            return
        }
        completedRef.current = true
        const completingSessionId = sessionIdRef.current
        void (async () => {
            await runGraphQL(
                async () => {
                    const result = await runCompleteSession.trigger({
                        request: { sessionId: completingSessionId, reviewedCount, xpEarned: 0 },
                        headers: courseHeaders as GraphQLHeaders,
                    })
                    return (
                        result.data?.completeFlashcardDueReviewSession ?? {
                            success: false,
                            message: t("flashcard.review.error"),
                        }
                    )
                },
                { showSuccessToast: false },
            )
            // whether it succeeded or the toast surfaced a failure, drop the
            // saving state and hand off to the dedicated result route (reads
            // events directly by sessionId, independent of the session row's
            // status ΓÇö "done" is now answered by the URL, not re-derived
            // client-side; see `.../result/page.tsx` doc for the root cause).
            // the due count changed ΓÇö refresh the queue so the home hero reads correctly
            // whenever the learner navigates back there.
            void globalMutate(dueKey)
            router.replace(`${reviewBasePath}/sessions/${completingSessionId}/result`)
        })()
    }, [done, reviewedCount, runCompleteSession, courseHeaders, runGraphQL, t, router, reviewBasePath, globalMutate, dueKey])

    // SM-2 grade buttons for the current card: localized label + next-interval
    // preview ("4 days") computed server-side from the card's current state
    const ratingOptions = useMemo(() => {
        const intervals = card?.nextIntervals
        // map a grade to its previewed next-interval in days
        const daysForGrade = (grade: number): number | undefined => {
            if (!intervals) {
                return undefined
            }
            return [intervals.again, intervals.hard, intervals.good, intervals.easy][grade]
        }
        return SM2_GRADES.map((grade) => {
            const days = daysForGrade(grade.grade)
            return {
                grade: grade.grade,
                label: t(grade.labelKey),
                hint: days === undefined ? undefined : t("flashcard.review.intervalDays", { count: days }),
            }
        })
    }, [t, card])

    // grade the current card, reschedule it (SM-2), then advance to the next
    // presentational callback contract is sync ΓÇö fire-and-forget from the click via void.
    const onRate = useCallback(
        async (grade: number) => {
            if (!card) {
                return
            }
            setReviewing(true)
            // a success toast per card would be noise ΓÇö only surface failures
            const ok = await runGraphQL(
                async () => {
                    const response = await mutateReviewFlashcard({
                        // thread the live session id so the review event links to
                        // this session ΓÇö powers the per-session stats aggregate.
                        request: { cardId: card.cardId, grade, sessionId: sessionIdRef.current ?? undefined },
                    })
                    return (
                        response.data?.reviewFlashcard ?? {
                            success: false,
                            message: t("flashcard.review.error"),
                        }
                    )
                },
                { showSuccessToast: false },
            )
            setReviewing(false)
            if (ok) {
                // mark THIS position graded (set dedupes a re-grade) ΓÇö the source
                // of truth for both the per-segment green and the reviewed count.
                const nextGraded = new Set(gradedIndexes).add(currentIndex)
                const nextReviewedCount = nextGraded.size
                const nextIndex = currentIndex + 1
                setGradedIndexes(nextGraded)
                setReviewedCount(nextReviewedCount)
                setRevealed(false)
                setCurrentIndex(nextIndex)
                // best-effort, fire-and-forget persistence for resume ΓÇö never blocks
                // advancing to the next card; still routed through `runGraphQL`
                // (toast on failure, no success toast) rather than a silent catch
                // (teacher, 2026-07-11: "FE shouldn't swallow errors, use runGraphQL").
                if (sessionIdRef.current) {
                    const syncingSessionId = sessionIdRef.current
                    void runGraphQL(
                        async () => {
                            const result = await runSyncSession.trigger({
                                request: {
                                    sessionId: syncingSessionId,
                                    currentIndex: nextIndex,
                                    reviewedCount: nextReviewedCount,
                                    gradedIndexes: Array.from(nextGraded),
                                    xpEarned: 0,
                                },
                                headers: courseHeaders as GraphQLHeaders,
                            })
                            return (
                                result.data?.syncFlashcardDueReviewSessionProgress ?? {
                                    success: false,
                                    message: t("flashcard.review.error"),
                                }
                            )
                        },
                        { showSuccessToast: false },
                    ).then(() => {
                        // invalidate the Hub's "Review in progress" (ContinueCard) cache ΓÇö
                        // it reads THIS exact key, and nothing else was invalidating it
                        // per-grade (only on completion, see the `done` effect below) ΓÇö
                        // so a revisit to the Hub mid-session showed a stale currentIndex
                        // from whenever that card first mounted, not the position just
                        // synced here (2026-07-12, teacher: "pressing the back button returns to 2 while it's
                        // actually at 5" ΓÇö the DB was correct the whole time; only this cache
                        // was stale, verified directly against Postgres).
                        if (courseId) {
                            void globalMutate(["QUERY_MY_IN_PROGRESS_FLASHCARD_DUE_REVIEW_SESSION_SWR", courseId])
                        }
                    })
                }
            }
        },
        [card, runGraphQL, t, currentIndex, gradedIndexes, runSyncSession, courseHeaders, courseId, globalMutate],
    )
    // step back to re-see an earlier card (question side; no re-grade) ΓÇö mirrors
    // `FlashcardReviewer`'s own `goPrev` (teacher: sync the UI, both session types should
    // have a "Previous" button, due-review was previously missing this button).
    const isFirst = currentIndex === 0
    const isLast = currentIndex >= effectiveCards.length - 1
    const goPrev = useCallback(() => {
        setRevealed(false)
        setCurrentIndex((index) => Math.max(index - 1, 0))
    }, [])
    // "Next" ΓÇö explicit, symmetric counterpart to "Previous": browse forward
    // WITHOUT grading (mirrors `FlashcardReviewer`'s own `goNext`, teacher,
    // 2026-07-12: "next prev" flanking the primary "Show answer" CTA).
    const goNext = useCallback(() => {
        setRevealed(false)
        setCurrentIndex((index) => Math.min(index + 1, effectiveCards.length - 1))
    }, [effectiveCards.length])
    // jump straight to ANY step from the progress-segment bar ΓÇö free navigation,
    // "both before and after, even ones not reached yet can be clicked" (2026-07-12). No re-grade; the
    // card's graded/green state is independent of which one you're viewing.
    const goToIndex = useCallback((position: number) => {
        setRevealed(false)
        setCurrentIndex(position)
    }, [])
    // end the session now ΓåÆ the completion effect (`done`) fires + navigates to
    // results. Distinct from "Exit" (back-link: leave, keep resumable).
    const onFinish = useCallback(() => setFinished(true), [])
    const onReveal = useCallback(() => setRevealed(true), [])

    // first load, nothing in hand ΓåÆ shimmer (loading-and-skeleton.md ┬º2); also holds through the
    // due-review resolve-or-start/resume state machine (forced skeleton while the bare
    // `?session=due` shim resolves-or-starts a session and redirects, and ΓÇö once the batch has
    // loaded ΓÇö until the resumed cursor has actually been APPLIED, not just until its underlying
    // query settled, closing a 1-frame flash: card 1 appears, then jumps to the real resume position).
    const isSkeleton = (isLoading && !data) || (!sessionId && cards.length > 0) || (Boolean(sessionId) && cards.length > 0 && !resolveApplied)
    const isEmpty = cards.length === 0

    const levelLabel = card?.level ? t(`flashcard.level.${card.level}`) : undefined

    const labels: DueReviewLabels = {
        exit: t("flashcard.exit"),
        modeTitle: t("flashcard.mode.due"),
        counter: t("flashcard.cardProgress", {
            current: done ? effectiveCards.length : currentIndex + 1,
            total: effectiveCards.length,
        }),
        finish: t("flashcard.finish"),
        savingLabel: t("flashcard.review.stats.savingLabel"),
        // NB: keeps the pre-existing (mismatched) copy verbatim ΓÇö "No flashcards for this course
        // yet." doubling as the due-queue error title predates this split, unchanged here.
        errorTitle: t("flashcard.empty"),
        emptyTitle: t("flashcard.due.allCaught"),
        emptyDescription: t("flashcard.due.allCaughtHint"),
        questionLabel: t("flashcard.questionLabel"),
        answerLabel: t("flashcard.answerLabel"),
        rateHint: t("flashcard.review.rateHint"),
        rateAria: t("flashcard.review.rateAria"),
        showAnswer: t("flashcard.showAnswer"),
        previous: t("flashcard.previous"),
        next: t("flashcard.next"),
    }

    return (
        <_DueReview
            isSkeleton={isSkeleton}
            isEmpty={isEmpty}
            error={error}
            onRetry={() => { void mutate() }}
            onBack={onExit}
            done={done}
            card={card}
            levelLabel={levelLabel}
            revealed={revealed}
            onReveal={onReveal}
            reviewing={reviewing}
            ratingOptions={ratingOptions}
            onRate={(grade) => { void onRate(grade) }}
            currentIndex={currentIndex}
            totalCount={effectiveCards.length}
            gradedIndexes={Array.from(gradedIndexes)}
            isFirst={isFirst}
            isLast={isLast}
            onSegmentClick={goToIndex}
            onPrev={goPrev}
            onNext={goNext}
            onFinish={onFinish}
            labels={labels}
        />
    )
}

"use client"

import React, { useCallback, useEffect, useMemo, useState } from "react"
import useSWR from "swr"
import { useLocale, useTranslations } from "next-intl"
import { useRouter } from "next/navigation"
import { _FlashcardDeckList, type DeckView } from "./component"
import { queryFlashcardDecksByCourse } from "@/modules/api/graphql/queries/query-flashcard-decks-by-course"
import { type FlashcardDeckEntity } from "@/modules/types/entities/flashcard-deck"
import { useAppSelector } from "@/redux/hooks"
import { pathConfig } from "@/resources/path"
import { useStartFlashcardReviewSession } from "@/hooks/useStartFlashcardReviewSession"
import type { FlashcardReviewMode } from "@/modules/api/graphql/mutations/types/start-flashcard-review-session"

/** Decks shown per page in the topic list before the pager kicks in. */
const DECKS_PER_PAGE = 10

/** localStorage key persisting the chosen deck view across sessions. */
const VIEW_STORAGE_KEY = "starci.flashcard.deckView"

/** Props for {@link FlashcardDeckList}. */
export interface FlashcardDeckListProps {
    /** Called with the chosen deck id when the learner opens a deck. */
    onSelectDeck: (deckId: string) => void
    /** CTA label on each deck card. Defaults to the study label. */
    ctaLabel?: string
    /** Show the per-viewer spaced-repetition chrome (due chip + mastery meter).
     * The quiz tab passes `false` ΓÇö SR state is irrelevant when picking a
     * topic to drill aloud. Defaults to `true`. */
    showProgress?: boolean
}

/**
 * Lists the flashcard decks owned by the active course as a topic picker, shared
 * by both the study and quiz tabs ΓÇö the CONNECTED half: it fetches the decks,
 * owns the search/pager/view UI state, resolves every label, and hands them to
 * the presentational {@link _FlashcardDeckList}. See `tiers/split.md`.
 *
 * @param props - {@link FlashcardDeckListProps}
 */
export const FlashcardDeckList = ({
    onSelectDeck,
    ctaLabel,
    showProgress = true,
}: FlashcardDeckListProps) => {
    const t = useTranslations()
    const locale = useLocale()
    const router = useRouter()
    // read the owning course id from the store ΓÇö no prop drilling needed
    const courseId = useAppSelector((state) => state.course.entity?.id)
    const displayId = useAppSelector((state) => state.course.displayId)
    // eager resolve-or-start (teacher 2026-07-11: "pressing Study should show
    // isPending on the study button itself ... once the session is created,
    // router push into the same page as quick study") ΓÇö only meaningful in the study ("Study cards") context; a
    // hypothetical future reuse with `showProgress={false}` (picking a deck for
    // something OTHER than a review session) falls back to `onSelectDeck`.
    const { start: startReview, startingDeckId } = useStartFlashcardReviewSession(courseId)
    // deck whose review-mode modal is open (teacher 2026-07-13: "Study" opens a modal to choose
    // full/forgotten-only before entering), null = closed. Held as the whole deck so the modal
    // reads its title + total + dueCount without a re-fetch.
    const [modeDeck, setModeDeck] = useState<FlashcardDeckEntity | null>(null)
    // live search query filtering decks by title/description
    const [query, setQuery] = useState("")
    // 1-based page for the client-side deck pager
    const [page, setPage] = useState(1)
    // grid (default) vs line layout; hydrated from localStorage after mount (SSR-safe)
    const [view, setView] = useState<DeckView>("grid")
    useEffect(() => {
        const saved = window.localStorage.getItem(VIEW_STORAGE_KEY)
        if (saved === "grid" || saved === "line") {
            setView(saved)
        }
    }, [])
    const onChangeView = useCallback((next: DeckView) => {
        setView(next)
        try {
            window.localStorage.setItem(VIEW_STORAGE_KEY, next)
        } catch {
            // storage unavailable (private mode) ΓÇö view simply won't persist
        }
    }, [])

    // fetch the decks for this course; null key suspends until the course hydrates
    const { data, isLoading, error, mutate } = useSWR(
        courseId ? ["flashcard-decks-by-course", courseId] : null,
        async () => {
            const response = await queryFlashcardDecksByCourse({
                request: { courseId: courseId as string },
            })
            return response.data?.flashcardDecksByCourse.data ?? null
        },
    )

    const decks = data ?? []

    // decks in display order, narrowed by the (case-insensitive) search query
    const filteredDecks = useMemo(() => {
        const sorted = [...decks].sort((prev, next) => prev.sortIndex - next.sortIndex)
        const normalized = query.trim().toLowerCase()
        if (!normalized) {
            return sorted
        }
        return sorted.filter((deck) => {
            const haystack = `${deck.title ?? ""} ${deck.description ?? ""}`.toLowerCase()
            return haystack.includes(normalized)
        })
    }, [decks, query])

    // paginate the filtered decks client-side
    const totalPages = Math.max(1, Math.ceil(filteredDecks.length / DECKS_PER_PAGE))
    // a new search shrinks the list ΓÇö snap back to the first page
    useEffect(() => {
        setPage(1)
    }, [query])
    const pagedDecks = filteredDecks.slice((page - 1) * DECKS_PER_PAGE, page * DECKS_PER_PAGE)

    /** "Study" pressed ΓåÆ open the mode modal (study context), or fall straight
     *  through to `onSelectDeck` for a non-study reuse (`showProgress={false}`). */
    const onPressStart = useCallback(
        (deck: FlashcardDeckEntity) => {
            if (!showProgress || !displayId) {
                onSelectDeck(deck.id)
                return
            }
            setModeDeck(deck)
        },
        [showProgress, displayId, onSelectDeck],
    )
    /** Chosen a mode in the modal ΓåÆ resolve-or-start with that scope, then
     *  `router.push` into the live session (mirrors the old eager idiom, now
     *  gated behind the modal's "Start"). */
    const onStartWithMode = useCallback(
        async (mode: FlashcardReviewMode) => {
            if (!modeDeck || !displayId) {
                return
            }
            const cardIds = (modeDeck.cards ?? []).map((deckCard) => deckCard.id)
            const sessionId = await startReview(modeDeck.id, cardIds, mode)
            if (sessionId) {
                setModeDeck(null)
                router.push(
                    pathConfig().locale(locale).course(displayId).learn().flashcards().due(sessionId).build(),
                )
            }
        },
        [modeDeck, displayId, startReview, router, locale],
    )
    /** Modal close ΓÇö blocked while ITS OWN deck is mid-start (mirrors the old inline check). */
    const onModalClose = useCallback(() => {
        if (!modeDeck || startingDeckId !== modeDeck.id) {
            setModeDeck(null)
        }
    }, [modeDeck, startingDeckId])

    return (
        <_FlashcardDeckList
            // first load, nothing in hand ΓåÆ shimmer (loading-and-skeleton.md); same formula as before
            isSkeleton={(isLoading || !courseId) && decks.length === 0}
            isEmpty={decks.length === 0}
            // only a settled fetch error (no cached decks to fall back on) reaches the block
            error={decks.length === 0 ? error : undefined}
            onRetry={() => { void mutate() }}
            showProgress={showProgress}
            ctaLabel={ctaLabel}
            pagedDecks={pagedDecks}
            filteredCount={filteredDecks.length}
            query={query}
            onQueryChange={setQuery}
            view={view}
            onViewChange={onChangeView}
            page={page}
            totalPages={totalPages}
            onPageChange={setPage}
            onPressStart={onPressStart}
            modalDeck={modeDeck}
            onModalClose={onModalClose}
            onModalStart={(mode) => { void onStartWithMode(mode) }}
            isModalPending={modeDeck != null && startingDeckId === modeDeck.id}
            labels={{
                errorTitle: t("flashcard.empty"),
                emptyTitle: t("flashcard.empty"),
                searchPlaceholder: t("flashcard.searchPlaceholder"),
                foundCount: t("flashcard.deck.found", { count: filteredDecks.length }),
                searchEmptyMessage: t("flashcard.searchEmpty", { query: query.trim() }),
                viewAria: t("flashcard.deck.viewAria"),
                viewGrid: t("flashcard.deck.viewGrid"),
                viewLine: t("flashcard.deck.viewLine"),
                study: t("flashcard.study"),
                difficultyLabel: (difficulty) => t(`flashcard.difficulty.${difficulty}`),
                dueLabel: (count) => t("flashcard.deck.due", { count }),
                masteredLabel: (mastered, total) => t("flashcard.deck.mastered", { mastered, total }),
                cardCountLabel: (count) => t("flashcard.cardCount", { count }),
            }}
        />
    )
}

"use client"

import React from "react"
import { useTranslations } from "next-intl"
import { useFlashcardNav, type FlashcardMode } from "@/hooks/useFlashcardNav"
import { TabsCard } from "@/components/blocks/navigation/TabsCard"

/** Props for {@link FlashcardMobileNav}. */
export type FlashcardMobileNavProps = Record<string, never>
/**
 * Mobile (`<lg`) fallback for the flashcards LEFT RAIL ΓÇö which is hidden on
 * small screens. Surfaces the mode switch (Study / Quiz) the rail owns,
 * driving the URL via {@link useFlashcardNav} so the rail (desktop) and this
 * bar (mobile) stay in sync. Rendered `@app-lg:hidden` above the work pane.
 *
 * The horizontal deck-chip picker this bar used to ALSO surface (a mobile
 * form of the rail's deck list) was removed (teacher, 2026-07-09: "remove this
 * on mobile") ΓÇö `FlashcardDeckList` already gives the overview a proper
 * deck picker, so the chip row was a redundant second way to jump decks.
 * @param props - {@link FlashcardMobileNavProps}
 */
export const FlashcardMobileNav = () => {
    const t = useTranslations()
    const { mode, goMode } = useFlashcardNav()

    return (
        <div className={"flex flex-col gap-3 @app-lg:hidden"}>
            {/* page-FEATURE switch (mirrors the desktop rail's own mode control, see
                FlashcardsPage/index.tsx) ΓåÆ TabsCard variant="primary"
                (fe/components/tabs.md ┬º0b, corrected 2026-07-09). */}
            <TabsCard
                variant="primary"
                leftTabs={{
                    items: [
                        { key: "study", label: t("flashcard.mode.study") },
                        { key: "quiz", label: t("flashcard.mode.quiz") },
                    ],
                    selectedKey: mode,
                    ariaLabel: t("flashcard.title"),
                    onSelectionChange: (key) => goMode(key as FlashcardMode),
                }}
            />
        </div>
    )
}

"use client"

import React, { useState } from "react"
import { Button, Chip, Label, Spinner, Typography } from "@heroui/react"
import { CaretLeftIcon, CaretRightIcon, LockIcon } from "@phosphor-icons/react"
import { MarkdownContent } from "@/components/blocks/rendering/MarkdownContent"
import { AsyncContentEmpty, AsyncContentError } from "@/components/composites/async/AsyncContent"
import { SurfaceCard } from "@/components/composites/cards/SurfaceCard"
import { WorkSessionHeader } from "@/components/blocks/navigation/WorkSessionHeader"
import { ConfirmDialog } from "@/components/composites/feedback/ConfirmDialog"
import { FlipCard } from "@/components/blocks/cards/FlipCard"
import { SectionCard } from "@/components/blocks/cards/SectionCard"
import { RatingBar, type RatingOption } from "@/components/blocks/buttons/RatingBar"
import { Skeleton } from "@/components/blocks/skeleton/Skeleton"
import { Box } from "@/components/frames/Box"
import { Cluster } from "@/components/frames/Cluster"
import { Container } from "@/components/frames/Container"
import { StackH, StackV } from "@/components/frames/Stack"
import { LEVEL_COLOR } from "@/modules/utils/flashcards"
import type { WithClassNames } from "@/modules/types/base/class-name"
import { type FlashcardCardEntity } from "@/modules/types/entities/flashcard-card"

/** How many segments the header's progress meter mirrors while shimmering. */
const HEADER_SKELETON_SEGMENT_COUNT = 6

/** How many placeholder chips the level/tag row mirrors while shimmering. */
const SKELETON_CHIP_COUNT = 2

/** Every translated string {@link _FlashcardReviewer} needs ΓÇö resolved by the connected `FlashcardReviewer`. */
export interface FlashcardReviewerLabels {
    /** `WorkSessionHeader`'s back-link label, both branches. */
    exit: string
    /** `WorkSessionHeader`'s mode title, both branches. */
    title: string
    /** Already-interpolated "card N/total" ΓÇö the connected file resolves the pair per `done`. */
    counter: string
    /** Under the spinner in the transient "saving" hand-off (`done` branch). */
    savingLabel: string
    leaveTitle: string
    finishEarlyTitle: string
    leaveConfirm: string
    finishEarlyConfirm: string
    leaveCta: string
    finishEarlyCta: string
    stayIn: string
    questionLabel: string
    answerLabel: string
    premiumLockedTitle: string
    premiumLockedHint: string
    noAnswer: string
    premiumCta: string
    rateHint: string
    rateAria: string
    showAnswer: string
    previous: string
    next: string
    finishEarly: string
    /** Shared by both the empty and the error branch (mirrors the original, which used one key for both). */
    emptyTitle: string
}

/** Props for {@link _FlashcardReviewer} ΓÇö presentational; every value already resolved by `index.tsx`. */
export interface FlashcardReviewerProps extends WithClassNames<undefined> {
    /** First load, nothing in hand yet (deck query + session resolve both settled) ΓÇö the whole tree shimmers in place. */
    isSkeleton?: boolean
    /** Settled, sessioned, and the resolved card list is empty. */
    isEmpty?: boolean
    /** Truthy ΓåÆ the error message (beats loading + empty). */
    error?: unknown
    /** Retries the deck query. */
    onRetry?: () => void
    /** Every translated string this tree draws. */
    labels: FlashcardReviewerLabels

    /** Deck title, once the deck query resolves. */
    deckTitle?: string
    /**
     * Past the last card (or explicitly finished) ΓÇö the transient "saving" hand-off
     * before the completion mutation resolves and the caller navigates to the result route.
     */
    done: boolean

    /** 0-indexed position of the card currently shown. */
    currentIndex: number
    /** Total cards in this review run. */
    totalCards: number
    /** The card currently shown; absent only transiently (e.g. `done`). */
    card?: FlashcardCardEntity
    /** Translated label for `card.level`, resolved by the connected file (dynamic i18n key). */
    cardLevelLabel?: string
    /** A premium card withheld from a non-enrolled viewer. */
    isLocked: boolean
    isFirst: boolean
    isLast: boolean
    /** Whether the answer side is currently shown. */
    revealed: boolean
    /** True while a grade mutation is in flight ΓÇö disables the rating bar. */
    reviewing: boolean
    /** Positions already graded (order-independent) ΓÇö drives the header's per-segment green. */
    gradedIndexes: ReadonlyArray<number>
    /** SM-2 grade options, already localized with their next-interval preview. */
    ratingOptions: Array<RatingOption>

    /** Returns to the study overview. */
    onBack?: () => void
    /** Reveals the answer side of the current card. */
    onReveal: () => void
    /** Grades the current card and advances. */
    onRate: (grade: number) => void
    onPrev: () => void
    onNext: () => void
    /** Free-navigation: jump straight to any step from the progress-segment bar. */
    onSegmentClick: (position: number) => void
    /** Ends the run now (past the confirm dialog). */
    onFinishEarly: () => void
    /** Opens the course page so the viewer can enrol to unlock premium cards. */
    onUnlock: () => void
}

/**
 * Spaced-repetition reviewer over one deck ΓÇö the presentational half of
 * {@link import("./index").FlashcardReviewer}. Four states in the fixed order
 * error ΓåÆ skeleton ΓåÆ empty ΓåÆ content (`loading-and-skeleton.md`): `error` falls to
 * the shared `AsyncContentError` frame, `isEmpty` to `AsyncContentEmpty`, otherwise
 * the ONE real tree renders with `isSkeleton` threaded through. None of this tree's
 * leaves (`WorkSessionHeader`, `FlipCard`, `SectionCard`, `RatingBar`, `ConfirmDialog`,
 * `MarkdownContent`) take an `isSkeleton` prop of their own, so the shimmer is mirrored
 * INLINE with `Skeleton.*` at the exact spot those leaves would otherwise sit ΓÇö still
 * co-located (same wrapper, same position), not a second parallel tree. See
 * `tiers/split.md` ΓÇö the connected `index.tsx` owns the fetch, the session-resolve
 * effects, and every i18n resolution.
 *
 * @param props - {@link FlashcardReviewerProps}
 */
export const _FlashcardReviewer = ({
    isSkeleton = false,
    isEmpty = false,
    error,
    onRetry,
    labels,
    deckTitle,
    done,
    currentIndex,
    totalCards,
    card,
    cardLevelLabel,
    isLocked,
    isFirst,
    isLast,
    revealed,
    reviewing,
    gradedIndexes,
    ratingOptions,
    onBack,
    onReveal,
    onRate,
    onPrev,
    onNext,
    onSegmentClick,
    onFinishEarly,
    onUnlock,
    className,
}: FlashcardReviewerProps) => {
    // "leave" (Exit) ┬╖ "endEarly" (Finish early) ΓÇö which confirm dialog is open, if any.
    // Pure UI toggle, not fetched/persisted data, so it lives here rather than in the
    // connected file (loading-and-skeleton.md's test: renders with no server/store/session).
    const [confirmAction, setConfirmAction] = useState<null | "leave" | "endEarly">(null)

    // error beats a stale loading flag; empty only once settled (loading-and-skeleton.md ┬º1/┬º6)
    if (error) {
        return <AsyncContentError title={labels.emptyTitle} onRetry={onRetry} />
    }
    if (!isSkeleton && isEmpty) {
        return <AsyncContentEmpty title={labels.emptyTitle} />
    }

    const identity = deckTitle ? { name: deckTitle } : undefined

    const header = isSkeleton ? (
        <Box className="sticky top-16 z-10 border-b border-default bg-surface">
            <StackH
                gap={1}
                padding={{ base: { x: 5, y: 3 }, sm: { x: 6, y: 3 } }}
                principle="pill-pad"
                explain="Pill/chip inset ΓÇö not control-pad, because this pads a compact badge shape rather than a form control."
                items={[() => (
                    <StackH
                        gap={4}
                        principle="content-row"
                        explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                        align="center"
                        divider
                        classNames={["w-full"]}
                        items={[
                            () => <Skeleton className="h-4 w-16 rounded" />,
                            () => (
                                <span className="hidden h-5 w-px shrink-0 bg-default @app-sm:block" aria-hidden />
                            ),
                            () => <Skeleton className="hidden h-4 w-24 rounded @app-sm:block" />,
                            () => (
                                <span className="hidden h-5 w-px shrink-0 bg-default @app-sm:block" aria-hidden />
                            ),
                            () => <Skeleton className="h-4 w-20 rounded" />,
                        ]}
                    />
                )]}
            />
            <Box principle="pill-pad" className="px-4 pb-2 @app-sm:px-6"
                explain="Pill/chip inset ΓÇö not control-pad, because this pads a compact badge shape rather than a form control.">
                <StackH
                    gap={2}
                    classNames={["w-full"]}
                    items={Array.from({ length: HEADER_SKELETON_SEGMENT_COUNT }, (_unused, index) => () => (
                        <Skeleton key={index} className="h-1 flex-1 rounded-full" />
                    ))}
                />
            </Box>
        </Box>
    ) : done ? (
        <WorkSessionHeader
            backLabel={labels.exit}
            onBack={onBack ?? (() => {})}
            title={labels.title}
            identity={identity}
            counter={labels.counter}
            current={totalCards}
            total={totalCards}
        />
    ) : (
        <>
            <WorkSessionHeader
                backLabel={labels.exit}
                onBack={() => setConfirmAction("leave")}
                title={labels.title}
                identity={identity}
                counter={labels.counter}
                current={currentIndex}
                total={totalCards}
                doneSet={gradedIndexes}
                onSegmentClick={onSegmentClick}
                onFinish={() => setConfirmAction("endEarly")}
                finishLabel={labels.finishEarly}
            />
            <ConfirmDialog
                isOpen={confirmAction !== null}
                onOpenChange={(open) => { if (!open) { setConfirmAction(null) } }}
                title={confirmAction === "leave" ? labels.leaveTitle : labels.finishEarlyTitle}
                description={confirmAction === "leave" ? labels.leaveConfirm : labels.finishEarlyConfirm}
                confirmLabel={confirmAction === "leave" ? labels.leaveCta : labels.finishEarlyCta}
                cancelLabel={labels.stayIn}
                onConfirm={() => {
                    const action = confirmAction
                    setConfirmAction(null)
                    if (action === "leave") {
                        onBack?.()
                    } else if (action === "endEarly") {
                        onFinishEarly()
                    }
                }}
            />
        </>
    )

    const cardLevel = card?.level ?? null
    const chipItems = isSkeleton
        ? Array.from({ length: SKELETON_CHIP_COUNT }, () => () => <Skeleton.Chip />)
        : card && (cardLevel || (card.tags?.length ?? 0) > 0)
            ? [
                ...(cardLevel ? [() => (
                    <Chip size="sm" variant="soft" color={LEVEL_COLOR[cardLevel] ?? "default"}>
                        {cardLevelLabel}
                    </Chip>
                )] : []),
                ...(card.tags ?? []).map((tag) => () => (
                    <Chip key={tag} size="sm" variant="soft" color="default">
                        {tag}
                    </Chip>
                )),
            ]
            : []

    const body = isSkeleton ? (
        <Container size="md" padding={1} body={() => (
            <StackV gap={6} items={[
                () => <Cluster gap={3} principle="chip-row"
                    explain="Lets chips share one wrapping row so related tags stay together without stacking as a column."
                    align="center" items={chipItems} />,
                () => (
                    <StackV gap={4} principle="label-field"
                        explain="Form label above its field ΓÇö not title-subtitle, because the upper line labels an input rather than a heading pair."
                        items={[
                            () => <Skeleton.Typography type="body-xs" width="1/4" />,
                            () => (
                                <SurfaceCard padding={6} body={() => (
                                    <StackV gap={4} principle="sibling-stack"
                                        explain="Same-kind peer stack ΓÇö not group-boundary, because these items are repeating siblings rather than section groups."
                                        items={[
                                            () => <Skeleton.Typography type="body" width="3/4" />,
                                            () => <Skeleton.Typography type="body" width="2/3" />,
                                        ]} />
                                )} />
                            ),
                        ]} />
                ),
                () => (
                    <StackH gap={4} principle="flex-action"
                        explain="Groups action controls on one horizontal peer row so they share a single hit baseline."
                        justify="between" align="center" items={[
                            () => <Skeleton.Button />,
                            () => <Skeleton.Button />,
                        ]} />
                ),
            ]} />
        )} />
    ) : done ? (
        <Container size="md" padding={1} body={() => (
            <Box className="py-10">
                <StackV gap={4} align="center" principle="card-caption"
                    explain="Holds caption text under card media so the caption stays attached to the image above it."
                    classNames={["w-full"]} items={[
                        () => <Spinner size="lg" />,
                        () => (
                            <Typography type="body-sm" color="muted">
                                {labels.savingLabel}
                            </Typography>
                        ),
                    ]} />
            </Box>
        )} />
    ) : (
        <Container size="md" padding={1} body={() => (
            <StackV gap={6} items={[
                () => (
                    <FlipCard
                        revealed={revealed}
                        questionLabel={labels.questionLabel}
                        answerLabel={labels.answerLabel}
                        front={() => <MarkdownContent plain markdown={card?.question ?? ""} />}
                        belowFront={chipItems.length > 0 ? () => (
                            <Cluster gap={3} principle="chip-row"
                                explain="Lets chips share one wrapping row so related tags stay together without stacking as a column."
                                align="center" items={chipItems}  />
                        ) : undefined}
                        back={() => (
                            <>
                                {isLocked ? (
                                    <StackV gap={4} principle="sibling-stack"
                                        explain="Same-kind peer stack ΓÇö not group-boundary, because these items are repeating siblings rather than section groups."
                                        align="center" classNames={["flex-1"]} items={[
                                            () => <LockIcon aria-hidden focusable="false" className="size-8 text-muted" />,
                                            () => (
                                                <Typography type="body-sm" weight="semibold">
                                                    {labels.premiumLockedTitle}
                                                </Typography>
                                            ),
                                            () => (
                                                <Typography type="body-xs" color="muted">
                                                    {labels.premiumLockedHint}
                                                </Typography>
                                            ),
                                        ]} />
                                ) : (
                                    <>
                                        {card?.answer ? (
                                            <MarkdownContent plain markdown={card.answer} arcSections />
                                        ) : (
                                            <Typography type="body-sm" color="muted">
                                                {labels.noAnswer}
                                            </Typography>
                                        )}
                                        {card?.explanation ? (
                                            <MarkdownContent plain markdown={card.explanation} />
                                        ) : null}
                                    </>
                                )}
                            </>
                        )}
                    />
                ),
                ...(revealed && isLocked ? [() => (
                    <StackH gap={3} principle="flex-action"
                        explain="Groups action controls on one horizontal peer row so they share a single hit baseline."
                        justify="center" items={[() => (
                            <Button size="sm" variant="primary" onPress={onUnlock}>
                                {labels.premiumCta}
                            </Button>
                        )]} />
                )] : revealed ? [() => (
                    <SectionCard withVerdict={{ enable: true, variant: "accent" }}>
                        <Label>{labels.rateHint}</Label>
                        <RatingBar
                            options={ratingOptions}
                            onRate={onRate}
                            ariaLabel={labels.rateAria}
                            isPending={reviewing}
                        />
                    </SectionCard>
                )] : [() => (
                    <Cluster gap={3} principle="flex-action"
                        explain="Groups action controls on one horizontal peer row so they share a single hit baseline."
                        align="center" items={[
                            () => (
                                <Button size="sm" variant="primary" className="w-full @app-sm:w-auto" onPress={onReveal}>
                                    {labels.showAnswer}
                                </Button>
                            ),
                            () => (
                                <Button
                                    size="sm"
                                    variant="secondary"
                                    isIconOnly
                                    isDisabled={isFirst}
                                    aria-label={labels.previous}
                                    onPress={onPrev}
                                >
                                    <CaretLeftIcon weight="bold" className="size-4" aria-hidden focusable="false" />
                                </Button>
                            ),
                            () => (
                                <Button
                                    size="sm"
                                    variant="secondary"
                                    isIconOnly
                                    isDisabled={isLast}
                                    aria-label={labels.next}
                                    onPress={onNext}
                                >
                                    <CaretRightIcon weight="bold" className="size-4" aria-hidden focusable="false" />
                                </Button>
                            ),
                        ]} />
                )]),
            ]} />
        )} />
    )

    const bodyShell = (
        <Box principle="page-pad" className="px-4 pb-6 pt-10 @app-sm:px-6"
            explain="Page chrome inset ΓÇö not card-padding, because this pads the whole page rather than a nested card surface."
        >{body}</Box>
    )

    return (
        <Box className={className}>
            <StackV
                gap={1}
                identity={{ tier: "block", component: "FlashcardReviewer" }}
                items={[
                    () => header,
                    () => bodyShell,
                ]}
            />
        </Box>
    )
}

"use client"

import React, { useCallback, useEffect, useMemo, useRef, useState } from "react"
import useSWR, { useSWRConfig } from "swr"
import { useTranslations, useLocale } from "next-intl"
import { usePathname, useRouter } from "next/navigation"
import { SM2_GRADES } from "@/modules/utils/flashcards"
import { _FlashcardReviewer, type FlashcardReviewerLabels } from "./component"
import { mutateReviewFlashcard } from "@/modules/api/graphql/mutations/mutation-review-flashcard"
import { queryFlashcardDeck } from "@/modules/api/graphql/queries/query-flashcard-deck"
import { type FlashcardCardEntity } from "@/modules/types/entities/flashcard-card"
import { useAppSelector } from "@/redux/hooks"
import { useGraphQLWithToast } from "@/modules/toast/hooks"
import { pathConfig } from "@/resources/path"
import { GraphQLHeadersKey } from "@/modules/api/graphql/types"
import { useMutateStartFlashcardReviewSessionSwr } from "@/hooks/swr/api/graphql/mutations/useMutateStartFlashcardReviewSessionSwr"
import { useMutateSyncFlashcardReviewSessionProgressSwr } from "@/hooks/swr/api/graphql/mutations/useMutateSyncFlashcardReviewSessionProgressSwr"
import { useMutateCompleteFlashcardReviewSessionSwr } from "@/hooks/swr/api/graphql/mutations/useMutateCompleteFlashcardReviewSessionSwr"
import { useQueryMyInProgressFlashcardReviewSessionSwr } from "@/hooks/swr/api/graphql/queries/useQueryMyInProgressFlashcardReviewSessionSwr"
import { useQueryMyFlashcardReviewSessionBySessionIdSwr } from "@/hooks/swr/api/graphql/queries/useQueryMyFlashcardReviewSessionBySessionIdSwr"

/** Props for {@link FlashcardReviewer}. */
export interface FlashcardReviewerProps {
    /** Deck id being reviewed. */
    deckId: string
    /**
     * Present when reached via the dedicated, resumable
     * `flashcards/review/decks/[deckId]/sessions/[sessionId]` route ΓÇö this
     * component then hydrates straight from THAT session (no resolve-or-start
     * call) instead of resolving one itself. Absent when reached via the bare
     * `.../decks/[deckId]` route (teacher 2026-07-11 correction: "so the review
     * session gets saved" ΓÇö that bare route is now a RESOLVE-ONLY shim: it resolves-or-starts a
     * session then `router.push`es into the sessioned URL, mirroring
     * `QuizSession`'s `startSession` ΓåÆ `router.push` idiom). Mirrors
     * `QuizSessionProps.resumeSessionId`.
     */
    sessionId?: string
    /** Returns to the study overview (due + mastery + deck list). Passed straight
     *  through as `WorkSessionHeader`'s `onBack` (mirrors `QuizSession`'s own
     *  `exitToSetup` ΓÇö teacher 2026-07-09: "neither the review nor the quiz
     *  section has a back button"). */
    onBack?: () => void
}

/**
 * Rehydrate the graded-position set from a resumed session: prefer the
 * server's `gradedIndexes` (order-independent, exact), else fall back to
 * "first `reviewedCount` contiguous" for an older row synced before the
 * column existed ΓÇö so green isn't lost on resume of a legacy session.
 */
const seedGradedSet = (resumed: { gradedIndexes?: Array<number>, reviewedCount: number }): Set<number> =>
    resumed.gradedIndexes && resumed.gradedIndexes.length > 0
        ? new Set(resumed.gradedIndexes)
        : new Set(Array.from({ length: resumed.reviewedCount }, (_, i) => i))

/**
 * Spaced-repetition reviewer over one deck ΓÇö the CONNECTED half: it owns the deck
 * fetch, the resumable-session resolve/sync/complete wiring, every piece of local
 * run state (current card, reveal, grading), and every i18n resolution, then hands
 * fully-resolved props to the presentational {@link _FlashcardReviewer}. One card at
 * a time: the Markdown question on the front, flipped to reveal the model answer
 * plus optional depth, then graded for recall (Again / Hard / Good / Easy) ΓÇö each
 * grade reschedules the card via `reviewFlashcard` (SM-2) and advances. Previous
 * steps back to re-grade; a summary closes the run. See `tiers/split.md`.
 * @param props - {@link FlashcardReviewerProps}
 */
export const FlashcardReviewer = ({ deckId, sessionId, onBack }: FlashcardReviewerProps) => {
    const t = useTranslations()
    const locale = useLocale()
    const router = useRouter()
    const pathname = usePathname()
    const runGraphQL = useGraphQLWithToast()
    const { mutate: globalMutate } = useSWRConfig()
    // owning course slug drives the deep-links to referenced lessons/modules
    const courseDisplayId = useAppSelector((state) => state.course.displayId)
    // owning course id (uuid) ΓÇö for the review-session mutations' enrollment-guard header
    const courseId = useAppSelector((state) => state.course.entity?.id)
    const courseHeaders = useMemo(
        () => (courseId ? { [GraphQLHeadersKey.XCourseId]: courseId } : undefined),
        [courseId],
    )
    // entitlement: enrolled viewers unlock premium cards (first ~20%/deck stay free)
    const enrolled = useAppSelector((state) => state.user.enrolled)
    // index of the card currently shown
    const [currentIndex, setCurrentIndex] = useState(0)
    // whether the current card is flipped to its answer side
    const [revealed, setRevealed] = useState(false)
    // true while a grade is in flight (blocks the rating bar)
    const [reviewing, setReviewing] = useState(false)
    // how many cards were graded this run (shown in the summary)
    const [reviewedCount, setReviewedCount] = useState(0)
    // WHICH card positions have been graded (0-indexed, order-independent) ΓÇö
    // drives the progress bar's per-segment green under free navigation
    // (2026-07-12; mirrors `DueReview`). Persisted via `gradedIndexes` sync.
    const [gradedIndexes, setGradedIndexes] = useState<Set<number>>(() => new Set())
    // explicit "Finish" ΓÇö end the run now regardless of position.
    const [finished, setFinished] = useState(false)
    // confirm-before-exit ("leave"/"endEarly" dialog toggle) is pure UI chrome ΓÇö
    // it now lives as local state in the presentational `_FlashcardReviewer`
    // (loading-and-skeleton.md's test: no server/store/session needed to render it).

    // load the full deck graph (cards with question + answer)
    const { data, isLoading, error, mutate } = useSWR(
        ["flashcard-deck", deckId],
        async () => {
            const response = await queryFlashcardDeck({
                request: { flashcardDeckId: deckId },
            })
            return response.data?.flashcardDeck.data ?? null
        },
    )

    // ΓöÇΓöÇ resumable review session (2026-07-09: "always save the session to
    // build stats" ΓÇö mirrors QuizSession's own start/sync/complete/resume wiring,
    // scoped to this ONE deck instead of the whole course) ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
    const runStartSession = useMutateStartFlashcardReviewSessionSwr()
    const runSyncSession = useMutateSyncFlashcardReviewSessionProgressSwr()
    const runCompleteSession = useMutateCompleteFlashcardReviewSessionSwr()
    // no-`sessionId` shim route only: MRU "is there a resumable draw at all"
    // lookup, used to resolve-or-start before a sessioned URL exists yet.
    const inProgressSessionSwr = useQueryMyInProgressFlashcardReviewSessionSwr(deckId, courseId)
    // sessioned route: resolve THIS EXACT session by id (not an MRU guess) ΓÇö
    // fixes a visible jank on load (2026-07-12: "this one jitters too"). The
    // old code reused `inProgressSessionSwr` here too and manually checked
    // `resumable.sessionId === sessionId` as a workaround for using the wrong
    // query; worse, that query's `isLoading` wasn't part of the `isSkeleton`
    // gate below, so the skeleton could resolve before `currentIndex` was set,
    // flashing card 1 before jumping to the real resume position.
    const sessionByIdSwr = useQueryMyFlashcardReviewSessionBySessionIdSwr(sessionId, courseId)

    // cards in review order. When a session resolves, its PERSISTED `cardIds` is
    // the source of truth for WHICH cards + their order ΓÇö so "Due cards only"
    // ("due" mode, teacher 2026-07-13) actually shows only its narrowed subset
    // instead of the whole deck. Order follows the session's `cardIds` exactly
    // (a card id no longer in the deck is dropped). Before a session exists (the
    // bare `?deckId=` shim, which starts a FULL draw), fall back to the whole
    // deck sorted by `sortIndex` ΓÇö that same fallback is what `startSessionAndRedirect`
    // persists for the shim path.
    const sessionCardIds = sessionByIdSwr.data?.cardIds ?? null
    const cards = useMemo<Array<FlashcardCardEntity>>(
        () => {
            const all = [...(data?.cards ?? [])].sort((prev, next) => prev.sortIndex - next.sortIndex)
            if (!sessionCardIds || sessionCardIds.length === 0) {
                return all
            }
            const byId = new Map(all.map((deckCard) => [deckCard.id, deckCard]))
            return sessionCardIds
                .map((id) => byId.get(id))
                .filter((deckCard): deckCard is FlashcardCardEntity => Boolean(deckCard))
        },
        [data?.cards, sessionCardIds],
    )

    // the server-issued session id ΓÇö a ref (not state) since it never drives a render
    const sessionIdRef = useRef<string | null>(null)
    // guards the mount-time resume/start effect so it runs its work at most once
    // per deck (prevents a duplicate `start` call on re-render).
    const initAttemptedRef = useRef(false)
    // STATE, separate from the ref above ΓÇö the `isSkeleton` gate below reads
    // THIS, so the skeleton stays up until `currentIndex`/`reviewedCount` are
    // ACTUALLY set, not just until the underlying query settles (closes a 1-frame
    // flash this component used to show: card 1 appears, then jumps to the real
    // resume position). Stays false on the redirect-away paths (fresh session /
    // no-sessionId shim) ΓÇö the skeleton correctly holds through the navigation.
    const [initResolved, setInitResolved] = useState(false)
    // guards `completeFlashcardReviewSession` so a re-render at `done` never double-fires it
    const completedRef = useRef(false)

    // once the deck's cards AND the in-progress check have both settled ΓÇö TWO
    // routes into this component (2026-07-11 correction: "so the review session gets saved"):
    // (a) reached via the dedicated `.../decks/[deckId]/sessions/[sessionId]`
    //     route (`sessionId` prop set) ΓåÆ hydrate straight from THAT session
    //     (no start call); a stale/invalid id (expired past 24h, or bogus) falls
    //     back to (b) below instead of getting stuck.
    // (b) reached via the bare `.../decks/[deckId]` route (`sessionId` absent)
    //     ΓåÆ this is now a RESOLVE-ONLY shim: resume the caller's existing draw
    //     if one exists, otherwise start a fresh one, THEN `router.push` into
    //     the sessioned URL ΓÇö mirrors `QuizSession`'s own `startSession` ΓåÆ
    //     `router.push` idiom. Never renders the live reviewer itself; `done`
    //     stays false the whole time (the `isSkeleton` gate below covers this
    //     branch), so only the skeleton ever shows here.
    // start a fresh session + redirect into its sessioned URL ΓÇö used by the
    // resolve effect (2 branches below). Routed through
    // `runGraphQL` (toast on failure, no success toast ΓÇö best-effort/silent
    // success) instead of a bare `.catch(() => {})` (teacher 2026-07-11: "FE
    // shouldn't swallow errors, use runGraphQL") ΓÇö a failed start now surfaces to
    // the learner instead of leaving the shim route stuck silently.
    const startSessionAndRedirect = useCallback(
        async (redirectBase: string) => {
            if (!courseHeaders) {
                return
            }
            let freshId: string | undefined
            await runGraphQL(
                async () => {
                    const result = await runStartSession.trigger({
                        request: { deckId, cardIds: cards.map((deckCard) => deckCard.id) },
                        headers: courseHeaders,
                    })
                    const response = result.data?.startFlashcardReviewSession
                    freshId = response?.data?.sessionId
                    return response ?? { success: false, message: t("flashcard.review.error") }
                },
                { showSuccessToast: false },
            )
            if (freshId) {
                sessionIdRef.current = freshId
                // the live URL carries ONLY the sessionId, no `?deckId=` (teacher
                // 2026-07-11: "drop the deck, session only" ΓÇö no more `decks/<id>`
                // path segment either; `review/sessions/[sessionId]` is shared with
                // `DueReview`). `FlashcardsPage` resolves deck identity back out via
                // `myFlashcardReviewSessionBySessionId` ΓÇö the session already
                // persists it, no query hint needed.
                router.push(`${redirectBase}/sessions/${freshId}`)
            }
        },
        [cards, deckId, courseHeaders, runStartSession, runGraphQL, router, t],
    )

    // every card in the deck was already graded (`reviewedCount` reaches the
    // deck size) but `status` never flipped to "completed" ΓÇö the earlier
    // completion call never landed (2026-07-12, same root cause traced in
    // `QuizSession`: "already submitted but F5 goes back to the last question"). Clamping `currentIndex`
    // to `cards.length - 1` would ALWAYS re-show the last card (that index
    // can't tell "about to answer" from "just answered" apart) ΓÇö resolve to
    // the FULL length instead so `done` computes true immediately and the
    // "finish" effect below retries completion.
    const resolveIndex = useCallback(
        (resumable: { reviewedCount: number, currentIndex: number }) =>
            resumable.reviewedCount >= cards.length
                ? cards.length
                : Math.min(resumable.currentIndex, cards.length - 1),
        [cards.length],
    )

    useEffect(() => {
        if (
            initAttemptedRef.current
            || cards.length === 0
            || !courseHeaders
        ) {
            return
        }

        if (sessionId) {
            if (sessionByIdSwr.isLoading) {
                return
            }
            initAttemptedRef.current = true
            const resolved = sessionByIdSwr.data
            if (resolved) {
                sessionIdRef.current = sessionId
                setCurrentIndex(resolveIndex(resolved))
                setReviewedCount(resolved.reviewedCount)
                setGradedIndexes(seedGradedSet(resolved))
                setInitResolved(true)
                return
            }
            // stale/invalid session id (not found/not owned/expired past 24h) ΓÇö
            // start a fresh one and correct the URL, same as the no-`sessionId`
            // branch below.
            void startSessionAndRedirect(pathname.replace(/\/sessions\/.+$/, ""))
            return
        }

        if (inProgressSessionSwr.isLoading) {
            return
        }
        initAttemptedRef.current = true
        const resumable = inProgressSessionSwr.data
        if (resumable) {
            sessionIdRef.current = resumable.sessionId
            setCurrentIndex(resolveIndex(resumable))
            setReviewedCount(resumable.reviewedCount)
            setGradedIndexes(seedGradedSet(resumable))
            // strip any existing `/sessions/<id>` so we never append a second
            // one (the `.../sessions/A//sessions/B` revisit crash); replace, not
            // push, so the stale URL doesn't linger in history.
            router.replace(`${pathname.replace(/\/sessions\/.+$/, "")}/sessions/${resumable.sessionId}`)
            return
        }
        void startSessionAndRedirect(pathname.replace(/\/sessions\/.+$/, ""))
    }, [
        cards,
        sessionId,
        courseHeaders,
        sessionByIdSwr.isLoading,
        sessionByIdSwr.data,
        inProgressSessionSwr.isLoading,
        inProgressSessionSwr.data,
        resolveIndex,
        router,
        pathname,
        startSessionAndRedirect,
    ])

    const card = cards[currentIndex]

    // SM-2 grade buttons for the current card: localized label + next-interval
    // preview ("4 days") computed server-side from the card's current state
    const ratingOptions = useMemo(() => {
        const intervals = card?.nextIntervals
        // map a grade to its previewed next-interval in days
        const daysForGrade = (grade: number): number | undefined => {
            if (!intervals) {
                return undefined
            }
            return [intervals.again, intervals.hard, intervals.good, intervals.easy][grade]
        }
        return SM2_GRADES.map((grade) => {
            const days = daysForGrade(grade.grade)
            return {
                grade: grade.grade,
                label: t(grade.labelKey),
                hint: days === undefined ? undefined : t("flashcard.review.intervalDays", { count: days }),
            }
        })
    }, [t, card])

    // a premium card is locked for a non-enrolled viewer ΓÇö its answer is withheld
    const isLocked = Boolean(card?.isPremium) && !enrolled
    const isFirst = currentIndex === 0
    const isLast = currentIndex >= cards.length - 1

    /** Open the course page so the viewer can enrol to unlock premium cards. */
    const onUnlock = useCallback(() => {
        router.push(pathConfig().locale(locale).course(courseDisplayId).build())
    }, [router, locale, courseDisplayId])
    // past the last card ΓåÆ the run is complete
    const done = cards.length > 0 && (finished || currentIndex >= cards.length)

    // step back to re-grade an earlier card (always on its question side)
    const goPrev = () => {
        setRevealed(false)
        setCurrentIndex((index) => Math.max(index - 1, 0))
    }
    // jump straight to ANY step from the progress-segment bar ΓÇö free navigation,
    // "both before and after, clickable even before you reach it" (2026-07-12, mirrors `DueReview`).
    const goToIndex = useCallback((position: number) => {
        setRevealed(false)
        setCurrentIndex(position)
    }, [])
    // "Next" ΓÇö the explicit, symmetric counterpart to "Previous": browse forward
    // WITHOUT revealing/grading (mirrors `goPrev`; both are just the free-nav
    // `goToIndex` under the hood, per teacher 2026-07-12: "next prev" flanking the
    // primary "Show answer" CTA, researched against Mochi/Anki's ΓåÉ ΓåÆ idiom).
    const goNext = useCallback(() => {
        setRevealed(false)
        setCurrentIndex((index) => Math.min(index + 1, cards.length - 1))
    }, [cards.length])
    // end the run now ΓåÆ the completion effect (`done`) fires + navigates to the
    // result route. Distinct from "Exit" (back-link: leave, keep resumable).
    const onFinish = useCallback(() => setFinished(true), [])

    // grade the current card, reschedule it (SM-2), then advance
    const onRate = useCallback(
        async (grade: number) => {
            if (!card) {
                return
            }
            setReviewing(true)
            // a success toast per card would be noise ΓÇö only surface failures
            const ok = await runGraphQL(
                async () => {
                    const response = await mutateReviewFlashcard({
                        // thread the live session id so the review event links to
                        // this session ΓÇö powers the per-session stats aggregate.
                        request: { cardId: card.id, grade, sessionId: sessionIdRef.current ?? undefined },
                    })
                    return (
                        response.data?.reviewFlashcard ?? {
                            success: false,
                            message: t("flashcard.review.error"),
                        }
                    )
                },
                { showSuccessToast: false },
            )
            setReviewing(false)
            if (ok) {
                // mark THIS position graded (set dedupes a re-grade) ΓÇö source of
                // truth for the per-segment green + the reviewed count.
                const nextGraded = new Set(gradedIndexes).add(currentIndex)
                const nextReviewedCount = nextGraded.size
                const nextIndex = currentIndex + 1
                setGradedIndexes(nextGraded)
                setReviewedCount(nextReviewedCount)
                setRevealed(false)
                setCurrentIndex(nextIndex)
                // best-effort, fire-and-forget persistence for resume ΓÇö never blocks
                // advancing the reviewer; still routed through `runGraphQL` (toast on
                // failure, no success toast) rather than a silent catch ΓÇö a failed sync
                // only degrades resumability, but the learner should still see it.
                if (sessionIdRef.current && courseHeaders) {
                    const syncSessionId = sessionIdRef.current
                    void runGraphQL(
                        async () => {
                            const result = await runSyncSession.trigger({
                                request: {
                                    sessionId: syncSessionId,
                                    currentIndex: nextIndex,
                                    reviewedCount: nextReviewedCount,
                                    gradedIndexes: Array.from(nextGraded),
                                    xpEarned: 0,
                                },
                                headers: courseHeaders,
                            })
                            return (
                                result.data?.syncFlashcardReviewSessionProgress ?? {
                                    success: false,
                                    message: t("flashcard.review.error"),
                                }
                            )
                        },
                        { showSuccessToast: false },
                    ).then(() => {
                        // invalidate any resumable-session indicator elsewhere reading
                        // THIS exact key (mirrors the identical fix on `DueReview`,
                        // 2026-07-12: "pressing back showed 2 while it was actually 5" ΓÇö a
                        // per-grade sync never invalidated the cache, only the `done`
                        // completion path did, so a revisit mid-session could read a
                        // stale currentIndex even though the DB itself was correct).
                        void globalMutate(["QUERY_MY_IN_PROGRESS_FLASHCARD_REVIEW_SESSION_SWR", deckId])
                    })
                }
            }
        },
        [card, runGraphQL, t, gradedIndexes, currentIndex, courseHeaders, runSyncSession, globalMutate, deckId],
    )

    // the run just finished (past the last card) ΓÇö close out the persisted
    // session ONCE so `myFlashcardReviewHistory`/`myFlashcardReviewStats` can
    // read it; guarded so a re-render at `done` never double-fires it. Routed
    // through `runGraphQL` (teacher 2026-07-11: "FE shouldn't swallow errors,
    // use runGraphQL") instead of a silent catch.
    useEffect(() => {
        if (!done || completedRef.current || !sessionIdRef.current || !courseHeaders) {
            return
        }
        completedRef.current = true
        const completingSessionId = sessionIdRef.current
        void (async () => {
            await runGraphQL(
                async () => {
                    const result = await runCompleteSession.trigger({
                        request: {
                            sessionId: completingSessionId,
                            reviewedCount,
                            xpEarned: 0,
                        },
                        headers: courseHeaders,
                    })
                    return (
                        result.data?.completeFlashcardReviewSession ?? {
                            success: false,
                            message: t("flashcard.review.error"),
                        }
                    )
                },
                { showSuccessToast: false },
            )
            // hand off to the dedicated result route once the session is closed out
            // (reads events by sessionId, independent of the session row's status ΓÇö
            // "done" is now answered by the URL, not re-derived client-side; see
            // `.../result/page.tsx` doc for the root cause).
            router.replace(`${pathname.replace(/\/sessions\/.+$/, "")}/sessions/${completingSessionId}/result`)
        })()
    }, [done, reviewedCount, courseHeaders, runCompleteSession, runGraphQL, t, router, pathname])

    // first load, nothing in hand yet ΓÇö the deck query AND the session-resolve
    // effect both have to settle (loading-and-skeleton.md ┬º2). No `sessionId` prop
    // = the resolve-only shim (bare `review?deckId=<id>` route) ΓÇö ALWAYS the
    // skeleton, never error/empty/live UI; it `router.replace`s into the sessioned
    // URL as soon as resolving lands (effect above). `cards.length > 0 &&
    // !initResolved` (2026-07-12 fix): once the deck itself has loaded, ALSO hold
    // the skeleton until the resume/start effect has actually applied
    // `currentIndex`/`reviewedCount` ΓÇö not just until its underlying query
    // settled ΓÇö closing a 1-frame flash (card 1 appears, then jumps to the real
    // resume position). Scoped to `cards.length > 0` so a genuinely empty deck
    // still falls through to `isEmpty` below (that effect never runs ΓÇö and never
    // resolves `initResolved` ΓÇö when there are no cards to resume into).
    const isSkeleton = !sessionId || ((isLoading || !data) && cards.length === 0) || (cards.length > 0 && !initResolved)
    // settled, sessioned, and the resolved card list is empty.
    const isEmpty = Boolean(sessionId) && cards.length === 0
    // error beats a stale loading flag (bug fixed 2026-07-11: gate `error`/`isEmpty`
    // on `sessionId` too, not just loading ΓÇö a genuine deck-query error used to leak
    // through as "no FlashcardsPage yet" on the shim even while still resolving).
    const resolvedError = sessionId && cards.length === 0 ? error : undefined

    const cardLevelLabel = card?.level ? t(`flashcard.level.${card.level}`) : undefined
    // interpolated per `done` ΓÇö the same pair the two branches used to compute
    // separately ("done" is now answered by the URL, not re-derived client-side).
    const counter = t("flashcard.cardProgress", {
        current: done ? cards.length : currentIndex + 1,
        total: cards.length,
    })

    const labels: FlashcardReviewerLabels = {
        exit: t("flashcard.exit"),
        title: t("flashcard.mode.study"),
        counter,
        savingLabel: t("flashcard.review.stats.savingLabel"),
        leaveTitle: t("flashcard.leaveTitle"),
        finishEarlyTitle: t("flashcard.finishEarlyTitle"),
        leaveConfirm: t("flashcard.leaveConfirm"),
        finishEarlyConfirm: t("flashcard.finishEarlyConfirm"),
        leaveCta: t("flashcard.leaveCta"),
        finishEarlyCta: t("flashcard.finishEarlyCta"),
        stayIn: t("flashcard.stayIn"),
        questionLabel: t("flashcard.questionLabel"),
        answerLabel: t("flashcard.answerLabel"),
        premiumLockedTitle: t("flashcard.premiumLockedTitle"),
        premiumLockedHint: t("flashcard.premiumLockedHint"),
        noAnswer: t("flashcard.noAnswer"),
        premiumCta: t("flashcard.premiumCta"),
        rateHint: t("flashcard.review.rateHint"),
        rateAria: t("flashcard.review.rateAria"),
        showAnswer: t("flashcard.showAnswer"),
        previous: t("flashcard.previous"),
        next: t("flashcard.next"),
        finishEarly: t("flashcard.finishEarly"),
        // shared by both the empty and the error branch ΓÇö mirrors the original,
        // which used this same key for both.
        emptyTitle: t("flashcard.empty"),
    }

    return (
        <_FlashcardReviewer
            isSkeleton={isSkeleton}
            isEmpty={isEmpty}
            error={resolvedError}
            onRetry={() => { void mutate() }}
            labels={labels}
            deckTitle={data?.title}
            done={done}
            currentIndex={currentIndex}
            totalCards={cards.length}
            card={card}
            cardLevelLabel={cardLevelLabel}
            isLocked={isLocked}
            isFirst={isFirst}
            isLast={isLast}
            revealed={revealed}
            reviewing={reviewing}
            gradedIndexes={Array.from(gradedIndexes)}
            ratingOptions={ratingOptions}
            onBack={onBack}
            onReveal={() => setRevealed(true)}
            onRate={(grade) => void onRate(grade)}
            onPrev={goPrev}
            onNext={goNext}
            onSegmentClick={goToIndex}
            onFinishEarly={onFinish}
            onUnlock={onUnlock}
        />
    )
}

"use client"

import React from "react"
import useSWR from "swr"
import { useTranslations } from "next-intl"
import { DUE_REVIEW_LIMIT } from "@/modules/utils/flashcards"
import { queryFlashcardDecksByCourse } from "@/modules/api/graphql/queries/query-flashcard-decks-by-course"
import { queryMyDueFlashcards } from "@/modules/api/graphql/queries/query-my-due-flashcards"
import { queryMyFlashcardStats } from "@/modules/api/graphql/queries/query-my-flashcard-stats"
import { useAppSelector } from "@/redux/hooks"
import { _FlashcardStatsStrip } from "./component"

/** Connected flashcards home progress block ΓÇö no public props. */
export const FlashcardStatsStrip = () => {
    const t = useTranslations()
    // scope mastery + new-backlog to THIS course (shared keys with the siblings)
    const courseId = useAppSelector((state) => state.course.entity?.id)

    // streak / retention / lifetime reviews
    const stats = useSWR(["my-flashcard-stats"], async () => {
        const response = await queryMyFlashcardStats({})
        return response.data?.myFlashcardStats.data ?? null
    })
    // decks ΓåÆ mastered + total cards (same key as FlashcardDeckList ΓåÆ cache shared)
    const decks = useSWR(
        courseId ? ["flashcard-decks-by-course", courseId] : null,
        async () => {
            const response = await queryFlashcardDecksByCourse({
                request: { courseId: courseId as string },
            })
            return response.data?.flashcardDecksByCourse.data ?? null
        },
    )
    // new (never-reviewed) backlog (same key as DueReviewHero ΓåÆ cache shared)
    const due = useSWR(
        ["my-due-flashcards", courseId ?? null, DUE_REVIEW_LIMIT],
        async () => {
            const response = await queryMyDueFlashcards({
                request: { courseId, limit: DUE_REVIEW_LIMIT },
            })
            return response.data?.myDueFlashcards.data ?? null
        },
    )

    // mastery split across the course's decks (all derived from existing data)
    const deckList = decks.data ?? []
    const total = deckList.reduce((sum, deck) => sum + (deck.cards?.length ?? 0), 0)
    const mastered = deckList.reduce((sum, deck) => sum + (deck.masteredCount ?? 0), 0)
    const newCount = Math.min(due.data?.newTotalCount ?? 0, total)
    const learning = Math.max(0, total - mastered - newCount)

    const streak = stats.data?.currentStreak ?? 0
    const retention = stats.data?.retentionRate ?? 0
    const totalReviewed = stats.data?.totalReviewed ?? 0
    const percent = total > 0 ? Math.round((mastered / total) * 100) : 0

    // still hydrating when no facet has resolved yet
    const isSkeleton =
        (stats.isLoading || decks.isLoading || due.isLoading) &&
        !stats.data && !decks.data && !due.data

    return (
        <_FlashcardStatsStrip
            isSkeleton={isSkeleton}
            // nothing to show only when the course has no cards at all
            isEmpty={total === 0}
            // only the deck-list fetch is watched here (unchanged from the legacy call)
            error={decks.error}
            onRetry={() => { void decks.mutate() }}
            mastered={mastered}
            total={total}
            learning={learning}
            newCount={newCount}
            streak={streak}
            totalReviewed={totalReviewed}
            labels={{
                label: t("flashcard.stats.label"),
                errorTitle: t("flashcard.empty"),
                masteredLine: `${t("flashcard.stats.masteredLine", { mastered, total })} ┬╖ ${percent}%`,
                streakChip: t("flashcard.stats.streakChip", { count: streak }),
                barAria: t("flashcard.stats.barAria", { mastered, learning, newCount, total }),
                mastered: t("flashcard.stats.mastered"),
                learning: t("flashcard.stats.learning"),
                new: t("flashcard.stats.new"),
                retentionCaption: t("flashcard.stats.retentionCaption", { percent: retention }),
                firstReviewHint: t("flashcard.stats.firstReviewHint"),
            }}
        />
    )
}

"use client"

import React, { useMemo, useState } from "react"
import useSWR from "swr"
import { useTranslations } from "next-intl"
import { useFlashcardNav } from "@/hooks/useFlashcardNav"
import { queryFlashcardDecksByCourse } from "@/modules/api/graphql/queries/query-flashcard-decks-by-course"
import { useAppSelector } from "@/redux/hooks"
import { _FlashcardStudyRail } from "./component"
import type { FlashcardStudyRailDeck } from "./component"
import type { FlashcardDeckEntity } from "@/modules/types/entities/flashcard-deck"

/** Props for {@link FlashcardStudyRail}. */
export type FlashcardStudyRailProps = Record<string, never>
/**
 * The flashcards LEFT RAIL ΓÇö CONNECTED half of {@link _FlashcardStudyRail}
 * (`tiers/split.md`): fetches the course's decks, owns the mode/deck/search
 * URL state (via `useFlashcardNav`), computes `isSkeleton` from the first-load
 * formula and `isEmpty` from the resolved (sorted + filtered) decks, and
 * resolves every label ΓÇö handing all of it down as already-resolved props.
 * Reads the owning course id from the store; shares the deck SWR key with the
 * page.
 *
 * @param props - {@link FlashcardStudyRailProps}
 */
export const FlashcardStudyRail = () => {
    const t = useTranslations()
    const courseId = useAppSelector((state) => state.course.entity?.id)
    const { mode, deckId, session, goMode, goDeck } = useFlashcardNav()
    const [query, setQuery] = useState("")

    // the deck highlighted in the rail = the open deck (none during the due session)
    const activeDeckId = session === "due" ? null : deckId

    const { data, isLoading, error, mutate } = useSWR(
        courseId ? ["flashcard-decks-by-course", courseId] : null,
        async () => {
            const response = await queryFlashcardDecksByCourse({
                request: { courseId: courseId as string },
            })
            return response.data?.flashcardDecksByCourse.data ?? null
        },
    )

    const decks = useMemo<Array<FlashcardDeckEntity>>(() => {
        const sorted = [...(data ?? [])].sort((prev, next) => prev.sortIndex - next.sortIndex)
        const normalized = query.trim().toLowerCase()
        if (!normalized) {
            return sorted
        }
        return sorted.filter((deck) =>
            `${deck.title ?? ""} ${deck.description ?? ""}`.toLowerCase().includes(normalized),
        )
    }, [data, query])

    // first load, nothing in hand ΓåÆ shimmer (loading-and-skeleton.md) ΓÇö same condition the
    // pre-split `AsyncContent.isLoading` used.
    const isSkeleton = (isLoading || !courseId) && (data ?? []).length === 0
    // settled (after loading + search) with nothing to show
    const isEmpty = decks.length === 0
    // settled fetch error with nothing cached to fall back to
    const settledError = (data ?? []).length === 0 ? error : undefined

    const rows: Array<FlashcardStudyRailDeck> = decks.map((deck) => ({
        id: deck.id,
        title: deck.title,
        dueCount: deck.dueCount,
    }))

    return (
        <_FlashcardStudyRail
            isSkeleton={isSkeleton}
            isEmpty={isEmpty}
            error={settledError}
            onRetry={() => { void mutate() }}
            mode={mode}
            onModeChange={goMode}
            query={query}
            onQueryChange={setQuery}
            activeDeckId={activeDeckId}
            decks={rows}
            onSelectDeck={goDeck}
            labels={{
                modeAria: t("flashcard.title"),
                modeStudy: t("flashcard.mode.study"),
                modeQuiz: t("flashcard.mode.quiz"),
                decksLabel: t("flashcard.decksLabel"),
                searchAria: t("flashcard.searchPlaceholder"),
                searchPlaceholder: t("flashcard.searchPlaceholder"),
                emptyTitle: query.trim()
                    ? t("flashcard.searchEmpty", { query: query.trim() })
                    : t("flashcard.empty"),
                errorTitle: t("flashcard.empty"),
            }}
        />
    )
}

