import { QuizSessionSkeleton } from "./QuizSessionSkeleton"
import { Box } from "@/components/frames/Box"
import { Cluster } from "@/components/frames/Cluster"
import { Container } from "@/components/frames/Container"
import { StackH, StackV } from "@/components/frames/Stack"

/** Props for {@link QuizSession}. */
export interface QuizSessionProps extends WithClassNames<undefined> {
    /** Course to draw quiz cards across (rendered only for enrolled viewers). */
    courseId: string
    /**
     * Present when reached via the dedicated `flashcards/quiz/sessions/[sessionId]`
     * route ΓÇö on mount, rehydrates that session from
     * `myInProgressFlashcardQuizSession` (re-fetching the actual card objects
     * for the persisted `cardIds`, in order) and jumps straight into the
     * `active` phase at the persisted `currentIndex`, instead of showing setup.
     * Mirrors `MockInterviewSessionProps.resumeSessionId`.
     */
    resumeSessionId?: string
}

/**
 * The phases of one quick-quiz run. `setup` picks mode + level; `active` walks a
 * fixed set of cloze cards (fill blanks ΓåÆ check ΓåÆ read full answer ΓåÆ SM-2);
 * `recap` frames the result by mastery and grants XP.
 */
export type QuizPhase = "setup" | "active" | "recap"

/** Practice modes ΓÇö differ only in how many cards a session runs. */
type QuizMode = "quick" | "deep"

/** Question count per practice mode. */
const MODE_LENGTH: Record<QuizMode, number> = { quick: 5, deep: 10 }

/** Seniority levels offered at setup (mirrors the backend `FlashcardLevel` enum). */
const LEVELS = ["junior", "middle", "senior", "staff"] as const

/** HeroUI Chip color per interview seniority level (mirrors the reviewer). */
const LEVEL_COLOR: Record<string, "success" | "warning" | "danger" | "accent"> = {
    junior: "success",
    middle: "warning",
    senior: "danger",
    staff: "accent",
}

/** A card counts toward the combo when the learner fills at least this ratio of blanks correctly. */
const COMBO_COVERAGE_THRESHOLD = 0.6
/** SM-2 grade at/above which a card also keeps the combo alive (Good / Easy). */
const COMBO_GRADE_THRESHOLD = 2
/** XP awarded per blank filled correctly ΓÇö the recap's local estimate. */
const XP_PER_CORRECT_BLANK = 2

/** Format elapsed/remaining seconds as mm:ss. Mirrors `MockInterviewSession`'s own. */
const formatElapsed = (seconds: number): string => {
    const mm = Math.floor(seconds / 60)
    const ss = seconds % 60
    return `${String(mm).padStart(2, "0")}:${String(ss).padStart(2, "0")}`
}
/** Below this many seconds remaining, the HUD countdown turns warning-colored
 *  (session time limit, real urgency ΓÇö not fake scarcity). Mirrors Mock Interview's own. */
const TIME_LIMIT_WARNING_SECONDS = 5 * 60
/** XP for a fallback (no-cloze) card with a Good/Easy self-grade. */
const XP_PER_STRUCTURAL_CARD = 3
/**
 * Spring used for the word-bank Γåö blank shared-layout ("fly into place") chip
 * animation ΓÇö snappy pick/place feel, not floaty. Swapped for `{ duration: 0 }`
 * under `prefers-reduced-motion` (same idiom as CollapsibleSidebar).
 */
const CLOZE_CHIP_TRANSITION = { type: "spring", stiffness: 500, damping: 32 } as const

/** A card drawn into a session, carrying the fields the quiz needs. */
interface QuizCard extends FlashcardCardEntity {
    /** Key terms ΓÇö union of the card's `:::chip` list and its own cloze marker
     *  terms (a term already marked `{{cN::term}}` never needs retyping into
     *  the chip block). Empty only when the card has neither. */
    keywords: Array<string>
    /** Owning deck id ΓÇö the source deck of the per-deck fetch in {@link fetchCardPool},
     *  not a GraphQL field. Drives the same-deck distractor tier. */
    deckId: string
}

/** Per-card outcome recorded during `active`, aggregated in the recap AND sent to
 *  `completeFlashcardQuizSession` so the server re-derives coverage/XP itself. */
interface CardResult {
    /** The card this outcome belongs to (sent to the server for scoring + weak-tags). */
    cardId: string
    /** Ratio of blanks filled correctly (0..1), or null for a fallback card without a cloze. */
    coverageRatio: number | null
    /** Blanks filled correctly this card had (0 for a fallback card without a cloze). */
    correctBlanks: number
    /** Total cloze blanks this card had (0 for a fallback card without a cloze). */
    totalBlanks: number
    /** Whether the learner got the card fully right without a hint (mastery signal). */
    correct: boolean
    /** XP this card contributed to the local estimate. */
    xp: number
}

/** FisherΓÇôYates shuffle (returns a new array; interleaves cards across decks/tags). */
const shuffle = <T,>(input: Array<T>): Array<T> => {
    const array = [...input]
    for (let i = array.length - 1; i > 0; i -= 1) {
        const j = Math.floor(Math.random() * (i + 1))
        ;[array[i], array[j]] = [array[j], array[i]]
    }
    return array
}

/**
 * "Quick Quiz" ΓÇö a non-AI, self-graded, gamified flashcard cloze quiz over a
 * course. The learner picks a mode + level, then for each drawn card fills the
 * blanks (key terms the author marked) from a word bank of correct terms +
 * sibling-card distractors, checks the answer objectively, reads the full model
 * answer, and self-grades with SM-2 (which reschedules the card). A combo tracks
 * momentum; the recap frames the run by mastery and grants leaderboard XP once
 * per session. The setup's data states go through {@link FlashcardStatsStrip}.
 * @param props - {@link QuizSessionProps}
 */
export const QuizSession = ({ courseId, className, resumeSessionId }: QuizSessionProps) => {
    const t = useTranslations()
    const locale = useLocale()
    const router = useRouter()
    const pathname = usePathname()
    const searchParams = useSearchParams()
    const runGraphQL = useGraphQLWithToast()
    // trial-vs-enrolled gating (enroll upsell + AI Mock Interview readiness) now lives
    // in the converged `FlashcardQuizResult` surface, which reads it from redux itself.
    const displayId = useAppSelector((state) => state.course.displayId)
    // course name for the shared WorkSessionHeader's identity chip
    const course = useAppSelector((state) => state.course.entity)
    // quiz cards are enrolled-only ΓåÆ send the course header for the backend guard
    const courseHeaders = useMemo(
        () => ({ [GraphQLHeadersKey.XCourseId]: courseId }),
        [courseId],
    )

    // mastery ("Mastery level") + the pool of decks to draw cards from
    const decksSwr = useSWR(
        ["flashcard-decks-by-course", courseId],
        async () => {
            const response = await queryFlashcardDecksByCourse({
                request: { courseId },
                headers: courseHeaders,
            })
            return response.data?.flashcardDecksByCourse.data ?? null
        },
    )
    const decks = decksSwr.data

    // today's due-card ids ΓÇö same SWR key/shape `DueReviewHero` already reads, so
    // the scope-picker's "Only cards due for review" and `startSession`'s draw-time filter
    // (below) share one fetch. `dueCount` also gates/dims the scope option when
    // nothing is due (mirrors `FlashcardReviewModeModal`'s `dueDisabled`).
    const dueSwr = useSWR(
        ["my-due-flashcards", courseId, DUE_REVIEW_LIMIT],
        async () => {
            const response = await queryMyDueFlashcards({ request: { courseId, limit: DUE_REVIEW_LIMIT } })
            return response.data?.myDueFlashcards.data ?? null
        },
    )
    const dueCardIds = useMemo(
        () => new Set((dueSwr.data?.cards ?? []).map((dueCard) => dueCard.cardId)),
        [dueSwr.data],
    )
    const dueDisabled = (dueSwr.data?.dueCount ?? 0) <= 0
    useEffect(() => {
        if (dueDisabled) {
            setScope("all")
        }
    }, [dueDisabled])

    // refreshed after a session grants XP (the setup's progress zone reads its own
    // streak from `FlashcardStatsStrip` instead)
    const weeklyStatsSwr = useQueryMyWeeklyStatsSwr()

    const runComplete = useMutateCompleteFlashcardQuizSessionSwr()
    const runStart = useMutateStartFlashcardQuizSessionSwr()
    const runSyncProgress = useMutateSyncFlashcardQuizSessionProgressSwr()
    // read BOTH by the setup screen's resume card (when NOT already resuming) and the
    // rehydrate effect below (when `resumeSessionId` IS present) ΓÇö mirrors
    // `MockInterviewSession`'s single `inProgressSessionSwr` read.
    const inProgressSessionSwr = useQueryMyInProgressFlashcardQuizSessionSwr(courseId)

    // total card count across the course's decks ΓÇö gates the setup CTA
    const totalCards = useMemo(
        () => (decks ?? []).reduce((sum, deck) => sum + (deck.cards?.length ?? 0), 0),
        [decks],
    )

    // shared-layout "fly into the blank" animation (word-bank chip Γåö blank chip)
    // is disabled under prefers-reduced-motion ΓÇö same idiom as CollapsibleSidebar.
    const reduceMotion = useReducedMotion()

    // ΓöÇΓöÇ session state ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
    const [phase, setPhase] = useState<QuizPhase>("setup")
    // which setup tab is active ("Begin" / "History" / "Stats") ΓÇö setup phase only.
    // Seeded from `?tab=` so a shared/refreshed link lands back on the same tab (mirrors
    // MockInterviewSession's own setupTab + `layouts/dashboard-hub.md`'s "?tab= must be
    // shareable" precedent) ΓÇö "begin" is the implicit default, never written to the URL.
    const [setupTab, setSetupTab] = useState<"begin" | "history" | "stats">(() => {
        const initial = searchParams.get("tab")
        return initial === "history" || initial === "stats" ? initial : "begin"
    })
    const [mode, setMode] = useState<QuizMode>("quick")
    const [level, setLevel] = useState<string | null>(null)
    // learner-chosen name for this run, set at setup ("Practice config") ΓÇö optional;
    // blank falls back to a TIME-BASED display name derived from `updatedAt` once
    // the session exists (see `sessionDisplayName`), never random-generated.
    const [sessionName, setSessionName] = useState("")
    // "Review all" (draw from the whole pool) vs "Only cards due for review" (draw only from
    // today's due queue) ΓÇö same 2 options + wording as `FlashcardReviewModeModal`
    // (teacher 2026-07-13: "add review-all and only-cards-due to the practice config").
    const [scope, setScope] = useState<"all" | "due">("all")
    // cards drawn for the current run
    const [sessionCards, setSessionCards] = useState<Array<QuizCard>>([])
    // zero-based index of the current card
    const [index, setIndex] = useState(0)
    // the learner's chosen term per blank (null = still empty)
    const [filled, setFilled] = useState<Array<string | null>>([])
    // true once the learner checked the filled cloze (locks it, reveals correctness)
    const [checked, setChecked] = useState(false)
    // true once the full model answer is revealed (after checking)
    const [showAnswer, setShowAnswer] = useState(false)
    // true while an SM-2 grade is in flight (blocks the rating bar)
    const [rating, setRating] = useState(false)
    // per-card outcomes gathered this run
    const [results, setResults] = useState<Array<CardResult>>([])
    // in-session combo (consecutive well-answered cards) ΓÇö drives the active HUD chip
    const [combo, setCombo] = useState(0)
    // confirm-before-exit for the two irreversible active-session actions, mirroring
    // MockInterviewSession: "leave" (Exit ΓÇö abandon this run) ┬╖ "endEarly" (End
    // early ΓÇö grade with the cards done so far). null = no dialog open.
    const [confirmAction, setConfirmAction] = useState<null | "leave" | "endEarly">(null)
    // true while `startSession` is drawing + persisting a fresh run ΓÇö drives the
    // "Start practice" button's own isPending (stays ON this screen; only the
    // eventual navigation to `/quiz/[sessionId]` leaves it, restructured 2026-07-09).
    const [starting, setStarting] = useState(false)
    // set when `startSession` couldn't produce a playable session (no cards at the
    // chosen level, or the persist call failed) ΓÇö shown inline on the setup screen;
    // the run never leaves `setup` until a session is actually created.
    const [startError, setStartError] = useState<string | null>(null)
    // client-generated id shared by this run ΓåÆ idempotent XP grant
    const sessionId = useRef<string | null>(null)
    // guards the one-shot completion mutation on entering the recap
    const completedRef = useRef(false)
    // guards the one-shot resume rehydration to run at most once per mounted instance
    const resumeAttemptedRef = useRef(false)
    // set when `resumeSessionId` couldn't be resumed (no matching session / expired
    // past its 60min TTL) ΓÇö shown as an inline note on the setup screen it falls back to
    const [resumeError, setResumeError] = useState<string | null>(null)
    // server-issued deadline for THIS run (createdAt + duration) ΓÇö set on start AND
    // on resume rehydrate; drives the WorkSessionHeader countdown below, same
    // `deadlineAt` contract as Mock Interview's own HUD (never a local clock start).
    const [deadlineAt, setDeadlineAt] = useState<string | null>(null)
    const [remainingSeconds, setRemainingSeconds] = useState<number | null>(null)
    // dummy tick to force the setup screen's resume-card "N minutes left" to recompute
    // every 30s while it's on screen ΓÇö same idiom as MockInterviewSession's own
    // `resumeCountdownTick` (the minutes value itself is computed inline in render).
    const [, setResumeCountdownTick] = useState(0)

    // the setup screen's mode picker drives this pre-build; once cards are actually
    // drawn (fresh OR resumed), the real count wins ΓÇö a resumed run's card count
    // depends on whichever mode it was originally started with, not the setup
    // screen's current (unrelated) selection.
    const sessionLength = sessionCards.length > 0 ? sessionCards.length : MODE_LENGTH[mode]

    const card = sessionCards[index]

    // SM-2 grade buttons for the current card: localized label + next-interval
    // preview ("4 days") computed server-side from the card's current state
    const ratingOptions = useMemo(() => {
        const intervals = card?.nextIntervals
        // map a grade to its previewed next-interval in days
        const daysForGrade = (grade: number): number | undefined => {
            if (!intervals) {
                return undefined
            }
            return [intervals.again, intervals.hard, intervals.good, intervals.easy][grade]
        }
        return SM2_GRADES.map((grade) => {
            const days = daysForGrade(grade.grade)
            return {
                grade: grade.grade,
                label: t(grade.labelKey),
                hint: days === undefined ? undefined : t("flashcard.review.intervalDays", { count: days }),
            }
        })
    }, [t, card])

    // fetch the full cards of every deck (self-grading needs a model answer to compare
    // against). Each deck is fetched independently (allSettled) so ONE deck failing
    // (e.g. missing from the Elasticsearch index the single-deck read serves from ΓÇö
    // see `FlashcardDeckReadService.getById`) can't silently empty the whole pool:
    // the caller just draws from whichever decks DID resolve. Shared by a FRESH start
    // (draws + shuffles) and a resume (looks the persisted `cardIds` up by id).
    const fetchCardPool = useCallback(async () => {
        const settled = await Promise.allSettled(
            (decks ?? []).map(async (deck) => {
                const response = await queryFlashcardDeck({
                    request: { flashcardDeckId: deck.id },
                    headers: courseHeaders,
                })
                const payload = response.data?.flashcardDeck
                if (!payload?.success) {
                    throw new Error(payload?.message ?? "flashcard deck fetch failed")
                }
                return (payload.data?.cards ?? []).map((card) => ({ ...card, deckId: deck.id }))
            }),
        )
        const anyDeckFailed = settled.some((result) => result.status === "rejected")
        const deckPayloads = settled
            .filter((result) => result.status === "fulfilled")
            .map((result) => result.value)
        const pool: Array<QuizCard> = deckPayloads
            .flat()
            .filter((card) => Boolean(card.answer))
            .map((card) => ({ ...card, keywords: extractMarkerTerms(card.answer) }))
        return { pool, anyDeckFailed }
    }, [decks, courseHeaders])

    // draw a fresh run: pool + filter by level + shuffle, persist it server-side,
    // THEN navigate to the resumable `/quiz/[sessionId]` route ΓÇö stays on THIS
    // (setup) screen the whole time, pending only on the CTA itself, per the teacher's
    // 2026-07-09 correction ("create the session first, then load into the quiz with its id" ΓÇö no
    // more instant phase flip to a building-skeleton screen, and no more silent
    // local/non-resumable fallback when the persist call fails: a real failure
    // now surfaces inline instead of quietly degrading).
    const startSession = useCallback(async () => {
        if (!decks || decks.length === 0 || starting) {
            return
        }
        setStarting(true)
        setStartError(null)
        setResumeError(null)
        try {
            const { pool, anyDeckFailed } = await fetchCardPool()
            const drawn = shuffle(
                pool
                    .filter((card) => level === null || card.level === level)
                    .filter((card) => scope !== "due" || dueCardIds.has(card.id)),
            ).slice(0, sessionLength)

            if (drawn.length === 0) {
                // an empty pool only means "no cards at this level" when every deck
                // fetch actually succeeded ΓÇö otherwise it's a load failure in disguise
                setStartError(
                    anyDeckFailed
                        ? t("flashcard.quiz.sessionLoadErrorTitle")
                        : scope === "due"
                            ? t("flashcard.quiz.emptyAtScope")
                            : t("flashcard.quiz.emptyAtLevel"),
                )
                setStarting(false)
                return
            }

            // `mode`/`level` are REQUIRED (non-null) on the backend's
            // StartFlashcardQuizSessionRequest (see start-flashcard-quiz-session/
            // graphql-types/request.ts) ΓÇö omitting them fails GraphQL input
            // validation before the resolver even runs (fixed 2026-07-09).
            const started = await runStart.trigger({
                request: {
                    courseId,
                    cardIds: drawn.map((card) => card.id),
                    mode,
                    level,
                    name: sessionName.trim() || undefined,
                },
                headers: courseHeaders,
            }).catch(() => null)
            const startedId = started?.data?.startFlashcardQuizSession.data?.sessionId
            if (!startedId || !displayId) {
                setStartError(t("flashcard.quiz.sessionLoadErrorTitle"))
                setStarting(false)
                return
            }
            // prime the in-progress cache with the just-created session BEFORE
            // navigating, so the fresh page that mounts at `/quiz/[sessionId]` reads
            // it (not the stale `null` this screen's own resume check cached) and
            // rehydrates cleanly instead of flashing "resume failed".
            await inProgressSessionSwr.mutate()
            router.push(
                pathConfig().locale(locale).course(displayId).learn()
                    .flashcards().quiz(startedId).build(),
            )
            // deliberately no `setStarting(false)` here ΓÇö this instance is about to
            // be unmounted by the navigation, so the button stays visibly pending
            // right up until the destination page takes over.
        } catch {
            setStartError(t("flashcard.quiz.sessionLoadErrorTitle"))
            setStarting(false)
        }
    }, [decks, starting, level, scope, dueCardIds, sessionLength, t, courseHeaders, courseId, mode, sessionName, runStart, inProgressSessionSwr, displayId, locale, router])

    // "Exit" ΓÇö leaves the active run for the setup screen. No confirm modal (unlike
    // Mock Interview's leave, which is destructive/abandon-ungraded): a quiz run is
    // persisted server-side (`syncFlashcardQuizSessionProgress`) so navigating away
    // just resumes later from the same card (teacher 2026-07-09: "both the review and
    // quiz parts have no back button").
    const exitToSetup = useCallback(() => {
        router.push(
            `${pathConfig().locale(locale).course(displayId).learn().flashcards().build()}/quiz`,
        )
    }, [router, locale, displayId])

    // finalize the run: send the per-card breakdown so the server re-derives coverage/XP
    // itself (no client-trusted aggregate), grant XP once (idempotent), then show the recap.
    // Defined here (not just above `commitCard`) so the resume effect below can call it too
    // (2026-07-12, mirrors the same move made for `MockInterviewSession`'s `renderWorkHeader`).
    const finish = useCallback(
        async (finalResults: Array<CardResult>) => {
            setPhase("recap")
            if (completedRef.current || !sessionId.current) {
                return
            }
            completedRef.current = true
            const answers = finalResults.map((result) => ({
                cardId: result.cardId,
                correctBlanks: result.correctBlanks,
                totalBlanks: result.totalBlanks,
            }))
            let awarded = 0
            await runGraphQL(
                async () => {
                    const response = await runComplete.trigger({
                        request: {
                            sessionId: sessionId.current as string,
                            courseId,
                            answers,
                        },
                        headers: courseHeaders,
                    })
                    const payload = response.data?.completeFlashcardQuizSession
                    awarded = payload?.data?.xpEarned ?? 0
                    return (
                        payload ?? {
                            success: false,
                            message: t("flashcard.review.error"),
                        }
                    )
                },
                { showSuccessToast: false },
            )
            if (awarded > 0) {
                // refresh the streak/XP chip now that this run counted
                void weeklyStatsSwr.mutate()
            }
            // Navigate to the dedicated result route instead of rendering the
            // result inline here ΓÇö "done" is now answered by the URL, not
            // re-derived client-side (see result/page.tsx doc for root cause).
            if (displayId) {
                router.replace(
                    pathConfig()
                        .locale(locale)
                        .course(displayId)
                        .learn()
                        .flashcards()
                        .quiz(sessionId.current as string)
                        .result()
                        .build(),
                )
            }
        },
        [runComplete, runGraphQL, courseId, courseHeaders, t, weeklyStatsSwr, router, locale, displayId],
    )

    // resume, on mount, when reached via the dedicated `flashcards/quiz/sessions/[sessionId]`
    // route ΓÇö waits for both the deck pool AND the in-progress query to settle, then
    // either rehydrates straight into the active phase at the persisted card/index or
    // falls back to setup with an inline error. Runs at most ONCE per mounted instance.
    useEffect(() => {
        if (!resumeSessionId || resumeAttemptedRef.current || !decks || inProgressSessionSwr.isLoading) {
            return
        }
        resumeAttemptedRef.current = true
        const data = inProgressSessionSwr.data
        if (!data || data.sessionId !== resumeSessionId) {
            setResumeError(t("flashcard.quiz.resumeFailed"))
            setPhase("setup")
            return
        }
        void (async () => {
            const { pool } = await fetchCardPool()
            const cardById = new Map(pool.map((quizCard) => [quizCard.id, quizCard]))
            const restoredCards = data.cardIds
                .map((cardId) => cardById.get(cardId))
                .filter((quizCard): quizCard is QuizCard => Boolean(quizCard))
            if (restoredCards.length === 0) {
                setResumeError(t("flashcard.quiz.resumeFailed"))
                setPhase("setup")
                return
            }
            const restoredResults: Array<CardResult> = data.results.map((result) => {
                const coverageRatio = result.totalBlanks > 0 ? result.correctBlanks / result.totalBlanks : null
                return {
                    cardId: result.cardId,
                    coverageRatio,
                    correctBlanks: result.correctBlanks,
                    totalBlanks: result.totalBlanks,
                    correct: coverageRatio === 1,
                    xp: coverageRatio !== null ? result.correctBlanks * XP_PER_CORRECT_BLANK : 0,
                }
            })
            sessionId.current = resumeSessionId
            setDeadlineAt(data.deadlineAt)
            setSessionCards(restoredCards)
            setCombo(0)
            setResumeError(null)

            // every card already has a recorded outcome ΓÇö the run WAS finished,
            // but `status` never flipped to "completed" (the earlier `finish()`
            // call never landed server-side for whatever reason ΓÇö network drop,
            // a duplicate-submit race, etc. ΓÇö 2026-07-12, teacher: "submitted, but
            // refreshing goes back to the last question"). `currentIndex` alone can't tell "about to answer
            // the LAST card" from "just answered it" apart ΓÇö both persist the
            // same last-valid-index value ΓÇö only `results` coverage can. Retry
            // completion instead of silently resuming into the (already
            // answered) last card again.
            if (restoredResults.length >= restoredCards.length) {
                completedRef.current = false
                setResults(restoredResults)
                setIndex(restoredCards.length - 1)
                void finish(restoredResults)
                return
            }

            setIndex(Math.min(data.currentIndex, restoredCards.length - 1))
            setResults(restoredResults)
            completedRef.current = false
            setPhase("active")
        })()
    }, [resumeSessionId, decks, inProgressSessionSwr.isLoading, inProgressSessionSwr.data, fetchCardPool, t, finish])

    // "session time limit" ΓÇö ticks every second while the run is active, counting
    // DOWN to the server-issued `deadlineAt` (never a local clock start). Mirrors
    // `MockInterviewSession`'s own countdown effect (teacher 2026-07-11: "add a
    // 60-minute time limit per session" ΓÇö the deadline itself was already server-enforced
    // via `FLASHCARD_QUIZ_SESSION_DURATION_MS`; this makes it VISIBLE in the HUD).
    useEffect(() => {
        if (phase !== "active" || !deadlineAt) {
            return
        }
        const deadlineMs = new Date(deadlineAt).getTime()
        const tick = () => {
            setRemainingSeconds(Math.max(0, Math.ceil((deadlineMs - Date.now()) / 1000)))
        }
        tick()
        const id = window.setInterval(tick, 1000)
        return () => window.clearInterval(id)
    }, [phase, deadlineAt])

    // resume-card countdown (setup screen) ΓÇö coarse 30s tick, only while there's
    // an actual resumable session to show a deadline for. Mirrors
    // MockInterviewSession's own resume-card countdown idiom.
    useEffect(() => {
        if (phase !== "setup" || !inProgressSessionSwr.data) {
            return
        }
        const id = window.setInterval(() => setResumeCountdownTick((previous) => previous + 1), 30_000)
        return () => window.clearInterval(id)
    }, [phase, inProgressSessionSwr.data])

    // mirror the setup tab into the URL (`?tab=history` / `?tab=stats`) ΓÇö same technique
    // as MockInterviewSession's own setupTab mirror, so "History"/"Stats" are
    // shareable/refresh-safe links. "begin" (the default) is never written, keeping the
    // common-case URL clean.
    useEffect(() => {
        const want = setupTab === "begin" ? null : setupTab
        if (searchParams.get("tab") === want) {
            return
        }
        const params = new URLSearchParams(searchParams.toString())
        if (want) {
            params.set("tab", want)
        } else {
            params.delete("tab")
        }
        const qs = params.toString()
        router.replace(qs ? `${pathname}?${qs}` : pathname, { scroll: false })
    }, [setupTab, pathname, searchParams, router])

    // distractor pool: sibling cards' key terms, closest-topic first (in the style of
    // Duolingo/Quizlet drawing from the session's own vocab) ΓÇö same TAG, then
    // same DECK (still one coherent topic even without a shared tag), then the
    // whole session as a last resort. Without the deck tier, a thin same-tag
    // draw fell straight through to the WHOLE session/course pool, which is how
    // an unrelated term (e.g. a SQL clause) ended up in a NestJS DI question's
    // word bank (teacher 2026-07-11 bug report).
    const distractorPool = useMemo(() => {
        if (!card) {
            return []
        }
        const others = sessionCards.filter((_, position) => position !== index)
        const sameTag = others.filter((other) =>
            (other.tags ?? []).some((tag) => (card.tags ?? []).includes(tag)),
        )
        const sameDeck = others.filter((other) => other.deckId === card.deckId)
        const source = sameTag.length >= 2 ? sameTag : sameDeck.length >= 2 ? sameDeck : others
        return [...new Set(source.flatMap((other) => other.keywords))]
    }, [card, sessionCards, index])

    // the cloze for the current card (null ΓåÆ fall back to a plain flip +
    // self-grade ΓÇö only when the card itself has no clozable key terms;
    // "Quick Quiz" and "Study Cards" are unrelated features, so this is NOT a
    // learner-facing method choice, just a per-card content fallback).
    const cloze = useMemo<ClozeQuestion | null>(
        () =>
            card
                ? buildCloze({
                    answer: card.answer ?? "",
                    distractorPool,
                })
                : null,
        [card, distractorPool],
    )

    // reset the per-card interaction whenever the card (hence its cloze) changes
    useEffect(() => {
        setFilled(cloze ? Array(cloze.blanks.length).fill(null) : [])
        setChecked(false)
        setShowAnswer(false)
    }, [cloze])

    // place a bank term into the first empty blank (ignored once checked / already used)
    const placeTerm = useCallback(
        (term: string) => {
            if (checked) {
                return
            }
            setFilled((current) => {
                if (current.includes(term)) {
                    return current
                }
                const slot = current.indexOf(null)
                if (slot === -1) {
                    return current
                }
                const next = [...current]
                next[slot] = term
                return next
            })
        },
        [checked],
    )

    // clear a filled blank (returns its term to the bank)
    const clearBlank = useCallback(
        (blankIndex: number) => {
            if (checked) {
                return
            }
            setFilled((current) => {
                const next = [...current]
                next[blankIndex] = null
                return next
            })
        },
        [checked],
    )

    // record the current card's outcome + combo, reschedule via SM-2, then advance
    const commitCard = useCallback(
        async (grade: number, coverageRatio: number | null) => {
            if (!card) {
                return
            }
            setRating(true)
            // a success toast per card would be noise ΓÇö only surface failures
            const ok = await runGraphQL(
                async () => {
                    const response = await mutateReviewFlashcard({
                        request: { cardId: card.id, grade },
                    })
                    return (
                        response.data?.reviewFlashcard ?? {
                            success: false,
                            message: t("flashcard.review.error"),
                        }
                    )
                },
                { showSuccessToast: false },
            )
            setRating(false)
            if (!ok) {
                return
            }
            const correct = coverageRatio === 1 || (coverageRatio === null && grade >= COMBO_GRADE_THRESHOLD)
            const keptCombo =
                (coverageRatio !== null && coverageRatio >= COMBO_COVERAGE_THRESHOLD)
                || grade >= COMBO_GRADE_THRESHOLD
            // this card's raw blank counts ΓÇö sent to the server, which re-derives coverage/XP
            // itself (no client-trusted aggregate); a fallback (no-cloze) card sends 0/0
            const totalBlanks = coverageRatio !== null ? (cloze?.blanks.length ?? 0) : 0
            const correctBlanks = coverageRatio !== null ? Math.round(coverageRatio * totalBlanks) : 0
            const xp =
                coverageRatio !== null
                    ? correctBlanks * XP_PER_CORRECT_BLANK
                    : grade >= COMBO_GRADE_THRESHOLD
                        ? XP_PER_STRUCTURAL_CARD
                        : 0
            const nextResults = [
                ...results,
                { cardId: card.id, coverageRatio, correctBlanks, totalBlanks, correct, xp },
            ]
            setResults(nextResults)
            setCombo((current) => (keptCombo ? current + 1 : 0))
            const nextIndex = index < sessionLength - 1 ? index + 1 : index
            // best-effort, fire-and-forget persistence for resume ΓÇö never blocks
            // advancing the quiz; still routed through `runGraphQL` (toast on failure,
            // no success toast) rather than a silent catch (teacher 2026-07-11: "FE
            // shouldn't swallow errors, use runGraphQL") ΓÇö a failed sync only degrades
            // resumability, but the learner should still see it.
            if (sessionId.current) {
                const syncingSessionId = sessionId.current
                void runGraphQL(
                    async () => {
                        const result = await runSyncProgress.trigger({
                            request: {
                                sessionId: syncingSessionId,
                                currentIndex: nextIndex,
                                results: nextResults.map((result) => ({
                                    cardId: result.cardId,
                                    correctBlanks: result.correctBlanks,
                                    totalBlanks: result.totalBlanks,
                                })),
                            },
                            headers: courseHeaders,
                        })
                        return (
                            result.data?.syncFlashcardQuizSessionProgress ?? {
                                success: false,
                                message: t("flashcard.quiz.error"),
                            }
                        )
                    },
                    { showSuccessToast: false },
                )
            }
            if (index < sessionLength - 1) {
                setIndex((current) => current + 1)
            } else {
                void finish(nextResults)
            }
        },
        [card, cloze, results, index, sessionLength, runGraphQL, t, finish, runSyncProgress, courseHeaders],
    )

    // ΓöÇΓöÇ RESUMING ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
    // reached via the dedicated `/quiz/[sessionId]` route and the rehydrate effect
    // above hasn't landed on `active` yet ΓÇö show the active-run skeleton instead of
    // flashing the setup screen's tabs/CTA (which would be wrong for this route and
    // never actually shown once the effect commits `active`).
    if (resumeSessionId && phase === "setup" && !resumeError) {
        return <QuizSessionSkeleton className={className} />
    }

    // ΓöÇΓöÇ SETUP ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
    if (phase === "setup") {
        const resumeData = inProgressSessionSwr.data
        const learnPath = pathConfig().locale(locale).course(displayId).learn()
        return (
            <Box className={className}>
                <StackV gap={6} principle="block-boundary" items={[
                    () => (
                        <TabsCard
                            variant="secondary"
                            className="w-full"
                            leftTabs={{
                                items: [
                                    { key: "begin", label: t("flashcard.quiz.setupTabBegin") },
                                    { key: "history", label: t("flashcard.quiz.setupTabHistory") },
                                    { key: "stats", label: t("flashcard.quiz.setupTabStats") },
                                ],
                                selectedKey: setupTab,
                                ariaLabel: t("flashcard.quiz.setupTabBegin"),
                                onSelectionChange: (key) => setSetupTab(key as "begin" | "history" | "stats"),
                            }}
                        />
                    ),
                    () => (
                        setupTab === "history" ? (
                            <FlashcardQuizHistory courseId={courseId} onStartQuiz={() => setSetupTab("begin")} />
                        ) : setupTab === "stats" ? (
                            <FlashcardQuizStats courseId={courseId} onStartQuiz={() => setSetupTab("begin")} />
                        ) : (
                            <StackV gap={6} items={[
                                ...(resumeData ? [() => {
                                    const resumeRemainingMinutes = Math.max(
                                        0,
                                        Math.ceil((new Date(resumeData.deadlineAt).getTime() - Date.now()) / 60_000),
                                    )
                                    const resumeName = sessionDisplayName(resumeData.name, resumeData.updatedAt, t, locale)
                                    return (
                                        <ContinueCard
                                            title={resumeName}
                                            subtitle={t("flashcard.quiz.resumeSubtitle", {
                                                current: resumeData.currentIndex + 1,
                                                total: resumeData.cardIds.length,
                                                minutes: resumeRemainingMinutes,
                                            })}
                                            urgent={resumeRemainingMinutes <= 15}
                                            variant="hero"
                                            value={resumeData.currentIndex + 1}
                                            max={resumeData.cardIds.length}
                                            ctaLabel={t("flashcard.quiz.resumeCta")}
                                            onPress={() => router.push(learnPath.flashcards().quiz(resumeData.sessionId).build())}
                                        />
                                    )
                                }] : []),
                                ...(resumeError ? [() => <Callout status="danger" title={resumeError} />] : []),
                                () => <FlashcardStatsStrip />,
                                () => (
                                    <LabeledCard label={t("flashcard.quiz.configLabel")}>
                                        <StackV gap={4} principle="group-boundary" items={[
                                            () => (
                                                <StackV gap={3} principle="label-field" items={[
                                                    () => <Label>{t("common.sessionNameLabel")}</Label>,
                                                    () => (
                                                        <TextField variant="secondary" className="w-full">
                                                            <Input
                                                                className="w-full"
                                                                placeholder={t("common.sessionNamePlaceholder")}
                                                                name="sessionName"
                                                                value={sessionName}
                                                                onChange={(event) => setSessionName(event.target.value)}
                                                                maxLength={80}
                                                            />
                                                        </TextField>
                                                    ),
                                                ]} />
                                            ),
                                            () => (
                                                <StackV gap={3} principle="label-field" items={[
                                                    () => <Label>{t("flashcard.quiz.scopeLabel")}</Label>,
                                                    () => (
                                                        <FlexWrapButtonRadio
                                                            ariaLabel={t("flashcard.quiz.scopeLabel")}
                                                            value={scope}
                                                            onChange={setScope}
                                                            items={[
                                                                { value: "all", content: t("flashcard.mode.fullLabel") },
                                                                { value: "due", isDisabled: dueDisabled, content: t("flashcard.mode.dueLabel") },
                                                            ]}
                                                        />
                                                    ),
                                                ]} />
                                            ),
                                            () => (
                                                <StackV gap={3} principle="label-field" items={[
                                                    () => <Label>{t("flashcard.quiz.modeLabel")}</Label>,
                                                    () => (
                                                        <FlexWrapButtonRadio
                                                            ariaLabel={t("flashcard.quiz.modeLabel")}
                                                            value={mode}
                                                            onChange={setMode}
                                                            items={[
                                                                { value: "quick", content: t("flashcard.quiz.modeQuick") },
                                                                { value: "deep", content: t("flashcard.quiz.modeDeep") },
                                                            ]}
                                                        />
                                                    ),
                                                ]} />
                                            ),
                                            () => (
                                                <StackV gap={3} principle="label-field" items={[
                                                    () => <Label>{t("flashcard.quiz.levelLabel")}</Label>,
                                                    () => (
                                                        <FlexWrapButtonRadio
                                                            ariaLabel={t("flashcard.quiz.levelLabel")}
                                                            value={level ?? "all"}
                                                            onChange={(value) => setLevel(value === "all" ? null : value)}
                                                            items={[
                                                                { value: "all", content: t("flashcard.quiz.levelAll") },
                                                                ...LEVELS.map((value) => ({
                                                                    value,
                                                                    content: t(`flashcard.level.${value}`),
                                                                })),
                                                            ]}
                                                        />
                                                    ),
                                                ]} />
                                            ),
                                        ]} />
                                    </LabeledCard>
                                ),
                                () => (
                                    <Button
                                        variant={resumeData ? "secondary" : "primary"}
                                        size="lg"
                                        className="self-start"
                                        isDisabled={!decks || totalCards === 0}
                                        isPending={starting}
                                        onPress={() => { void startSession() }}
                                    >
                                        {t("flashcard.quiz.begin")}
                                        <ArrowRightIcon className="size-5" aria-hidden focusable="false" />
                                    </Button>
                                ),
                                ...(startError ? [() => <Callout status="danger" title={startError} />] : []),
                            ]} />
                        )
                    ),
                ]} />
            </Box>
        )
    }

    // ΓöÇΓöÇ RECAP ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
    // Transient hand-off only ΓÇö `finish()` navigates to the dedicated
    // `flashcards/quiz/sessions/[sessionId]/result` route once the completion
    // mutation resolves (2026-07-12: "done" is now answered by the ROUTE, not
    // re-derived client-side here), so this phase never has a real end state
    // to render ΓÇö just the "saving" interim until that navigation lands.
    if (phase === "recap") {
        return (
            // KEEP the same `WorkSessionHeader` chrome the just-finished ACTIVE
            // phase used (2026-07-12, corrected: the teacher wanted the loading state
            // to render like the active session's header, not swap to
            // `PageHeader` early). Segment bar reads full "done"
            // (`current === total` ΓåÆ every segment `success`), no `rightSlot`
            // (timer no longer meaningful once the run has ended).
            <Box className={className}>
                {(() => {
                    const recapChromeItems = [
                        () => (
                            <WorkSessionHeader
                                backLabel={t("flashcard.exit")}
                                onBack={exitToSetup}
                                title={t("flashcard.mode.quiz")}
                                identity={course?.title ? { name: course.title } : undefined}
                                counter={t("flashcard.quiz.progress", {
                                    current: sessionLength,
                                    total: sessionLength,
                                })}
                                current={sessionLength}
                                total={sessionLength}
                            />
                        ),
                        () => (
                            // teacher-hold: flashcards-remain-quiz-session-body-inset ΓÇö asymmetric session-body
                            // inset owned via Box page-pad escape hatch (pt-10 not in the padding scale).
                            <Box principle="page-pad" className="px-4 pb-6 pt-10 @app-sm:px-6">
                                <Container size="md" padding={1} body={() => (
                                    <Box className="py-10">
                                        <StackV gap={4} align="center" principle="card-caption" items={[
                                            () => <Spinner size="lg" />,
                                            () => (
                                                <Typography type="body-sm" color="muted">
                                                    {t("flashcard.quiz.result.savingLabel")}
                                                </Typography>
                                            ),
                                        ]} />
                                    </Box>
                                )} />
                            </Box>
                        ),
                    ]
                    return <StackV gap={1} items={recapChromeItems} />
                })()}
            </Box>
        )
    }

    // ΓöÇΓöÇ ACTIVE ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
    // no cards after the level filter ΓÇö offer a way back to setup. (A fresh draw
    // that fails to produce cards, or a load failure, is now caught earlier ΓÇö
    // see `startError` on the setup screen ΓÇö and never reaches here; this branch
    // is a resume-only guard, e.g. every persisted card was since deleted.)
    if (!card) {
        return (
            <Box className={className}>
                <StackV gap={6} items={[() => (
                    <EmptyState
                        icon={CheckCircleIcon}
                        title={t("flashcard.quiz.emptyAtLevel")}
                        action={() => (
                            <Button size="sm" variant="secondary" onPress={() => setPhase("setup")}>
                                {t("flashcard.quiz.backToSetup")}
                            </Button>
                        )}
                    />
                )]} />
            </Box>
        )
    }

    // shared header: WorkSessionHeader (course identity + step counter +
    // progress segments, combo chip in the right slot) ΓÇö same shell as the
    // mock-interview's work-surface header. Level/tag chips moved OUT of this
    // header into the question card's own body via `belowFront`/inline (teacher
    // 2026-07-13: "put the quick-quiz chip below the question per the review rules" ΓÇö
    // matching the same move already done for `FlashcardReviewer`/`DueReview`,
    // per-card meta belongs to the card body, not the fixed session chrome ΓÇö
    // `components/card.md` Correction 2026-07-13).
    const header = (
        <>
            <WorkSessionHeader
                backLabel={t("flashcard.exit")}
                onBack={() => setConfirmAction("leave")}
                onFinish={() => setConfirmAction("endEarly")}
                finishLabel={t("flashcard.finishEarly")}
                title={t("flashcard.mode.quiz")}
                identity={course?.title ? { name: course.title } : undefined}
                counter={t("flashcard.quiz.progress", {
                    current: index + 1,
                    total: sessionLength,
                })}
                current={index}
                total={sessionLength}
                rightSlot={
                    <StackH gap={4} align="center" classNames={["shrink-0"]} items={[
                        ...(remainingSeconds !== null ? [() => (
                            <StackH
                                gap={3}
                                principle="icon-text"
                                align="center"
                                classNames={["shrink-0"]}
                                items={[
                                    () => <ClockIcon className={cn("size-4", remainingSeconds <= TIME_LIMIT_WARNING_SECONDS && "text-warning-soft-foreground")} aria-hidden focusable="false" />,
                                    () => (
                                        <Typography type="body-sm" weight="medium" className={cn("tabular-nums", remainingSeconds <= TIME_LIMIT_WARNING_SECONDS && "text-warning-soft-foreground")}>
                                            {formatElapsed(remainingSeconds)}
                                        </Typography>
                                    ),
                                ]}
                            />
                        )] : []),
                        ...(combo > 1 ? [() => (
                            <Chip size="sm" variant="soft" color="warning">
                                <FlameIcon className="size-4" aria-hidden focusable="false" />
                                {t("flashcard.quiz.comboChip", { combo })}
                            </Chip>
                        )] : []),
                    ]} />
                }
            />
            <ConfirmDialog
                isOpen={confirmAction !== null}
                onOpenChange={(open) => { if (!open) { setConfirmAction(null) } }}
                title={confirmAction === "leave" ? t("flashcard.leaveTitle") : t("flashcard.finishEarlyTitle")}
                description={confirmAction === "leave" ? t("flashcard.leaveConfirm") : t("flashcard.finishEarlyConfirm")}
                confirmLabel={confirmAction === "leave" ? t("flashcard.leaveCta") : t("flashcard.finishEarlyCta")}
                cancelLabel={t("flashcard.stayIn")}
                onConfirm={() => {
                    const action = confirmAction
                    setConfirmAction(null)
                    if (action === "leave") {
                        exitToSetup()
                    } else if (action === "endEarly") {
                        void finish(results)
                    }
                }}
            />
        </>
    )

    // ΓöÇΓöÇ FALLBACK: card has no clozable key terms ΓåÆ plain flip + self-grade ΓöÇΓöÇ
    if (!cloze) {
        return (
            <Box className={className}>
                <StackV gap={1} items={[
                    () => header,
                    () => (
                        // teacher-hold: flashcards-remain-quiz-session-body-inset ΓÇö asymmetric session-body
                        // inset owned via Box page-pad escape hatch (pt-10 not in the padding scale).
                        <Box principle="page-pad" className="px-4 pb-6 pt-10 @app-sm:px-6">
                            <Container size="md" padding={1} body={() => (
                                <StackV gap={6} items={[
                                    () => (
                                        <FlipCard
                                            revealed={showAnswer}
                                            questionLabel={t("flashcard.questionLabel")}
                                            answerLabel={t("flashcard.answerLabel")}
                                            front={() => <MarkdownContent plain markdown={card.question} />}
                                            belowFront={card.level || (card.tags?.length ?? 0) > 0 ? () => {
                                                const level = card.level
                                                return (
                                                    <Cluster gap={3} principle="chip-row" align="center" items={[
                                                        ...(level ? [() => (
                                                            <Chip size="sm" variant="soft" color={LEVEL_COLOR[level] ?? "default"}>
                                                                {t(`flashcard.level.${level}`)}
                                                            </Chip>
                                                        )] : []),
                                                        ...(card.tags ?? []).map((tag) => () => (
                                                            <Chip key={tag} size="sm" variant="soft" color="default">
                                                                {tag}
                                                            </Chip>
                                                        )),
                                                    ]} />
                                                )
                                            } : undefined}
                                            back={() => (
                                                <>
                                                    {card.answer ? (
                                                        <MarkdownContent plain markdown={card.answer} arcSections />
                                                    ) : (
                                                        <Typography type="body-sm" color="muted">
                                                            {t("flashcard.noAnswer")}
                                                        </Typography>
                                                    )}
                                                    {card.explanation ? <MarkdownContent plain markdown={card.explanation} /> : null}
                                                </>
                                            )}
                                        />
                                    ),
                                    ...(showAnswer ? [() => (
                                        <StackV gap={4} principle="label-field" items={[
                                            () => <Label>{t("flashcard.review.rateHint")}</Label>,
                                            () => (
                                                <RatingBar
                                                    options={ratingOptions}
                                                    onRate={(grade) => void commitCard(grade, null)}
                                                    ariaLabel={t("flashcard.review.rateAria")}
                                                    isPending={rating}
                                                />
                                            ),
                                        ]} />
                                    )] : [() => (
                                        <StackH gap={4} principle="flex-action" justify="end" items={[() => (
                                            <Button size="sm" variant="outline" onPress={() => setShowAnswer(true)}>
                                                {t("flashcard.showAnswer")}
                                            </Button>
                                        )]} />
                                    )]),
                                ]} />
                            )} />
                        </Box>
                    ),
                ]} />
            </Box>
        )
    }

    // ΓöÇΓöÇ CLOZE: fill blanks ΓåÆ check ΓåÆ read full answer ΓåÆ SM-2 ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
    const allFilled = filled.every((value) => value !== null)
    // `cloze.blanks[blankIndex]?.` guards the same transient-render crash as
    // `filled[segment.index] ?? null` above: for one render tick right after
    // `commitCard` advances to the next card, `cloze` has ALREADY recomputed
    // for it (possibly with FEWER blanks) while `filled`/`checked` still hold
    // the PREVIOUS (possibly longer) card's values ΓÇö `cloze.blanks[blankIndex]`
    // then reads `undefined` for an out-of-range index, crashing on
    // `.toLowerCase()`. Optional-chaining just makes that comparison `false`
    // for this one tick; the reset effect below realigns everything right after.
    const correctCount = checked
        ? filled.filter((value, blankIndex) =>
            value !== null && value.toLowerCase() === cloze.blanks[blankIndex]?.toLowerCase(),
        ).length
        : 0
    const coverageRatio = cloze.blanks.length > 0 ? correctCount / cloze.blanks.length : 0

    return (
        // scoped per-card (`card.id`) so the word-bank Γåö blank `layoutId` FLIP never
        // leaks its animation into the NEXT card's chips once `cloze` recomputes.
        <LayoutGroup id={`quiz-cloze-${card.id}`}>
            <Box className={className}>
                <StackV gap={1} items={[
                    () => header,
                    () => (
                        // teacher-hold: flashcards-remain-quiz-session-body-inset ΓÇö asymmetric session-body
                        // inset owned via Box page-pad escape hatch (pt-10 not in the padding scale).
                        <Box principle="page-pad" className="px-4 pb-6 pt-10 @app-sm:px-6">
                            <Container size="md" padding={1} body={() => (
                                <StackV gap={6} items={[
                                    () => (
                                        <StackV gap={4} principle="card-caption" items={[
                                            () => (
                                                <LabeledCard label={t("flashcard.questionLabel")} bordered>
                                                    <MarkdownContent plain markdown={card.question} />
                                                </LabeledCard>
                                            ),
                                            ...(card.level || (card.tags?.length ?? 0) > 0 ? [() => {
                                                const level = card.level
                                                return (
                                                    <Cluster gap={3} principle="chip-row" align="center" items={[
                                                        ...(level ? [() => (
                                                            <Chip size="sm" variant="soft" color={LEVEL_COLOR[level] ?? "default"}>
                                                                {t(`flashcard.level.${level}`)}
                                                            </Chip>
                                                        )] : []),
                                                        ...(card.tags ?? []).map((tag) => () => (
                                                            <Chip key={tag} size="sm" variant="soft" color="default">
                                                                {tag}
                                                            </Chip>
                                                        )),
                                                    ]} />
                                                )
                                            }] : []),
                                        ]} />
                                    ),
                                    () => (
                                        <LabeledCard label={t("flashcard.quiz.fillLabel")} bordered>
                                            <StackV gap={4} principle="sibling-stack" items={[
                                                () => (
                                                    <Typography type="body-xs" weight="medium" color="muted">
                                                        {t("flashcard.quiz.clozeInstruction")}
                                                    </Typography>
                                                ),
                                                () => (
                                                    <p className="text-base leading-loose text-foreground">
                                                        {cloze.segments.map((segment, position) =>
                                                            segment.kind === "text" ? (
                                                                <span key={position}>{segment.text}</span>
                                                            ) : segment.kind === "code" ? (
                                                            // same inline-code styling as MarkdownContent's own renderer
                                                            // (reuseable/MarkdownContent/map.tsx) ΓÇö kept consistent since this
                                                            // sentence sits right next to the question's own MarkdownContent.
                                                                <code
                                                                    key={position}
                                                                    className="rounded-md bg-default font-mono text-sm text-foreground [overflow-wrap:anywhere]"
                                                                >
                                                                    {segment.text}
                                                                </code>
                                                            ) : segment.kind === "bold" ? (
                                                                <strong key={position} className="font-semibold">{segment.text}</strong>
                                                            ) : segment.kind === "italic" ? (
                                                                <em key={position}>{segment.text}</em>
                                                            ) : (
                                                                (() => {
                                                                    // `?? null` guards a real crash: for one render tick right after
                                                                    // `commitCard` advances `index` (before the card-change effect
                                                                    // resets `filled`), `cloze` has ALREADY recomputed for the new
                                                                    // (possibly longer) card while `filled` still holds the previous
                                                                    // card's (possibly shorter) array ΓÇö `filled[segment.index]` then
                                                                    // reads `undefined`, which slips past a `!== null` guard and
                                                                    // crashes on `.toLowerCase()`. Coercing to `null` here makes every
                                                                    // downstream `=== null` check treat it the same as "not filled yet".
                                                                    const value = filled[segment.index] ?? null
                                                                    const isCorrect =
                                        checked
                                        && value !== null
                                        && value.toLowerCase() === cloze.blanks[segment.index].toLowerCase()
                                        // empty = dashed-outline "slot" chip, filled surface (canon
                                        // `input.md` ┬º1 ΓÇö a fill-in affordance sitting on a surface must
                                        // have a real bg-surface fill, never bg-transparent, or it reads
                                        // as a dead patch of the page instead of a field); filled +
                                        // unchecked = solid accent (primary-solid ΓÇö canon
                                        // `elements/color.md` ┬º3, NOT a `/10` tint); checked = keep the
                                        // existing success/danger tint + shake/pop animation.
                                                                    const chipToneClassName = value === null
                                                                        ? "border border-dashed border-default bg-surface text-muted"
                                                                        : !checked
                                                                            ? "border-0 bg-accent text-accent-foreground"
                                                                            : isCorrect
                                                                                ? "border border-success/60 bg-success-soft text-success-soft-foreground motion-safe:[animation:blankPop_0.35s_ease]"
                                                                                : "border border-danger/60 bg-danger-soft text-danger-soft-foreground motion-safe:[animation:blankShake_0.4s_ease]"
                                                                    // shared `layoutId` with the SAME term's word-bank chip below ΓÇö when
                                                                    // `placeTerm`/`clearBlank` swaps `value`, framer-motion FLIPs the
                                                                    // chip's bounding box across the two positions ("flies" into/out of
                                                                    // the slot). `undefined` while empty ΓÇö nothing to morph from/to yet.
                                                                    const layoutId = value !== null ? `quiz-term-${card.id}-${value}` : undefined
                                                                    return (
                                                                        <motion.span
                                                                            key={position}
                                                                            layout
                                                                            layoutId={layoutId}
                                                                            transition={reduceMotion ? { duration: 0 } : CLOZE_CHIP_TRANSITION}
                                                                            className="mx-1 inline-block align-middle"
                                                                        >
                                                                            <button
                                                                                type="button"
                                                                                disabled={checked || value === null}
                                                                                onClick={() => clearBlank(segment.index)}
                                                                                className={!checked && value !== null ? "cursor-pointer" : undefined}
                                                                            >
                                                                                <Chip
                                                                                    size="sm"
                                                                                    // HeroUI bakes `.chip`/`.chip--sm`'s font-size as an
                                                                                    // UNLAYERED style (same trap as radius.md's rounded-*
                                                                                    // warning) ΓÇö a `text-sm` utility class silently loses
                                                                                    // to it. Only an inline style (always highest
                                                                                    // specificity) actually overrides it; reuse the
                                                                                    // design system's own `--text-sm` token, not a raw px.
                                                                                    // teacher-hold: flashcards-remain-quiz-cloze-vendor-chip-pad
                                                                                    style={{ fontSize: "var(--text-sm)" }}
                                                                                    className={cn(
                                                                                        "min-w-16 justify-center rounded-full font-medium transition-colors",
                                                                                        chipToneClassName,
                                                                                    )}
                                                                                >
                                                                                    {value ?? "┬╖┬╖┬╖"}
                                                                                </Chip>
                                                                            </button>
                                                                        </motion.span>
                                                                    )
                                                                })()
                                                            ),
                                                        )}
                                                    </p>
                                                ),
                                                ...(checked && correctCount < cloze.blanks.length ? [() => (
                                                    <Typography type="body-xs" color="muted">
                                                        {t("flashcard.quiz.clozeResult", {
                                                            correct: correctCount,
                                                            total: cloze.blanks.length,
                                                        })}
                                                    </Typography>
                                                )] : []),
                                            ]} />
                                        </LabeledCard>
                                    ),
                                    ...(!checked ? [() => (
                                        <StackV gap={6} items={[
                                            () => (
                                                <StackV gap={4} principle="label-field" items={[
                                                    () => <Label>{t("flashcard.quiz.wordBankLabel")}</Label>,
                                                    () => (
                                                        <Cluster gap={3} principle="chip-row" align="center" items={
                                                            cloze.bank
                                                                .filter((term) => !filled.includes(term))
                                                                .map((term) => () => (
                                                                    <motion.button
                                                                        key={term}
                                                                        type="button"
                                                                        layout
                                                                        layoutId={`quiz-term-${card.id}-${term}`}
                                                                        transition={reduceMotion ? { duration: 0 } : CLOZE_CHIP_TRANSITION}
                                                                        onClick={() => placeTerm(term)}
                                                                        className="cursor-pointer transition-transform hover:-translate-y-0.5"
                                                                    >
                                                                        <Chip
                                                                            size="sm"
                                                                            // teacher-hold: flashcards-remain-quiz-cloze-vendor-chip-pad ΓÇö
                                                                            // HeroUI Chip internal pad, not a sibling layout seam.
                                                                            className="rounded-full border border-default bg-surface text-sm font-medium"
                                                                        >
                                                                            {term}
                                                                        </Chip>
                                                                    </motion.button>
                                                                ))
                                                        } />
                                                    ),
                                                ]} />
                                            ),
                                            () => (
                                                <Button
                                                    variant="primary"
                                                    className="self-start"
                                                    isDisabled={!allFilled}
                                                    onPress={() => setChecked(true)}
                                                >
                                                    {t("flashcard.quiz.checkAnswer")}
                                                </Button>
                                            ),
                                        ]} />
                                    )] : [() => (
                                        <StackV gap={6} items={[
                                            () => (
                                                <StackH gap={3} principle="icon-text" align="center" items={[
                                                    () => (correctCount === cloze.blanks.length ? (
                                                        <CheckCircleIcon className="size-5 text-success-soft-foreground" aria-hidden focusable="false" />
                                                    ) : (
                                                        <XCircleIcon className="size-5 text-danger-soft-foreground" aria-hidden focusable="false" />
                                                    )),
                                                    () => (
                                                        <Typography type="body-sm" weight="medium">
                                                            {t("flashcard.quiz.clozeResult", {
                                                                correct: correctCount,
                                                                total: cloze.blanks.length,
                                                            })}
                                                        </Typography>
                                                    ),
                                                ]} />
                                            ),
                                            ...(showAnswer ? [() => (
                                                <LabeledCard label={t("flashcard.answerLabel")} bordered>
                                                    <StackV gap={4} principle="sibling-stack" items={[
                                                        () => <MarkdownContent plain markdown={card.answer ?? ""} arcSections />,
                                                        ...(card.explanation ? [() => <MarkdownContent plain markdown={card.explanation ?? ""} />] : []),
                                                    ]} />
                                                </LabeledCard>
                                            )] : [() => (
                                                <Button
                                                    variant="outline"
                                                    className="self-start"
                                                    onPress={() => setShowAnswer(true)}
                                                >
                                                    {t("flashcard.quiz.showSolution")}
                                                </Button>
                                            )]),
                                            ...(showAnswer ? [() => (
                                                <StackV gap={4} principle="label-field" items={[
                                                    () => <Label>{t("flashcard.review.rateHint")}</Label>,
                                                    () => (
                                                        <RatingBar
                                                            options={ratingOptions}
                                                            onRate={(grade) => void commitCard(grade, coverageRatio)}
                                                            ariaLabel={t("flashcard.review.rateAria")}
                                                            isPending={rating}
                                                        />
                                                    ),
                                                ]} />
                                            )] : []),
                                        ]} />
                                    )]),
                                ]} />
                            )} />
                        </Box>
                    ),
                ]} />
            </Box>
        </LayoutGroup>
    )
}

"use client"

import React, { useEffect, useState } from "react"
import useSWR from "swr"
import { useLocale, useTranslations } from "next-intl"
import { usePathname, useRouter, useSearchParams } from "next/navigation"
import { EnrollGate } from "@/components/blocks/learn/EnrollGate"
import { LearnBreadcrumb } from "@/components/blocks/learn/LearnBreadcrumb"
import { FlashcardReviewer } from "./FlashcardReviewer"
import { FlashcardReviewerSkeleton } from "./FlashcardReviewer/FlashcardReviewerSkeleton"
import { QuizSession } from "./QuizSession"
import { QuizSessionSkeleton } from "./QuizSession/QuizSessionSkeleton"
import { FlashcardQuizResult } from "./FlashcardQuizResult"
import { FlashcardQuizResultSkeleton } from "./FlashcardQuizResult/FlashcardQuizResultSkeleton"
import { DueReview } from "./DueReview"
import { DueReviewHero } from "./DueReviewHero"
import { FlashcardStatsStrip } from "./FlashcardStatsStrip"
import { FlashcardDeckList } from "./FlashcardDeckList"
import { FlashcardMobileNav } from "./FlashcardMobileNav"
import { FlashcardReviewHistory } from "./FlashcardReviewHistory"
import { FlashcardReviewStats } from "./FlashcardReviewStats"
import { FlashcardSessionStats } from "./FlashcardSessionStats"
import { FlashcardSessionStatsSkeleton } from "./FlashcardSessionStats/FlashcardSessionStatsSkeleton"
import { useFlashcardNav, type FlashcardMode } from "@/hooks/useFlashcardNav"
import { PageHeader } from "@/components/blocks/layout/PageHeader"
import { StackV } from "@/components/frames/Stack"
import { TabsCard } from "@/components/blocks/navigation/TabsCard"
import { useAppSelector } from "@/redux/hooks"
import { useQueryCourseEnrollmentStatusSwr } from "@/hooks/swr/api/graphql/queries/useQueryCourseEnrollmentStatusSwr"
import { useQueryMyFlashcardReviewSessionBySessionIdSwr } from "@/hooks/swr/api/graphql/queries/useQueryMyFlashcardReviewSessionBySessionIdSwr"
import { useQueryMyFlashcardReviewSessionStatsBySessionIdSwr } from "@/hooks/swr/api/graphql/queries/useQueryMyFlashcardReviewSessionStatsBySessionIdSwr"
import { useQueryMyFlashcardQuizSessionBySessionIdSwr } from "@/hooks/swr/api/graphql/queries/useQueryMyFlashcardQuizSessionBySessionIdSwr"
import { queryFlashcardDeck } from "@/modules/api/graphql/queries/query-flashcard-deck"
import { pathConfig } from "@/resources/path"

/** Props for {@link FlashcardsPage}. */
export interface FlashcardsPageProps {
    /**
     * Present when reached via the dedicated `flashcards/quiz/sessions/[sessionId]`
     * route ΓÇö threaded straight through to {@link QuizSession}, which
     * rehydrates that server-persisted "Quick quiz" run (24h TTL) instead of
     * showing the setup screen. Mirrors `MockInterviewProps.resumeSessionId`.
     */
    resumeQuizSessionId?: string
    /**
     * Present when reached via the dedicated, resumable
     * `flashcards/review/sessions/[sessionId]` route ΓÇö covers BOTH a
     * single-deck "Study cards" run and the cross-deck "Due today" (due)
     * run; ONE shared live route/prop for both kinds now (teacher, 2026-07-11:
     * "drop the deck, session only" ΓÇö supersedes the earlier separate
     * `resumeReviewSessionId`/`resumeDueReviewSessionId` props and the
     * `decks/[deckId]` route segment). `FlashcardsPage` resolves which kind it is
     * (and the deck identity, when applicable) via
     * `myFlashcardReviewSessionBySessionId` ΓÇö the session already persists
     * that context server-side (teacher: "the session has already persisted everything"), no
     * `deckId` query hint needed ΓÇö before rendering `FlashcardReviewer` (deck)
     * or `DueReview` (due). Mirrors `resumeQuizSessionId`.
     */
    resumeStudySessionId?: string
    /**
     * Present when reached via the dedicated
     * `flashcards/quiz/sessions/[sessionId]/result` route ΓÇö renders
     * `FlashcardQuizResult` DIRECTLY, no in-progress check (2026-07-12). This
     * route only ever means "show the result"; `QuizSession` navigates here
     * once its completion mutation resolves. See that route's own doc for the
     * full root-cause this route split fixes.
     */
    resultQuizSessionId?: string
    /**
     * Present when reached via the dedicated
     * `flashcards/review/sessions/[sessionId]/result` route ΓÇö renders
     * `FlashcardSessionStats` DIRECTLY (covers both single-deck review and
     * cross-deck due), no in-progress check (2026-07-12). Mirrors
     * `resultQuizSessionId`.
     */
    resultStudySessionId?: string
}

/**
 * Course-level flashcards WORK PANE. The mode switch + deck list live in the
 * left rail (rendered by the learn layout, same as the content-map rail); this
 * page is the right pane and reads the active surface off the URL via
 * {@link useFlashcardNav}: study mode lands on an overview (today's due queue +
 * mastery), opens a deck's SM-2 reviewer, or runs the cross-deck due session;
 * quiz mode drills the chosen deck by voice.
 *
 * Back navigation from a sub-view: the due session uses the breadcrumb's
 * clickable "Review" crumb; a deck reviewer ALSO gets its own in-pane
 * `BackLink` (teacher, 2026-07-09: "both the review and quiz sections have no
 * back button") since it's reachable via a direct `/decks/[id]` URL, same
 * reasoning as `QuizSession`'s own exit link.
 * @param {FlashcardsPageProps} props Optional wrapper placement props.
 */
export const FlashcardsPage = ({
    resumeQuizSessionId,
    resumeStudySessionId,
    resultQuizSessionId,
    resultStudySessionId}: FlashcardsPageProps) => {
    const t = useTranslations()
    const locale = useLocale()
    const pathname = usePathname()
    const router = useRouter()
    const searchParams = useSearchParams()
    const courseId = useAppSelector((state) => state.course.entity?.id)
    // owning course slug ΓÇö the finished-session stats recap deep-links study
    // suggestions (RAG) back into the course with it.
    const courseDisplayId = useAppSelector((state) => state.course.displayId)
    const { mode, deckId, session, goMode, goDeck, goOverview } = useFlashcardNav()
    // resumed straight into a live "Quick quiz" (quiz) or "Study cards" (review/due)
    // run (via the dedicated `flashcards/{quiz,review}/sessions/[sessionId]`
    // routes) ΓÇö the session becomes a full-bleed focused work surface (its own
    // `WorkSessionHeader`), so the surrounding chrome (breadcrumb, mode tabs,
    // mobile nav, bounded column) steps aside instead of doubling up on the
    // session's own header.
    const isLive = Boolean(resumeQuizSessionId || resumeStudySessionId)
    // resolve WHICH kind a "Study cards" session id is (deck-review vs cross-deck
    // due) + the deck identity when applicable ΓÇö the session already persists
    // that context server-side (teacher, 2026-07-11: "drop the deck, session
    // only" + "the session has already persisted everything"), no `deckId` query hint needed.
    const studySessionContextSwr = useQueryMyFlashcardReviewSessionBySessionIdSwr(resumeStudySessionId, courseId)
    // recap stats for THAT session ΓÇö its `status` is how we tell a finished
    // (completed/abandoned) session apart from an in-progress one. A finished
    // session reached by direct URL/refresh must render the STATS recap, NOT be
    // handed to the reviewer (which would wrongly start a fresh session). The
    // sibling context query above resolves ANY status, so without this a revisit
    // used to fall through to `startSessionAndRedirect`.
    const sessionStatsSwr = useQueryMyFlashcardReviewSessionStatsBySessionIdSwr(resumeStudySessionId, courseId)
    const sessionStats = sessionStatsSwr.data
    // A revisit must resolve the session's STATUS before routing. Only a
    // POSITIVELY-confirmed `in_progress` session is handed to the reviewer /
    // DueReview (whose own effect self-resumes-or-starts). Anything else ΓÇö
    // finished (completed/abandoned), not-found, or status-not-yet-known ΓÇö must
    // NOT reach them, or their start-a-fresh-session effect fires and appends a
    // second `/sessions/ΓÇª` (the revisit crash). Hold the skeleton until known.
    const studyStatusKnown = Boolean(courseId) && !sessionStatsSwr.isLoading
        && !studySessionContextSwr.isLoading && Boolean(studySessionContextSwr.data)
    const studyIsInProgress = sessionStats?.status === "in_progress"
    // ... and the same gate for a resumed "Quick quiz" (quiz) id: a finished
    // (completed/abandoned) or unknown session reached by direct URL/refresh must
    // render the RESULT surface, NOT be handed to the live `QuizSession` (whose
    // resume effect only accepts an in-progress session and would otherwise
    // dead-end to setup ΓÇö the revisit dead-end this fixes). Status-agnostic query,
    // so a not-found id resolves too (ΓåÆ the result surface's own null fallback).
    const quizSessionSwr = useQueryMyFlashcardQuizSessionBySessionIdSwr(resumeQuizSessionId, courseId)
    const quizStatusKnown = Boolean(courseId) && !quizSessionSwr.isLoading
    const quizIsInProgress = quizSessionSwr.data?.status === "in_progress"
    // quiz is enrolled-only (it spends AI credits) ΓÇö gate the tab for trial viewers
    const enrollmentSwr = useQueryCourseEnrollmentStatusSwr()
    const isEnrolled = enrollmentSwr.data?.courseEnrollmentStatus?.data?.isEnrolled === true

    // once a resumed session's status resolves to "not in progress" (finished/
    // abandoned) at the LIVE route, redirect to the dedicated RESULT route
    // (2026-07-12) instead of rendering the result surface inline here ΓÇö ONE
    // place decides "is this session done" (the URL itself), so an old
    // bookmark to the live route, or a session that self-heals its stuck
    // completion on a later resume attempt, both converge on `/result`
    // instead of silently rendering results at the live URL forever (which
    // is exactly what made today's bugs hard to reproduce/trust ΓÇö F5 kept
    // landing back on ambiguous state). `replace` (not `push`) ΓÇö the live URL
    // was never a real navigation step the learner chose.
    useEffect(() => {
        if (!resumeStudySessionId || !studyStatusKnown || studyIsInProgress || !courseDisplayId) {
            return
        }
        router.replace(
            pathConfig().locale(locale).course(courseDisplayId).learn()
                .flashcards().due(resumeStudySessionId).result().build(),
        )
    }, [resumeStudySessionId, studyStatusKnown, studyIsInProgress, courseDisplayId, locale, router])

    useEffect(() => {
        if (!resumeQuizSessionId || !quizStatusKnown || quizIsInProgress || !courseDisplayId) {
            return
        }
        router.replace(
            pathConfig().locale(locale).course(courseDisplayId).learn()
                .flashcards().quiz(resumeQuizSessionId).result().build(),
        )
    }, [resumeQuizSessionId, quizStatusKnown, quizIsInProgress, courseDisplayId, locale, router])

    // which study-overview tab is active ("Review" / "History" / "Stats") ΓÇö
    // overview only (no deck open, no due session). Seeded from `?tab=` so a
    // shared/refreshed link lands back on the same tab ΓÇö mirrors QuizSession's
    // own `setupTab` (teacher, 2026-07-09: "for these numbers to actually mean
    // something, we need to add a step to build the History/Stats UI for Review").
    const [overviewTab, setOverviewTab] = useState<"overview" | "history" | "stats">(() => {
        const initial = searchParams.get("tab")
        return initial === "history" || initial === "stats" ? initial : "overview"
    })
    // Only the STUDY OVERVIEW owns the `?tab=` param. In quiz mode `QuizSession`
    // mirrors its OWN setup tab into `?tab=`, and while a deck/due session is open
    // there are no overview tabs at all ΓÇö so this effect MUST NOT run then, else two
    // components write the same param with different state and clobber each other in
    // a loop (teacher, 2026-07-13: "the history side here keeps glitching the url"). Gate on the
    // exact condition the overview `TabsCard` is rendered under (mode=study, no deck,
    // not a due run).
    const overviewTabsVisible = mode === "study" && session !== "due" && !deckId
    useEffect(() => {
        if (!overviewTabsVisible) {
            return
        }
        const want = overviewTab === "overview" ? null : overviewTab
        if (searchParams.get("tab") === want) {
            return
        }
        const params = new URLSearchParams(searchParams.toString())
        if (want) {
            params.set("tab", want)
        } else {
            params.delete("tab")
        }
        const qs = params.toString()
        router.replace(qs ? `${pathname}?${qs}` : pathname, { scroll: false })
    }, [overviewTabsVisible, overviewTab, pathname, searchParams, router])

    // deck name for the breadcrumb when reviewing one deck (shared SWR key with the
    // reviewer ΓåÆ one fetch). The reviewer owns the heavy card states.
    const { data: deckData } = useSWR(
        deckId ? ["flashcard-deck", deckId] : null,
        async () => {
            const response = await queryFlashcardDeck({
                request: { flashcardDeckId: deckId as string },
            })
            return response.data?.flashcardDeck.data ?? null
        },
    )

    // breadcrumb: a sub-view (deck / due session) inserts a clickable "Review" crumb
    // (ΓåÆ overview) + names the sub-view; the overview/quiz just end at "Review".
    const isDeck = mode === "study" && Boolean(deckId)
    const isDue = mode === "study" && session === "due"
    const breadcrumb = isDeck ? (
        <LearnBreadcrumb
            current={deckData?.title ?? t("flashcard.title")}
            section={{ label: t("flashcard.title"), onPress: goOverview }}
        />
    ) : isDue ? (
        <LearnBreadcrumb
            current={t("flashcard.due.label")}
            section={{ label: t("flashcard.title"), onPress: goOverview }}
        />
    ) : (
        <LearnBreadcrumb current={t("flashcard.title")} />
    )

    // dedicated RESULT route (2026-07-12) ΓÇö renders the result surface
    // directly, no in-progress check. This URL only ever means "show the
    // result"; both surfaces already handle not-found/degraded data via their
    // own `AsyncContent`.
    if (resultStudySessionId) {
        return (
            <div>
                {courseId ? (
                    <FlashcardSessionStats
                        sessionId={resultStudySessionId}
                        courseId={courseId}
                        courseDisplayId={courseDisplayId ?? ""}
                        onBack={goOverview}
                    />
                ) : (
                    // brief courseId-not-resolved-yet flash ΓÇö the stats surface's OWN
                    // shape, not the full live-session skeleton (header + card +
                    // buttons is the wrong shape for a result page).
                    <FlashcardSessionStatsSkeleton />
                )}
            </div>
        )
    }
    if (resultQuizSessionId) {
        return (
            <div>
                {courseId ? (
                    <FlashcardQuizResult
                        sessionId={resultQuizSessionId}
                        courseId={courseId}
                        courseDisplayId={courseDisplayId ?? ""}
                        onBack={goOverview}
                    />
                ) : (
                    <FlashcardQuizResultSkeleton />
                )}
            </div>
        )
    }

    // live "Quick quiz" run ΓÇö full-bleed work surface, its own `WorkSessionHeader`
    // IS the header, so the breadcrumb/PageHeader, mobile nav, and mode tabs
    // (all "which surface am I on" chrome) step aside; nothing to switch away
    // from mid-run. No bounded `max-w-3xl` column either ΓÇö matches the sticky
    // header band spanning edge-to-edge, same as `MockInterviewSession`.
    if (isLive) {
        return (
            <div>
                {resumeStudySessionId ? (
                    !studyStatusKnown || !studyIsInProgress ? (
                        // status not settled yet, OR resolved to "not in progress" ΓÇö the
                        // effect above is redirecting to `/result` in the latter case; hold
                        // the skeleton through both, never fall through to the reviewer
                        // before a POSITIVELY-confirmed in-progress session.
                        <FlashcardReviewerSkeleton />
                    ) : studySessionContextSwr.data?.kind === "deck" && studySessionContextSwr.data.deckId ? (
                        <FlashcardReviewer
                            key={studySessionContextSwr.data.deckId}
                            deckId={studySessionContextSwr.data.deckId}
                            sessionId={resumeStudySessionId}
                            onBack={goOverview}
                        />
                    ) : (
                        <DueReview onExit={goOverview} sessionId={resumeStudySessionId} />
                    )
                ) : !quizStatusKnown || !quizIsInProgress ? (
                    // status not settled yet, OR resolved to "not in progress" ΓÇö the effect
                    // above is redirecting to `/result` in the latter case; hold the
                    // skeleton through both, never hand a maybe-finished session to the
                    // live QuizSession (whose resume effect only accepts in-progress).
                    <QuizSessionSkeleton />
                ) : courseId ? (
                    <QuizSession
                        key={courseId}
                        courseId={courseId}
                        resumeSessionId={resumeQuizSessionId}
                    />
                ) : null}
            </div>
        )
    }

    return (
        <div>
            {/* header ΓåÆ content = gap-10 (named exception, fe/foundations/gap.md) ΓÇö
                everything under the header is ONE gap-6 content cluster */}
            <div className={"mx-auto flex max-w-3xl flex-col gap-10"}>
                <PageHeader
                    breadcrumb={breadcrumb}
                    title={t("flashcard.title")}
                    description={t("flashcard.subtitle")}
                />

                <StackV
                    gap={6}
                    items={[
                        () => <FlashcardMobileNav />,
                        () => (
                            <div className="hidden @app-lg:block">
                                <TabsCard
                                    variant="primary"
                                    leftTabs={{
                                        items: [
                                            { key: "study", label: t("flashcard.mode.study") },
                                            { key: "quiz", label: t("flashcard.mode.quiz") },
                                        ],
                                        selectedKey: mode,
                                        ariaLabel: t("flashcard.title"),
                                        onSelectionChange: (key) => goMode(key as FlashcardMode),
                                    }}
                                />
                            </div>
                        ),
                        () => (
                            mode === "study" ? (
                                session === "due" ? (
                                    <DueReview onExit={goOverview} />
                                ) : deckId ? (
                                    // keyed so switching decks resets the reviewer's local state
                                    <FlashcardReviewer key={deckId} deckId={deckId} onBack={goOverview} />
                                ) : (
                                    <StackV
                                        gap={6}
                                        items={[
                                            () => (
                                                <TabsCard
                                                    variant="secondary"
                                                    className="w-full"
                                                    leftTabs={{
                                                        items: [
                                                            { key: "overview", label: t("flashcard.review.overviewTabOverview") },
                                                            { key: "history", label: t("flashcard.review.overviewTabHistory") },
                                                            { key: "stats", label: t("flashcard.review.overviewTabStats") },
                                                        ],
                                                        selectedKey: overviewTab,
                                                        ariaLabel: t("flashcard.review.overviewTabOverview"),
                                                        onSelectionChange: (key) => setOverviewTab(key as "overview" | "history" | "stats"),
                                                    }}
                                                />
                                            ),
                                            () => (
                                                overviewTab === "history" ? (
                                                    courseId ? (
                                                        <FlashcardReviewHistory
                                                            courseId={courseId}
                                                            onStartReview={() => setOverviewTab("overview")}
                                                        />
                                                    ) : null
                                                ) : overviewTab === "stats" ? (
                                                    courseId ? (
                                                        <FlashcardReviewStats
                                                            courseId={courseId}
                                                            onStartReview={() => setOverviewTab("overview")}
                                                        />
                                                    ) : null
                                                ) : (
                                                    <>
                                                        {/* today's spaced-repetition queue + mastery overview */}
                                                        <DueReviewHero />
                                                        <FlashcardStatsStrip />
                                                        {/* deck topic picker ΓÇö now in the pane (rail dropped) */}
                                                        <FlashcardDeckList onSelectDeck={goDeck} />
                                                    </>
                                                )
                                            ),
                                        ]}
                                    />
                                )
                            ) : !isEnrolled ? (
                                // trial viewer ΓåÆ lock the quiz behind an enroll CTA
                                <EnrollGate
                                    title={t("flashcard.quiz.gateTitle")}
                                    description={t("flashcard.quiz.gateDescription")}
                                />
                            ) : courseId ? (
                                // a fixed-length random session over the whole course (no per-deck
                                // topic pick); keyed by course so it resets
                                <QuizSession
                                    key={courseId}
                                    courseId={courseId}
                                    resumeSessionId={resumeQuizSessionId}
                                />
                            ) : null
                        ),
                    ]}
                />
            </div>
        </div>
    )
}

"use client"

import React, {
    useCallback,
    useMemo,
    useState,
} from "react"
import {
    useLocale,
    useTranslations,
} from "next-intl"
import {
    useRouter,
} from "next/navigation"
import {
    pathConfig,
} from "@/resources/path"
import {
    KPI_META,
} from "@/modules/utils/kpi-meta"
import {
    DEFAULT_KPI_TARGETS,
} from "@/modules/utils/weekly-goals-map"
import { useQueryMyKpisSwr } from "@/hooks/swr/api/graphql/queries/useQueryMyKpisSwr"
import { useMutateSetKpiTargetSwr } from "@/hooks/swr/api/graphql/mutations/useMutateSetKpiTargetSwr"
import { useMutateClaimKpiRewardSwr } from "@/hooks/swr/api/graphql/mutations/useMutateClaimKpiRewardSwr"
import type { KpiKey, QueryKpiItemData } from "@/modules/api/graphql/queries/types/my-kpis"
import { useGraphQLWithToast } from "@/modules/toast/hooks"
import type { AllowedClassName } from "@/components/atoms/_allowed-class-name"
import { _KpiPage, type KpiRowData } from "./component"

/**
 * Props for {@link KpiPage}. Only positioning ΓÇö the route hands this nothing else, it
 * self-fetches. Renamed from the old `className: string` to the house
 * `classNames: Array<AllowedClassName>` convention every frame/atom already uses.
 */
export interface KpiPageProps {
    /** Where this sits inside its parent. Appearance is not passable ΓÇö it is already a prop. */
    classNames?: Array<AllowedClassName>
}

/**
 * The `/kpi` editor page: the connected half of {@link _KpiPage}. Self-fetches the
 * weekly KPIs, owns the set-target + claim-reward mutations, resolves every
 * label (incl. interpolation), and hands them to the presentational `_KpiPage`.
 * See `tiers/split.md`.
 *
 * @param props - {@link KpiPageProps}
 */
export const KpiPage = ({
    classNames,
}: KpiPageProps) => {
    const t = useTranslations()
    const locale = useLocale()
    const router = useRouter()
    const { data, error, mutate } = useQueryMyKpisSwr()
    const { trigger: triggerSetTarget } = useMutateSetKpiTargetSwr()
    const { trigger: triggerClaimReward } = useMutateClaimKpiRewardSwr()
    const runGraphQL = useGraphQLWithToast()
    // the `${key}:${preset}` currently being saved, or null when idle
    const [savingKey, setSavingKey] = useState<string | null>(null)
    // the KPI key currently being claimed, or null when idle
    const [claimingKey, setClaimingKey] = useState<KpiKey | null>(null)

    /** Navigate to the DashboardPage (breadcrumb root). */
    const onNavigateHome = useCallback(
        () => router.push(pathConfig().locale(locale).build()),
        [router, locale],
    )

    /** Index the KPI items by key for O(1) lookup while rendering meta order. */
    const itemByKey = useMemo(
        () => {
            const map = new Map<KpiKey, QueryKpiItemData>()
            for (const item of data?.items ?? []) {
                map.set(item.key, item)
            }
            return map
        },
        [
            data,
        ],
    )

    /** Persist a chosen target for one KPI, then revalidate. */
    const onChoose = useCallback(
        async (key: KpiKey, target: number) => {
            setSavingKey(`${key}:${target}`)
            try {
                const ok = await runGraphQL(async () => {
                    const result = await triggerSetTarget({
                        key,
                        target,
                    })
                    const env = result?.data?.setKpiTarget
                    if (!env) {
                        throw new Error(t("DashboardPage.kpi.error"))
                    }
                    // returned envelope drives the success / error toast
                    return env
                })
                if (ok) {
                    await mutate()
                }
            } finally {
                setSavingKey(null)
            }
        },
        [
            triggerSetTarget,
            mutate,
            runGraphQL,
        ],
    )

    /** Claim one KPI's coin reward, then revalidate. */
    const onClaim = useCallback(
        async (key: KpiKey) => {
            setClaimingKey(key)
            try {
                const ok = await runGraphQL(async () => {
                    const result = await triggerClaimReward({
                        key,
                    })
                    const env = result?.data?.claimKpiReward
                    if (!env) {
                        throw new Error(t("DashboardPage.kpi.error"))
                    }
                    return env
                })
                if (ok) {
                    await mutate()
                }
            } finally {
                setClaimingKey(null)
            }
        },
        [
            triggerClaimReward,
            mutate,
            runGraphQL,
            t,
        ],
    )

    // days/hours left until the weekly reset ΓÇö mirrors WeeklyBoard/WeeklyGoals
    const remaining = data ? Math.max(0, new Date(data.resetAt).getTime() - Date.now()) : 0
    const countdown = {
        days: Math.floor(remaining / 86_400_000),
        hours: Math.floor((remaining % 86_400_000) / 3_600_000),
    }

    // composite-score sentence (or the plain subtitle before any target is set) + the reset countdown
    const description = data
        ? (data.composite.total > 0
            ? t("DashboardPage.kpi.summary", {
                percent: data.composite.percent,
                completed: data.composite.completed,
                total: data.composite.total,
            })
            : t("DashboardPage.kpi.subtitle")) + ` ┬╖ ${t("DashboardPage.kpi.resetIn", {
            days: countdown.days,
            hours: countdown.hours,
        })}`
        : ""

    // one resolved row per weekly KPI, meta order ΓÇö presets carry their disabled
    // state pre-computed (a global save lock, matching the pre-split behaviour:
    // saving ANY preset on ANY row locks every OTHER preset everywhere).
    const rows: Array<KpiRowData> = KPI_META.map(({ key, Icon, labelKey, presets }) => {
        const item = itemByKey.get(key)
        const current = item?.current ?? 0
        // effective target = the learner's custom goal, or a sensible default
        // (mirrors the DashboardPage card ΓÇö meter always runs, never sits empty waiting for config)
        const target = item?.target ?? DEFAULT_KPI_TARGETS[key]
        return {
            key,
            icon: Icon,
            label: t(`DashboardPage.kpi.labels.${labelKey}`),
            current,
            target,
            presets: presets.map((preset) => ({
                value: preset,
                isDisabled: savingKey !== null && savingKey !== `${key}:${preset}`,
            })),
            onChoosePreset: (chosenTarget: number) => {
                void onChoose(key, chosenTarget)
            },
            coinRewardText: item?.coinReward != null
                ? t("DashboardPage.kpi.coinReward", {
                    count: item.coinReward,
                })
                : undefined,
            claimed: item?.claimed ?? false,
            canClaim: item?.canClaim ?? false,
            isClaiming: claimingKey === key,
            isClaimDisabled: claimingKey !== null && claimingKey !== key,
            onClaim: () => {
                void onClaim(key)
            },
        }
    })

    return (
        <_KpiPage
            // first load with no cached data ΓåÆ skeleton; a first-load query error
            // shows the retryable error slot instead of a permanent skeleton
            isSkeleton={!data}
            error={!data ? error : undefined}
            onRetry={() => {
                void mutate()
            }}
            onNavigateHome={onNavigateHome}
            rows={rows}
            classNames={classNames}
            labels={{
                title: t("DashboardPage.kpi.title"),
                tooltipDescription: t("DashboardPage.kpi.help"),
                homeLabel: t("nav.home"),
                description,
                errorTitle: t("DashboardPage.loadError"),
                retry: t("DashboardPage.retry"),
                claimLabel: t("DashboardPage.kpi.claimReward"),
                claimedLabel: t("DashboardPage.kpi.claimed"),
            }}
        />
    )
}

"use client"

import React from "react"
import { Handle, type NodeProps, Position } from "@xyflow/react"
import { Button, Typography, cn } from "@heroui/react"
import { ArrowRightIcon } from "@phosphor-icons/react"
import { useTranslations } from "next-intl"
import { TRACK_CONFIG, NODE_DEGREE, bubbleRadius, type TrackKey } from "@/modules/utils/knowledge-graph-data"
import { LANDING_TRACK_TAG } from "@/modules/utils/landing-constants"

/** React Flow node-type id for a knowledge-graph concept. */
export const CONCEPT_NODE_TYPE = "concept" as const

/** Data carried on a concept node. */
export interface ConceptNodeData {
    label: string
    track: TrackKey
    /** Dim when another node is hovered and this one isn't connected to it. */
    dimmed?: boolean
    /** This node is the one whose popover is open. */
    selected?: boolean
    /** Open the flagship course that teaches this concept. */
    onOpenCourse?: (track: TrackKey) => void
    [key: string]: unknown
}

/** Centred, invisible handle ΓÇö kept for layout/positioning only (no edges are drawn). */
const centreHandleClass = "!size-0 !min-w-0 !border-0 !bg-transparent"
const centreHandleStyle = { left: "50%", top: "50%", transform: "translate(-50%, -50%)" } as const

/**
 * A glowing concept BUBBLE ΓÇö a translucent track-coloured circle sized by its degree
 * (hubs big, leaves small) + soft glow + colored ring, with the label CENTRED on it,
 * its font scaled by the same degree (hub labels read bigger). No connecting edges ΓÇö
 * a pure constellation. When `selected`, a popover floats above with a one-line blurb
 * (i18n by node id) + an "Enter course" CTA.
 *
 * @param props - React Flow {@link NodeProps} carrying {@link ConceptNodeData}.
 */
export const ConceptNode = ({ id, data }: NodeProps) => {
    const { label, track, dimmed, selected, onOpenCourse } = data as ConceptNodeData
    const t = useTranslations()
    const cfg = TRACK_CONFIG[track]
    const degree = NODE_DEGREE[id] ?? 1
    const r = bubbleRadius(degree)
    const fontSize = Math.round(11 + degree * 0.8)
    return (
        <div
            className={cn("relative cursor-pointer transition-opacity duration-300", dimmed && "opacity-25")}
            style={{ width: r * 2, height: r * 2 }}
        >
            {/* bubble ΓÇö diameter Γê¥ degree; translucent track fill + colored ring + soft glow */}
            <div
                className={cn("absolute inset-0 rounded-full border", cfg.ring, selected && "ring-2 ring-accent")}
                style={{
                    backgroundColor: `color-mix(in oklch, ${cfg.glow} 22%, transparent)`,
                    boxShadow: `0 0 ${Math.round(r * 0.9)}px -2px ${cfg.glow}`,
                }}
            >
                <Handle type="target" position={Position.Top} isConnectable={false} className={centreHandleClass} style={centreHandleStyle} />
                <Handle type="source" position={Position.Bottom} isConnectable={false} className={centreHandleClass} style={centreHandleStyle} />
            </div>
            {/* label centred ON the bubble; font scales with degree (may overflow small bubbles) */}
            <span
                className="pointer-events-none absolute left-1/2 top-1/2 -translate-x-1/2 -translate-y-1/2 text-center font-medium whitespace-nowrap text-foreground"
                style={{ fontSize }}
            >
                {label}
            </span>

            {selected ? (
                <div
                    data-principle="cell-pad" className="nodrag nopan absolute bottom-full left-1/2 z-50 mb-2 w-60 -translate-x-1/2 cursor-default rounded-2xl border border-default bg-surface p-3 text-left"

                    onClick={(event) => event.stopPropagation()}
                >
                    <div data-principle="identity" className="mb-1 flex items-center gap-2">
                        <span aria-hidden className={cn("size-1.5 shrink-0 rounded-full", cfg.dot)} />
                        <span className="text-xs font-semibold text-foreground">{label}</span>
                        <span data-principle="push-end" className="ml-auto text-[10px] text-muted">{LANDING_TRACK_TAG[track]}</span>
                    </div>
                    <Typography type="body-xs" color="muted" className="whitespace-normal">
                        {t(`landing.treasure.graph.${id}`)}
                    </Typography>
                    <Button variant="primary" size="sm" className="mt-2" onPress={() => onOpenCourse?.(track)}>
                        {t("landing.courses.view")}
                        <ArrowRightIcon aria-hidden focusable="false" className="size-3.5" />
                    </Button>
                </div>
            ) : null}
        </div>
    )
}

"use client"

import React, { useCallback, useEffect, useMemo, useRef, useState } from "react"
import {
    Background,
    BackgroundVariant,
    type Edge,
    type Node,
    type NodeMouseHandler,
    Panel,
    ReactFlow,
    ReactFlowProvider,
    useEdgesState,
    useNodesState,
    useReactFlow,
} from "@xyflow/react"
import { useLocale } from "next-intl"
import { useRouter } from "next/navigation"
import { useReducedMotion } from "framer-motion"
import { useTheme } from "next-themes"
import {
    forceCollide,
    forceLink,
    forceManyBody,
    forceSimulation,
    forceX,
    forceY,
    type Simulation,
    type SimulationLinkDatum,
    type SimulationNodeDatum,
} from "d3-force"
import { pathConfig } from "@/resources/path"
import { LANDING_TRACK_COURSE_SLUG } from "@/modules/utils/landing-constants"
import { CONCEPT_NODE_TYPE, type ConceptNodeData, ConceptNode } from "./ConceptNode"
import { ShuffleBeacon } from "./ShuffleBeacon"
import { KNOWLEDGE_EDGES, KNOWLEDGE_NODES, NODE_DEGREE, TRACK_CONFIG, bubbleRadius, type TrackKey } from "@/modules/utils/knowledge-graph-data"

/** A d3-force simulation node (positions written back onto React Flow each tick). */
interface SimNode extends SimulationNodeDatum {
    id: string
    track: TrackKey
}

/** Initial React Flow nodes ΓÇö seeded around the ANCHOR per track (3 colors, 3 triangle
 * corners), scattered over a small ring; the force then pulls each track back to its own
 * corner, while the space between corners blends together naturally. */
const buildInitialNodes = (): Node<ConceptNodeData>[] =>
    KNOWLEDGE_NODES.map((node, index) => {
        const cfg = TRACK_CONFIG[node.track]
        const angle = (index / KNOWLEDGE_NODES.length) * Math.PI * 2
        return {
            id: node.id,
            type: CONCEPT_NODE_TYPE,
            position: {
                x: cfg.anchorX + Math.cos(angle) * 130,
                y: cfg.anchorY + Math.sin(angle) * 130,
            },
            data: { label: node.label, track: node.track },
            draggable: true,
        }
    })

/** Edges ΓÇö ALL are light connecting lines (solid, thin, faint ΓÇö like sharding<->cdc); NO dashed, NO accent. */
const buildEdges = (): Edge[] =>
    KNOWLEDGE_EDGES.map((edge, index) => ({
        id: `e${index}`,
        source: edge.source,
        target: edge.target,
        type: "straight",
        style: { stroke: "var(--border)", strokeWidth: 1, strokeOpacity: 0.22 },
    }))

/** Per-node collide radius (px): bubble radius, but ΓëÑ half the label's width (the label is
 * CENTER-aligned and overflows past the bubble horizontally) so labels don't overlap their
 * neighbors. The pad keeps the bubble cluster feeling airy. */
const COLLIDE_RADIUS = new Map(
    KNOWLEDGE_NODES.map((node) => {
        const r = bubbleRadius(NODE_DEGREE[node.id] ?? 1)
        const labelHalfWidth = node.label.length * 3.4
        return [node.id, Math.max(r, labelHalfWidth) + 14] as const
    }),
)

/** Inner flow (needs to be inside {@link ReactFlowProvider} for `useReactFlow`). */
const KnowledgeGraphFlow = () => {
    const router = useRouter()
    const locale = useLocale()
    const { resolvedTheme } = useTheme()
    const reduce = useReducedMotion()
    const { setCenter } = useReactFlow()

    const [nodes, setNodes, onNodesChange] = useNodesState<Node<ConceptNodeData>>(buildInitialNodes())
    const [edges, , onEdgesChange] = useEdgesState(buildEdges())
    const [selectedId, setSelectedId] = useState<string | null>(null)
    const nodeTypes = useMemo(() => ({ [CONCEPT_NODE_TYPE]: ConceptNode }), [])

    // Re-shuffle = give every node a random velocity kick + reheat the sim ΓåÆ nodes drift
    // out and re-settle into a fresh arrangement (the beacon countdown / tap fires this).
    const reshuffle = useCallback(() => {
        const simulation = simRef.current
        if (!simulation) {
            return
        }
        simNodesRef.current.forEach((simNode) => {
            simNode.fx = null
            simNode.fy = null
            simNode.vx = (Math.random() - 0.5) * 200
            simNode.vy = (Math.random() - 0.5) * 200
        })
        simulation.alpha(1).restart()
    }, [])

    const simRef = useRef<Simulation<SimNode, undefined> | null>(null)
    const simNodesRef = useRef<Map<string, SimNode>>(new Map())
    const draggingRef = useRef<string | null>(null)

    // Live force layout: a d3-force simulation drives node positions; each tick writes
    // positions back to React Flow. The 3 tracks gravitate to their own x-anchor (loose
    // clusters) while charge + collide spread nodes and links pull related ones together.
    useEffect(() => {
        const simNodes: SimNode[] = buildInitialNodes().map((rfNode) => ({
            id: rfNode.id,
            track: rfNode.data.track,
            x: rfNode.position.x,
            y: rfNode.position.y,
        }))
        const byId = new Map(simNodes.map((simNode) => [simNode.id, simNode]))
        simNodesRef.current = byId

        const simLinks: SimulationLinkDatum<SimNode>[] = KNOWLEDGE_EDGES.map((edge) => ({
            source: edge.source,
            target: edge.target,
        }))

        const simulation = forceSimulation(simNodes)
            .force("charge", forceManyBody().strength(-100))
            .force("link", forceLink<SimNode, SimulationLinkDatum<SimNode>>(simLinks).id((node) => node.id).distance(90).strength(0.12))
            .force("x", forceX<SimNode>((node) => TRACK_CONFIG[node.track].anchorX).strength(0.05))
            .force("y", forceY<SimNode>((node) => TRACK_CONFIG[node.track].anchorY).strength(0.05))
            .force("collide", forceCollide<SimNode>((node) => COLLIDE_RADIUS.get(node.id) ?? 44))
            .alphaDecay(0.035)
        simRef.current = simulation

        const writeBack = () => setNodes((current) => current.map((rfNode) => {
            if (rfNode.id === draggingRef.current) return rfNode
            const simNode = byId.get(rfNode.id)
            return simNode ? { ...rfNode, position: { x: simNode.x ?? 0, y: simNode.y ?? 0 } } : rfNode
        }))
        simulation.on("tick", writeBack)

        // Camera: pushed in close to the cluster's center (zoom 1.2, center 0,0) ΓåÆ the 3-color
        // core converges to fill the frame, edges get cropped ΓåÆ drag (pan) to explore = a natural map feel.
        const centre = (duration: number) => void setCenter(0, 0, { zoom: 1.2, duration })

        const fits: ReturnType<typeof setTimeout>[] = []
        if (reduce) {
            simulation.stop()
            simulation.tick(300)
            writeBack()
            fits.push(setTimeout(() => centre(0), 0))
        } else {
            fits.push(setTimeout(() => centre(500), 600))
        }

        return () => {
            simulation.stop()
            fits.forEach(clearTimeout)
        }
    }, [setCenter, reduce, setNodes])

    // Drag pins the node (fx/fy) and reheats the sim; release lets it flow back.
    const onNodeDragStart: NodeMouseHandler = useCallback((_, node) => {
        draggingRef.current = node.id
        const simNode = simNodesRef.current.get(node.id)
        if (simNode) {
            simNode.fx = node.position.x
            simNode.fy = node.position.y
        }
        simRef.current?.alphaTarget(0.3).restart()
    }, [])
    const onNodeDrag: NodeMouseHandler = useCallback((_, node) => {
        const simNode = simNodesRef.current.get(node.id)
        if (simNode) {
            simNode.fx = node.position.x
            simNode.fy = node.position.y
        }
    }, [])
    const onNodeDragStop: NodeMouseHandler = useCallback((_, node) => {
        draggingRef.current = null
        const simNode = simNodesRef.current.get(node.id)
        if (simNode) {
            simNode.fx = null
            simNode.fy = null
        }
        simRef.current?.alphaTarget(0)
    }, [])

    // Click toggles a concept's popover (blurb + CTA); clicking empty pane closes it.
    const onNodeClick: NodeMouseHandler = useCallback((_, node) => {
        setSelectedId((prev) => (prev === node.id ? null : node.id))
    }, [])
    const onPaneClick = useCallback(() => setSelectedId(null), [])
    // CTA inside the popover ΓåÆ flagship course that teaches the concept (grounded).
    const onOpenCourse = useCallback(
        (track: TrackKey) => router.push(pathConfig().locale(locale).course(LANDING_TRACK_COURSE_SLUG[track]).build()),
        [router, locale],
    )
    // Inject per-render UI state (selected + CTA handler) into node data for the custom node.
    const displayNodes = useMemo(
        () => nodes.map((node) => ({
            ...node,
            // lift the open node (+ its popover) above every other node
            zIndex: node.id === selectedId ? 1000 : 0,
            data: { ...node.data, selected: node.id === selectedId, onOpenCourse },
        })),
        [nodes, selectedId, onOpenCourse],
    )

    return (
        <ReactFlow
            nodes={displayNodes}
            onPaneClick={onPaneClick}
            edges={edges}
            onNodesChange={onNodesChange}
            onEdgesChange={onEdgesChange}
            onNodeDragStart={onNodeDragStart}
            onNodeDrag={onNodeDrag}
            onNodeDragStop={onNodeDragStop}
            onNodeClick={onNodeClick}
            nodeTypes={nodeTypes}
            colorMode={resolvedTheme === "dark" ? "dark" : "light"}
            // @xyflow dark colorMode bakes a #141414 pane bg via this var ΓÇö force it
            // transparent so the graph blends into the page (starfield shows through).
            style={{ backgroundColor: "transparent", "--xy-background-color": "transparent" } as React.CSSProperties}
            proOptions={{ hideAttribution: true }}
            nodesConnectable={false}
            elementsSelectable={false}
            minZoom={1.2}
            maxZoom={1.2}
            // FIXED zoom; ALLOW drag (pan) to explore ΓÇö the cluster's edges get cropped = a natural feel
            zoomOnScroll={false}
            zoomOnPinch={false}
            zoomOnDoubleClick={false}
            preventScrolling={false}
            panOnDrag
            translateExtent={[[-1000, -820], [1000, 820]]}
        >
            <Background variant={BackgroundVariant.Dots} gap={22} size={1} className="opacity-40" />
            {/* DeFi-swap-style countdown beacon (bottom-left): auto-reshuffles the graph
                every 10s; tap it to reshuffle now. Signals the graph is live + interactive. */}
            <Panel position="bottom-left">
                <ShuffleBeacon onShuffle={reshuffle} />
            </Panel>
        </ReactFlow>
    )
}

