                        <KnowledgeGraph />
                    </div>
                </section>

                {/* 5 ΓÇö Founder beat */}
                <section id="founder" className="flex scroll-mt-24 flex-col gap-12">
                    <SectionHeading
                        anchorId="founder"
                        eyebrow={t("landing.founder.eyebrow")}
                        title={t("landing.founder.title")}
                        intro={t("landing.founder.thesis")}
                    />
                    {/* the uncomfortable truths are the hero; the founder recedes to a
                        byline (who's saying this), each truth anchored to a real mechanism */}
                    <TruthList
                        items={LANDING_FOUNDER_TRUTH_INDEXES.map((index) => ({
                            truth: t(`landing.founder.truth${index}`),
                            fix: t(`landing.founder.fix${index}`),
                        }))}
                        byline={(
                            <>
                                <IconTile
                                    size="sm"
                                    tone="accent"
                                    src="/landing/founder.jpg"
                                    alt={t("landing.founder.name")}
                                    icon={<UserIcon aria-hidden focusable="false" />}
                                />
                                <StackV gap={3} principle="sibling-stack" classNames={["min-w-0"]}
                                    explain="Same-kind peer stack ΓÇö not group-boundary, because these items are repeating siblings rather than section groups."
                                    items={[
                                        () => (
                                            <Typography type="body-sm" weight="semibold">
                                                {t("landing.founder.name")}
                                            </Typography>
                                        ),
                                        () => (
                                            <Typography type="body-xs" color="muted">
                                                {t("landing.founder.titles")}
                                            </Typography>
                                        ),
                                    ]} />
                                <div data-principle="content-row" className="flex items-center gap-3 @app-sm:ml-auto">
                                    {/* social proof ΓÇö brand icons (GitHub ┬╖ LinkedIn ┬╖ Facebook) */}
                                    {FOUNDER_SOCIALS.map(({ key, href, icon: Icon, label }) => (
                                        <Link
                                            key={key}
                                            href={href}
                                            target="_blank"
                                            aria-label={label}
                                            className="text-muted transition-colors hover:text-accent-soft-foreground"
                                        >
                                            <Icon aria-hidden className="size-4" />
                                        </Link>
                                    ))}
                                    {/* blog = "go read + judge the quality yourself" CTA */}
                                    <Link href={pathConfig().locale(locale).blog().build()} data-principle="flex-action" className="inline-flex items-center gap-2 text-accent-soft-foreground">
                                        {t("landing.founder.blog")}
                                        <ArrowRightIcon aria-hidden focusable="false" className="size-4" />
                                    </Link>
                                </div>
                            </>
                        )}
                    />
                </section>

                {/* 6 ΓÇö Two-sided talent marketplace (engineer outcome + recruiter browse, product-led) */}
                <TalentMarketplace />

                {/* 9 ΓÇö FAQ */}
                <section id="faq" className="flex scroll-mt-24 flex-col gap-12">
                    <SectionHeading
                        anchorId="faq"
                        eyebrow={t("landing.faq.eyebrow")}
                        title={t("landing.faq.title")}
                    />
                    <Accordion variant="surface">
                        {LANDING_FAQ_INDEXES.map((index) => (
                            <Accordion.Item key={index} aria-label={t(`landing.faq.q${index}`)}>
                                <Accordion.Heading>
                                    <Accordion.Trigger>
                                        <Typography type="body-sm" weight="medium">
                                            {t(`landing.faq.q${index}`)}
                                        </Typography>
                                    </Accordion.Trigger>
                                </Accordion.Heading>
                                <Accordion.Panel>
                                    <Accordion.Body>
                                        <Typography type="body-sm" color="muted">
                                            {t(`landing.faq.a${index}`)}
                                        </Typography>
                                    </Accordion.Body>
                                </Accordion.Panel>
                            </Accordion.Item>
                        ))}
                    </Accordion>
                </section>

                {/* 10 ΓÇö Closing CTA */}
                <StackV as="section" align="center" gap={6} principle="block-boundary"
                    explain="Block-to-block spacing ΓÇö not group-boundary, because this separates major blocks rather than nested section groups."
                    items={[
                        () => (
                            <StackV align="center" gap={4} principle="card-caption"
                                explain="Holds caption text under card media so the caption stays attached to the image above it."
                                items={[
                                    () => (
                                        <Typography.Heading level={2} weight="bold" align="center" className="max-w-2xl">
                                            {t("landing.closing.title")}
                                        </Typography.Heading>
                                    ),
                                    () => (
                                        <Typography type="body" color="muted" align="center" className="max-w-xl">
                                            {t("landing.closing.subtitle")}
                                        </Typography>
                                    ),
                                ]} />
                        ),
                        () => (
                            <Button variant="primary" size="lg" onPress={onSeeCourses}>
                                {t("landing.closing.cta")}
                                <CaretRightIcon aria-hidden focusable="false" weight="bold" className="size-4" />
                            </Button>
                        ),
                    ]} />
            </Box>

            {/* Back-to-top FAB ΓÇö floats bottom-right (primary accent), shows after scrolling past the first screen */}
            {showTop ? (
                <Button
                    isIconOnly
                    variant="primary"
                    aria-label={t("landing.backToTop")}
                    onPress={() => window.scrollTo({ top: 0, behavior: "smooth" })}
                    className="fixed bottom-6 right-[calc(var(--app-rail-w,0px)+1.5rem)] z-40 size-12 rounded-full shadow-lg"
                >
                    <ArrowUpIcon aria-hidden focusable="false" className="size-5" />
                </Button>
            ) : null}
        </div>
    )
}

"use client"

import React, {
    useState,
} from "react"
import {
    Input,
    Link,
    TextField,
    Typography,
} from "@heroui/react"
import {
    useTranslations,
} from "next-intl"
import {
    ArrowLeftIcon,
    BookOpenIcon,
    FlagIcon,
    ListBulletsIcon,
} from "@phosphor-icons/react"
import {
    CourseTrialChip,
} from "@/components/blocks/course/CourseTrialChip"
import {
    useSelectedCourse,
} from "@/hooks/useSelectedCourse"
import {
    CourseOutline,
} from "../CourseOutline"
import {
    CourseMilestoneOutline,
} from "../CourseMilestoneOutline"
import { useQueryMyCourseOutlineSwr } from "@/hooks/swr/api/graphql/queries/useQueryMyCourseOutlineSwr"
import { useQueryMyCoursesSwr } from "@/hooks/swr/api/graphql/queries/useQueryMyCoursesSwr"
import { AsyncContent } from "@/components/blocks/async/AsyncContent"
import { IconTile } from "@/components/blocks/identity/IconTile"
import { SegmentBar } from "@/components/composites/stats/SegmentBar"
import { Skeleton } from "@/components/blocks/skeleton/Skeleton"
import { TabsCard } from "@/components/blocks/navigation/TabsCard"
import { fromGlobalId } from "@/modules/utils/globalId"
import { Box } from "@/components/frames/Box"
import { StackH, StackV } from "@/components/frames/Stack"

/** Detail view tabs: course content vs the personal-project capstone. */
type DetailTab = "contents" | "personalProject"

/** Segment colour per course progress dimension. */
const DIM_COLOR: Record<string, string> = {
    content: "var(--accent)",
    challenge: "var(--success)",
    milestone: "var(--warning)",
}

/**
 * Per-course detail. A sticky course header ({@link IconTile} + title +
 * completion % + {@link SegmentBar} + a meta line of lessons / challenges /
 * milestones), a client search over the active tab, and a two-tab toggle ΓÇö both
 * tabs render an accordion-card off the SAME `myCourseOutline` payload:
 *
 *   - "Contents" (default): the {@link CourseOutline} module ΓåÆ lesson ΓåÆ
 *     challenge tree with read flags.
 *   - "Personal Project": the {@link CourseMilestoneOutline}
 *     milestone ΓåÆ task tree with a roll-up completion status per milestone.
 *
 * Reads the selected course globalId from `?course=` (decoded to the raw id for
 * the shared outline query in each tab).
 */
export const CourseDetail = () => {
    const t = useTranslations()
    const { selectedCourse, setSelectedCourse } = useSelectedCourse()
    const [tab, setTab] = useState<DetailTab>("contents")
    const [search, setSearch] = useState("")

    // decode the selected course globalId (CourseEntity:<id>) ΓåÆ raw id for the outline query
    const rawCourseId = selectedCourse ? fromGlobalId(selectedCourse)?.id ?? null : null
    const outlineSwr = useQueryMyCourseOutlineSwr(rawCourseId)
    const outline = outlineSwr.data
    // the outline payload has no cover; reuse the (cached) course list to show the real
    // course logo in the header IconTile, like the hub list does ΓÇö falls back to the book icon.
    const coursesSwr = useQueryMyCoursesSwr()
    const selectedCourseItem = (coursesSwr.data ?? [])
        .find((course) => course.globalId === selectedCourse)
    const courseThumbnailUrl = selectedCourseItem?.thumbnailUrl
    const query = search.trim().toLowerCase()

    const progress = outline?.progress
    const headerDims = progress
        ? [
            { key: "content", completed: progress.lessonsRead, total: progress.lessonsTotal },
            { key: "challenge", completed: progress.challengesCompleted, total: progress.challengesTotal },
            { key: "milestone", completed: progress.tasksCompleted, total: progress.tasksTotal },
        ]
        : []
    const headerTotal = headerDims.reduce((acc, dim) => acc + dim.total, 0)

    return (
        <StackV
            gap={6}
            principle="block-boundary"
            explain="Block-to-block spacing ΓÇö not group-boundary, because this separates major course-detail sections rather than nested section groups."
            items={[
                () => (
                    <Link onPress={() => { setSelectedCourse(null) }} className="text-sm text-muted">
                        <StackH
                            inline
                            gap={3}
                            principle="identity"
                            explain="Keeps avatar and identity text as one peer unit so the person label stays beside the face."
                            align="center"
                            items={[
                                () => <ArrowLeftIcon aria-hidden focusable="false" className="size-5" />,
                                () => <>{t("profileSettings.learning.history.title")}</>,
                            ]}
                        />
                    </Link>
                ),
                () => (
                    /* sticky course header ΓÇö title + progress + meta */
                    <Box principle="row-pad" className="sticky top-16 z-30 -mx-4 bg-background px-4 py-3"
                        explain="Row content inset ΓÇö not cell-pad, because this pads a horizontal content row rather than a dense table cell.">
                        <StackV gap={4} principle="content-row"
                            explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                            items={[
                                () => (
                                    <AsyncContent
                                        isLoading={outlineSwr.data === null || outlineSwr.data === undefined ? !outlineSwr.error : false}
                                        skeleton={(
                                            <StackH gap={4} principle="content-row"
                                                explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                                align="center" items={[
                                                    () => <Skeleton className="size-12 shrink-0 rounded-xl" />,
                                                    () => (
                                                        <StackV gap={3} principle="sibling-stack"
                                                            explain="Same-kind peer stack ΓÇö not group-boundary, because these items are repeating siblings rather than section groups."
                                                            classNames={["min-w-0", "flex-1"]} items={[
                                                                () => <Skeleton.Typography type="h4" width="1/2" />,
                                                                () => <Skeleton.ProgressBar />,
                                                            ]} />
                                                    ),
                                                ]} />
                                        )}
                                        isEmpty={!outline}
                                        emptyContent={{ title: t("profileSettings.learning.outline.empty") }}
                                        error={!outlineSwr.data ? outlineSwr.error : undefined}
                                        errorContent={{
                                            title: t("profileSettings.learning.outline.error"),
                                            onRetry: () => { void outlineSwr.mutate() },
                                            retryLabel: t("profileSettings.learning.loadMore"),
                                        }}
                                    >
                                        {outline && progress ? (
                                            <StackH gap={4} principle="content-row"
                                                explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                                align="center" items={[
                                                    () => <IconTile size="sm" src={courseThumbnailUrl} icon={<BookOpenIcon aria-hidden focusable="false" />} />,
                                                    () => (
                                                        <StackV gap={3} principle="sibling-stack"
                                                            explain="Same-kind peer stack ΓÇö not group-boundary, because these items are repeating siblings rather than section groups."
                                                            classNames={["min-w-0", "flex-1"]} items={[
                                                                () => (
                                                                    <StackH gap={3} principle="value-row"
                                                                        explain="Holds a label and its numeric value on one baseline so the count stays readable against the label."
                                                                        justify="between" align="center" items={[
                                                                            () => (
                                                                                <Typography type="h5" weight="bold" truncate className="min-w-0 flex-1">
                                                                                    {outline.course.title}
                                                                                </Typography>
                                                                            ),
                                                                            () => (selectedCourseItem ? <CourseTrialChip isEnrolled={selectedCourseItem.isEnrolled} /> : null),
                                                                            () => (
                                                                                <Typography type="body-xs" color="muted">
                                                                                    {`${progress.completionPercent}%`}
                                                                                </Typography>
                                                                            ),
                                                                        ]} />
                                                                ),
                                                                () => (
                                                                    <SegmentBar
                                                                        max={headerTotal || 1}
                                                                        hideLegend
                                                                        ariaLabel={`${outline.course.title} ┬╖ ${progress.completionPercent}%`}
                                                                        segments={headerDims.map((dim) => ({
                                                                            key: dim.key,
                                                                            label: t(`dashboard.courseProgress.${dim.key}`),
                                                                            value: dim.completed,
                                                                            color: DIM_COLOR[dim.key],
                                                                        }))}
                                                                    />
                                                                ),
                                                                () => (
                                                                    <Typography type="body-xs" color="muted">
                                                                        {t("profileSettings.learning.detail.meta", {
                                                                            lessonsRead: progress.lessonsRead,
                                                                            lessonsTotal: progress.lessonsTotal,
                                                                            challenges: progress.challengesCompleted,
                                                                            milestones: progress.tasksCompleted,
                                                                        })}
                                                                    </Typography>
                                                                ),
                                                            ]} />
                                                    ),
                                                ]} />
                                        ) : null}
                                    </AsyncContent>
                                ),
                            ]} />
                    </Box>
                ),
                () => (
                    /* search over the active tab (lessons or milestone tasks) */
                    <TextField variant="secondary">
                        <Input
                            aria-label={t("profileSettings.learning.detail.searchLessons")}
                            placeholder={t("profileSettings.learning.detail.searchLessons")}
                            value={search}
                            onChange={(event) => setSearch(event.target.value)}
                        />
                    </TextField>
                ),
                () => (
                    /* Contents vs Personal Project ΓÇö TabsCard pattern: tabs float ABOVE, each
                       tab below is its own accordion-card (Card p-0 skin owned by the view). */
                    <StackV gap={4} principle="content-row"
                        explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                        items={[
                            () => (
                                <TabsCard
                                    leftTabs={{
                                        items: [
                                            {
                                                key: "contents",
                                                label: t("profileSettings.learning.detail.contents"),
                                                icon: <ListBulletsIcon aria-hidden focusable="false" className="size-5 shrink-0" />,
                                            },
                                            {
                                                key: "personalProject",
                                                label: t("profileSettings.learning.detail.personalProject"),
                                                icon: <FlagIcon aria-hidden focusable="false" className="size-5 shrink-0" />,
                                            },
                                        ],
                                        selectedKey: tab,
                                        ariaLabel: t("profileSettings.learning.detail.viewToggle"),
                                        onSelectionChange: (key) => setTab(key as DetailTab),
                                    }}
                                />
                            ),
                            () => (tab === "contents" ? (
                                <CourseOutline search={query} />
                            ) : (
                                <CourseMilestoneOutline search={query} />
                            )),
                        ]} />
                ),
            ]}
        />
    )
}

"use client"

import React, {
    useMemo,
} from "react"
import {
    Chip,
    Typography,
    cn,
} from "@heroui/react"
import {
    useTranslations,
} from "next-intl"
import {
    CheckCircleIcon,
    CircleIcon,
    CircleHalfIcon,
} from "@phosphor-icons/react"
import {
    useSelectedCourse,
} from "@/hooks/useSelectedCourse"
import { useQueryMyCourseOutlineSwr } from "@/hooks/swr/api/graphql/queries/useQueryMyCourseOutlineSwr"
import { AsyncContent } from "@/components/blocks/async/AsyncContent"
import { AsyncContentEmpty } from "@/components/composites/async/AsyncContent"
import { ListRow } from "@/components/blocks/lists/ListRow"
import { LabeledAccordionCard } from "@/components/blocks/cards/LabeledAccordionCard"
import { Skeleton } from "@/components/blocks/skeleton/Skeleton"
import { StatusChip } from "@/components/blocks/chips/StatusChip"
import type { StatusChipTone } from "@/components/blocks/chips/StatusChip"
import { fromGlobalId } from "@/modules/utils/globalId"
import type { MyCourseOutlineMilestone, MyCourseOutlinePayload } from "@/modules/api/graphql/queries/types/my-course-outline"
import { Box } from "@/components/frames/Box"
import { StackH, StackV } from "@/components/frames/Stack"

/** Props for {@link CourseMilestoneOutline}. */
export interface CourseMilestoneOutlineProps {
    /**
     * Lower-cased trimmed search query. Milestones survive when their title matches
     * or any of their tasks match; surviving milestones keep only matching tasks.
     */
    search?: string
}

/** Number of placeholder accordion milestones shown while the outline loads. */
const SKELETON_MILESTONE_COUNT = 4

/** Skeleton frame mirroring the surface accordion-card. */
const ACCORDION_CARD_SKELETON = "flex flex-col rounded-3xl bg-surface shadow-surface"

/** A milestone's roll-up completion state, derived from its tasks. */
type MilestoneState = "done" | "inProgress" | "todo"

/**
 * Roll a milestone's tasks up into one state: `done` when every task passed,
 * `inProgress` when at least one task is passed or attempted, else `todo`.
 *
 * @param milestone - The milestone with its tasks.
 * @returns The milestone's completion state.
 */
const milestoneState = (milestone: MyCourseOutlineMilestone): MilestoneState => {
    if (milestone.tasks.length === 0) {
        return "todo"
    }
    if (milestone.tasks.every((task) => task.completed)) {
        return "done"
    }
    if (milestone.tasks.some((task) => task.completed || task.lastScore > 0)) {
        return "inProgress"
    }
    return "todo"
}

/** Status-chip tone per milestone state. */
const STATE_TONE: Record<MilestoneState, StatusChipTone> = {
    done: "success",
    inProgress: "warning",
    todo: "neutral",
}

/**
 * Filter milestones + their tasks by a search query (same rule as the module
 * filter). Empty query ΓåÆ unchanged.
 *
 * @param milestones - The course's milestones.
 * @param query - Lower-cased trimmed search query.
 * @returns The filtered milestones.
 */
const filterMilestones = (
    milestones: Array<MyCourseOutlineMilestone>,
    query: string,
): Array<MyCourseOutlineMilestone> => {
    if (!query) {
        return milestones
    }
    const result: Array<MyCourseOutlineMilestone> = []
    for (const milestone of milestones) {
        const matches = milestone.title.toLowerCase().includes(query)
        const tasks = matches
            ? milestone.tasks
            : milestone.tasks.filter((task) => task.title.toLowerCase().includes(query))
        if (matches || tasks.length > 0) {
            result.push({ ...milestone, tasks })
        }
    }
    return result
}

/**
 * The milestone to open by default ΓÇö the one holding the viewer's current task,
 * else the first not-yet-done milestone. Null when nothing is in flight.
 *
 * @param outline - The course outline payload.
 * @returns The milestone id to expand, or null.
 */
const resolveOpenMilestoneId = (outline: MyCourseOutlinePayload): string | null => {
    if (outline.currentTask?.milestoneId) {
        return outline.currentTask.milestoneId
    }
    const firstOpen = outline.milestones.find((milestone) => milestoneState(milestone) !== "done")
    return firstOpen?.id ?? null
}

/**
 * Course "Personal Project" tab: the capstone milestone ΓåÆ task tree of ONE
 * enrolled course as an accordion-card, each milestone showing a roll-up
 * completion status chip (done / in progress / not started) + a passed-count, and
 * each task showing its own pass state + latest score. Reads the same
 * `myCourseOutline` payload as the Contents tab ΓÇö no extra query. The milestone
 * holding the viewer's current task opens by default.
 *
 * @param props - {@link CourseMilestoneOutlineProps}
 */
export const CourseMilestoneOutline = ({
    search = ""}: CourseMilestoneOutlineProps) => {
    const t = useTranslations()
    const { selectedCourse } = useSelectedCourse()

    const rawCourseId = selectedCourse ? fromGlobalId(selectedCourse)?.id ?? null : null
    const outlineSwr = useQueryMyCourseOutlineSwr(rawCourseId)
    const outline = outlineSwr.data

    const query = search.trim().toLowerCase()
    const milestones = useMemo(
        () => (outline ? filterMilestones(outline.milestones, query) : []),
        [outline, query],
    )
    const defaultOpenId = useMemo(
        () => (outline && !query ? resolveOpenMilestoneId(outline) : null),
        [outline, query],
    )

    return (
        <AsyncContent
            isLoading={outlineSwr.data === null || outlineSwr.data === undefined ? !outlineSwr.error : false}
            skeleton={(
                <div className={cn(ACCORDION_CARD_SKELETON)}>
                    {Array.from({ length: SKELETON_MILESTONE_COUNT }).map((_unused, index) => (
                        <Box key={index} principle="row-pad" className="border-b border-default p-4 last:border-b-0"
                            explain="Row content inset ΓÇö not cell-pad, because this pads a horizontal content row rather than a dense table cell.">
                            <StackH gap={4} principle="content-row"
                                explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                justify="between" align="center" items={[
                                    () => <Skeleton.Typography type="body" width="1/2" />,
                                    () => <Skeleton className="h-5 w-20 rounded-full" />,
                                ]} />
                        </Box>
                    ))}
                </div>
            )}
            isEmpty={!outline || outline.milestones.length === 0}
            emptyContent={{ title: t("profileSettings.learning.outline.milestonesEmpty") }}
            error={!outlineSwr.data ? outlineSwr.error : undefined}
            errorContent={{
                title: t("profileSettings.learning.outline.error"),
                onRetry: () => { void outlineSwr.mutate() },
                retryLabel: t("profileSettings.learning.loadMore"),
            }}
        >
            {milestones.length === 0 ? (
                <AsyncContentEmpty title={t("profileSettings.learning.outline.noMatch")} />
            ) : (
                // NO `label`: the accordion IS the tab content (the tab already names it);
                // per-milestone status + progress ride in the header via `titleEnd`.
                <LabeledAccordionCard
                    defaultExpandedKeys={defaultOpenId ? new Set([defaultOpenId]) : undefined}
                    items={milestones.map((milestone) => {
                        const state = milestoneState(milestone)
                        const done = milestone.tasks.filter((task) => task.completed).length
                        const total = milestone.tasks.length
                        return {
                            id: milestone.id,
                            title: milestone.title,
                            titleEnd: () => (
                                <>
                                    <StatusChip tone={STATE_TONE[state]}>
                                        {t(`profileSettings.learning.outline.milestoneStatus.${state}`)}
                                    </StatusChip>
                                    <Typography type="body-xs" color="muted">
                                        {t("profileSettings.learning.outline.taskProgress", { done, total })}
                                    </Typography>
                                </>
                            ),
                            body: () => (
                                <StackV gap={3} principle="sibling-stack"
                                    explain="Same-kind peer stack ΓÇö not group-boundary, because these items are repeating siblings rather than section groups."
                                    items={milestone.tasks.map((task) => () => {
                                        const attempted = !task.completed && task.lastScore > 0
                                        return (
                                            <ListRow
                                                key={task.id}
                                                leading={task.completed ? (
                                                    <CheckCircleIcon aria-hidden focusable="false" className="size-5 text-success-soft-foreground" />
                                                ) : attempted ? (
                                                    <CircleHalfIcon aria-hidden focusable="false" className="size-5 text-warning-soft-foreground" />
                                                ) : (
                                                    <CircleIcon aria-hidden focusable="false" className="size-5 text-foreground" />
                                                )}
                                                title={task.completed ? (
                                                    <span className="text-success-soft-foreground">{task.title}</span>
                                                ) : attempted ? (
                                                    <span className="text-warning-soft-foreground">{task.title}</span>
                                                ) : (
                                                    task.title
                                                )}
                                                meta={(
                                                    <>
                                                        {task.type ? (
                                                            <Chip size="sm" variant="soft">
                                                                <Chip.Label>
                                                                    {t(`profileSettings.learning.outline.taskType.${task.type}`)}
                                                                </Chip.Label>
                                                            </Chip>
                                                        ) : null}
                                                        {task.completed || attempted ? (
                                                            <Typography type="body-xs" color="muted">
                                                                {`${task.lastScore}/${task.maxScore}`}
                                                            </Typography>
                                                        ) : null}
                                                    </>
                                                )}
                                            />
                                        )
                                    })} />
                            ),
                        }
                    })}
                />
            )}
        </AsyncContent>
    )
}

"use client"

import React, {
    useMemo,
} from "react"
import {
    Typography,
    cn,
} from "@heroui/react"
import {
    useTranslations,
} from "next-intl"
import {
    CheckCircleIcon,
    CircleIcon,
    LockIcon,
    PuzzlePieceIcon,
} from "@phosphor-icons/react"
import {
    useSelectedCourse,
} from "@/hooks/useSelectedCourse"
import {
    isAttempted,
    toStatusTone,
} from "@/modules/utils/learning-history-outline-map"
import { toDifficulty } from "@/modules/utils/difficulty"
import { useQueryMyCourseOutlineSwr } from "@/hooks/swr/api/graphql/queries/useQueryMyCourseOutlineSwr"
import { AsyncContent } from "@/components/blocks/async/AsyncContent"
import { AsyncContentEmpty } from "@/components/composites/async/AsyncContent"
import { DifficultyChip } from "@/components/blocks/chips/DifficultyChip"
import { ListRow } from "@/components/blocks/lists/ListRow"
import { LabeledAccordionCard } from "@/components/blocks/cards/LabeledAccordionCard"
import { Skeleton } from "@/components/blocks/skeleton/Skeleton"
import { StatusChip } from "@/components/blocks/chips/StatusChip"
import { fromGlobalId } from "@/modules/utils/globalId"
import type { MyCourseOutlineModule, MyCourseOutlinePayload } from "@/modules/api/graphql/queries/types/my-course-outline"
import { Box } from "@/components/frames/Box"
import { StackH, StackV } from "@/components/frames/Stack"

/** Props for {@link CourseOutline}. */
export interface CourseOutlineProps {
    /**
     * Lower-cased trimmed search query. Modules are kept when their title matches
     * or any of their lessons match; their lesson list is filtered to matches.
     */
    search?: string
}

/** Number of placeholder accordion modules shown while the outline loads. */
const SKELETON_MODULE_COUNT = 4

/** Skeleton frame that mirrors the surface accordion-card (bg-surface + rounded + border). */
const ACCORDION_CARD_SKELETON = "flex flex-col rounded-3xl bg-surface shadow-surface"

/**
 * Filter modules + their lessons by a search query. A module survives when its
 * own title matches OR it has at least one matching lesson; surviving modules keep
 * only their matching lessons (or all of them when the module title itself
 * matched). Empty query ΓåÆ unchanged.
 *
 * @param modules - The course's modules.
 * @param query - Lower-cased trimmed search query.
 * @returns The filtered modules.
 */
const filterModules = (
    modules: Array<MyCourseOutlineModule>,
    query: string,
): Array<MyCourseOutlineModule> => {
    if (!query) {
        return modules
    }
    const result: Array<MyCourseOutlineModule> = []
    for (const module of modules) {
        const moduleMatches = module.title.toLowerCase().includes(query)
        const lessons = moduleMatches
            ? module.lessons
            : module.lessons.filter((lesson) => lesson.title.toLowerCase().includes(query))
        if (moduleMatches || lessons.length > 0) {
            result.push({ ...module, lessons })
        }
    }
    return result
}

/**
 * The id of the module that should open by default ΓÇö the one holding the viewer's
 * next content task (next unread lesson / first uncompleted challenge), so the
 * accordion lands on "where you are". Null when there is no resume pointer.
 *
 * @param outline - The course outline payload.
 * @returns The module id to expand, or null.
 */
const resolveOpenModuleId = (outline: MyCourseOutlinePayload): string | null => {
    const pointer = outline.nextContentTask ?? outline.currentTask
    if (!pointer) {
        return null
    }
    for (const module of outline.modules) {
        const hit = module.lessons.some(
            (lesson) => lesson.id === pointer.id
                || lesson.challenges.some((challenge) => challenge.id === pointer.id),
        )
        if (hit) {
            return module.id
        }
    }
    return null
}

/**
 * Course "Contents" tab: the curriculum of ONE enrolled course as a
 * module ΓåÆ lesson ΓåÆ challenge accordion-card (read flags + challenge progress
 * overlaid), filtered by the shared `search`. The module containing the viewer's
 * next content task opens by default. Owns no header / back link / overall
 * progress ΓÇö its parent ({@link import("../CourseDetail").CourseDetail}) does.
 *
 * @param props - {@link CourseOutlineProps}
 */
export const CourseOutline = ({
    search = ""}: CourseOutlineProps) => {
    const t = useTranslations()
    const { selectedCourse } = useSelectedCourse()

    // decode the selected course globalId (CourseEntity:<id>) ΓåÆ raw id for the query
    const rawCourseId = selectedCourse ? fromGlobalId(selectedCourse)?.id ?? null : null
    const outlineSwr = useQueryMyCourseOutlineSwr(rawCourseId)
    const outline = outlineSwr.data

    const query = search.trim().toLowerCase()
    const modules = useMemo(
        () => (outline ? filterModules(outline.modules, query) : []),
        [outline, query],
    )
    // default-open the module holding the resume pointer (only when not searching)
    const defaultOpenId = useMemo(
        () => (outline && !query ? resolveOpenModuleId(outline) : null),
        [outline, query],
    )

    return (
        <AsyncContent
            isLoading={outlineSwr.data === null || outlineSwr.data === undefined ? !outlineSwr.error : false}
            skeleton={(
                <div className={cn(ACCORDION_CARD_SKELETON)}>
                    {Array.from({ length: SKELETON_MODULE_COUNT }).map((_unused, moduleIndex) => (
                        <Box key={moduleIndex} principle="row-pad" className="border-b border-default p-4 last:border-b-0"
                            explain="Row content inset ΓÇö not cell-pad, because this pads a horizontal content row rather than a dense table cell.">
                            <StackH gap={4} principle="content-row"
                                explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                justify="between" align="center" items={[
                                    () => <Skeleton.Typography type="body" width="1/2" />,
                                    () => <Skeleton className="h-4 w-16 rounded-medium" />,
                                ]} />
                        </Box>
                    ))}
                </div>
            )}
            isEmpty={!outline}
            emptyContent={{ title: t("profileSettings.learning.outline.empty") }}
            error={!outlineSwr.data ? outlineSwr.error : undefined}
            errorContent={{
                title: t("profileSettings.learning.outline.error"),
                onRetry: () => { void outlineSwr.mutate() },
                retryLabel: t("profileSettings.learning.loadMore"),
            }}
        >
            {modules.length === 0 ? (
                <AsyncContentEmpty title={t("profileSettings.learning.outline.noMatch")} />
            ) : (
                // NO `label`: the accordion IS the tab content; the premium lock +
                // read-count ride in the header via `titleEnd`.
                <LabeledAccordionCard
                    defaultExpandedKeys={defaultOpenId ? new Set([defaultOpenId]) : undefined}
                    items={modules.map((module) => {
                        const read = module.lessons.filter((lesson) => lesson.isRead).length
                        const total = module.lessons.length
                        const allRead = total > 0 && read === total
                        return {
                            id: module.id,
                            title: module.title,
                            titleEnd: () => (
                                <>
                                    {module.isPremium ? (
                                        <LockIcon
                                            aria-label={t("profileSettings.learning.outline.premium")}
                                            focusable="false"
                                            className="size-5 shrink-0 text-muted"
                                        />
                                    ) : null}
                                    <Typography
                                        type="body-xs"
                                        color={allRead ? undefined : "muted"}
                                        className={allRead ? "text-success-soft-foreground" : undefined}
                                    >
                                        {t("profileSettings.learning.outline.readCount", { read, total })}
                                    </Typography>
                                </>
                            ),
                            body: () => (
                                <StackV gap={3} principle="sibling-stack"
                                    explain="Same-kind peer stack ΓÇö not group-boundary, because these items are repeating siblings rather than section groups."
                                    items={module.lessons.map((lesson) => () => (
                                        <StackV key={lesson.id} gap={3} principle="sibling-stack"
                                            explain="Same-kind peer stack ΓÇö not group-boundary, because these items are repeating siblings rather than section groups."
                                            items={[
                                                () => (
                                                    <ListRow
                                                        title={lesson.title}
                                                        subtitle={t("content.minutesRead", { minutes: lesson.minutesRead })}
                                                        meta={(
                                                            <>
                                                                {lesson.difficulty ? (
                                                                    <DifficultyChip difficulty={toDifficulty(lesson.difficulty)} />
                                                                ) : null}
                                                                {lesson.isPremium ? (
                                                                    <LockIcon
                                                                        aria-label={t("profileSettings.learning.outline.premium")}
                                                                        focusable="false"
                                                                        className="size-5 text-muted"
                                                                    />
                                                                ) : null}
                                                                {lesson.isRead ? (
                                                                    <CheckCircleIcon
                                                                        aria-label={t("profileSettings.learning.outline.read")}
                                                                        focusable="false"
                                                                        className="size-5 text-success-soft-foreground"
                                                                    />
                                                                ) : (
                                                                    <CircleIcon
                                                                        aria-label={t("profileSettings.learning.outline.unread")}
                                                                        focusable="false"
                                                                        className="size-5 text-muted"
                                                                    />
                                                                )}
                                                            </>
                                                        )}
                                                    />
                                                ),
                                                () => (lesson.challenges.length > 0 ? (
                                                    <Box principle="cell-pad" className="pl-6"
                                                        explain="Tight cell inset ΓÇö not card-padding, because this sits inside a dense table or list cell rather than a card body.">
                                                        <StackV gap={3} principle="sibling-stack"
                                                            explain="Same-kind peer stack ΓÇö not group-boundary, because these items are repeating siblings rather than section groups."
                                                            items={lesson.challenges.map((challenge) => () => (
                                                                <ListRow
                                                                    key={challenge.id}
                                                                    leading={(
                                                                        <PuzzlePieceIcon aria-hidden focusable="false" className="size-5 text-foreground" />
                                                                    )}
                                                                    title={challenge.title}
                                                                    meta={(
                                                                        <>
                                                                            <DifficultyChip difficulty={toDifficulty(challenge.difficulty)} />
                                                                            <StatusChip tone={toStatusTone(challenge.status)}>
                                                                                {t(`profileSettings.learning.outline.status.${challenge.status}`)}
                                                                            </StatusChip>
                                                                            {isAttempted(challenge.status) ? (
                                                                                <Typography type="body-xs" color="muted">
                                                                                    {`${challenge.lastScore}/${challenge.maxScore}`}
                                                                                </Typography>
                                                                            ) : null}
                                                                        </>
                                                                    )}
                                                                />
                                                            ))} />
                                                    </Box>
                                                ) : null),
                                            ]} />
                                    ))} />
                            ),
                        }
                    })}
                />
            )}
        </AsyncContent>
    )
}

"use client"

import React, {
    useMemo,
    useState,
} from "react"
import { Input, TextField, Typography } from "@heroui/react"
import {
    useLocale,
