/** Props for {@link LearningHistoryPage}. */
export type LearningHistoryPageProps = Record<string, never>
/** Number of placeholder course cards shown while the hub loads. */
const SKELETON_COURSE_COUNT = 3

/** Hub-search appears only once the list has at least this many courses. */
const SEARCH_MIN_COURSES = 4

/** Segment colour per course progress dimension. */
const DIM_COLOR: Record<string, string> = {
    content: "var(--accent)",
    challenge: "var(--success)",
    milestone: "var(--warning)",
}

/**
 * Learning history (brainstorm direction A / H1). The HUB lists every joined
 * course as a hinh-2 card ΓÇö an {@link IconTile}, the title + overall completion %,
 * and a {@link SegmentBar} folding the three dimensions (content / challenge /
 * milestone) into one honest bar ΓÇö each a press target opening that course's
 * detail (written into `?course=`). A client search filters the cards by title,
 * shown only when there are several courses. When a course is selected, the
 * {@link CourseDetail} view (day timeline + chapter outline) replaces the grid.
 *
 * @param props - optional root className (placement only).
 */
export const LearningHistoryPage = () => {
    const t = useTranslations()
    const locale = useLocale()
    const router = useRouter()
    const { selectedCourse, setSelectedCourse } = useSelectedCourse()
    const [search, setSearch] = useState("")
    const coursesSwr = useQueryMyCoursesSwr()
    const courses = useMemo(() => coursesSwr.data ?? [], [coursesSwr.data])

    // search filters the loaded courses by title, client-side
    const query = search.trim().toLowerCase()
    const filtered = useMemo(
        () => (query
            ? courses.filter((course) => course.label.toLowerCase().includes(query))
            : courses),
        [courses, query],
    )

    // a selected course ΓåÆ show its detail (day timeline + chapter outline)
    if (selectedCourse) {
        return <CourseDetail />
    }

    return (
        <div className={"flex flex-col gap-10"}>
            <PageHeader
                breadcrumb={<SettingsBreadcrumb current={t("profileSettings.learning.history.title")} />}
                title={t("profileSettings.learning.history.title")}
                description={t("profileSettings.learning.history.subtitle")}
            />
            <StackV gap={6} principle="block-boundary"
                explain="Block-to-block spacing ΓÇö not group-boundary, because this separates major blocks rather than nested section groups."
                items={[
                // search ΓÇö only worth showing once there are several courses
                    () => (courses.length >= SEARCH_MIN_COURSES ? (
                        <TextField variant="secondary">
                            <Input
                                aria-label={t("profileSettings.learning.history.searchCourses")}
                                placeholder={t("profileSettings.learning.history.searchCourses")}
                                value={search}
                                onChange={(event) => setSearch(event.target.value)}
                            />
                        </TextField>
                    ) : null),

                    () => (
                        <AsyncContent
                            isLoading={!coursesSwr.data && !coursesSwr.error}
                            skeleton={(
                                <SurfaceListCard>
                                    {Array.from({ length: SKELETON_COURSE_COUNT }).map((_unused, row) => (
                                        <SurfaceListCardItem key={row}>
                                            <StackH gap={4} principle="content-row"
                                                explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                                align="center" items={[
                                                    () => <Skeleton className="size-12 shrink-0 rounded-xl" />,
                                                    () => (
                                                        <StackV gap={3} principle="sibling-stack"
                                                            explain="Same-kind peer stack ΓÇö not group-boundary, because these items are repeating siblings rather than section groups."
                                                            classNames={["min-w-0", "flex-1"]} items={[
                                                                () => (
                                                                    <StackH gap={3} principle="value-row"
                                                                        explain="Holds a label and its numeric value on one baseline so the count stays readable against the label."
                                                                        justify="between" align="center" items={[
                                                                            () => <Skeleton.Typography type="body-sm" width="1/2" />,
                                                                            () => <Skeleton className="h-3 w-8 rounded" />,
                                                                        ]} />
                                                                ),
                                                                () => <Skeleton.ProgressBar />,
                                                            ]} />
                                                    ),
                                                ]} />
                                        </SurfaceListCardItem>
                                    ))}
                                </SurfaceListCard>
                            )}
                            isEmpty={courses.length === 0}
                            emptyContent={{
                                title: t("profileSettings.learning.history.coursesEmpty"),
                                description: t("profileSettings.learning.history.coursesEmptyHint"),
                                onRetry: () => { router.push(pathConfig().locale(locale).course().build()) },
                                retryLabel: t("profileSettings.learning.history.explore"),
                            }}
                            error={!coursesSwr.data ? coursesSwr.error : undefined}
                            errorContent={{
                                title: t("profileSettings.learning.outline.error"),
                                onRetry: () => { void coursesSwr.mutate() },
                                retryLabel: t("profileSettings.learning.loadMore"),
                            }}
                        >
                            {filtered.length === 0 ? (
                            // loaded but the current search matches nothing
                                <AsyncContentEmpty title={t("profileSettings.learning.history.noMatch")} />
                            ) : (
                                <SurfaceListCard>
                                    {filtered.map((course) => {
                                        const dims = [
                                            { key: "content", completed: course.contentCompleted, total: course.contentTotal },
                                            { key: "challenge", completed: course.challengeCompleted, total: course.challengeTotal },
                                            { key: "milestone", completed: course.completed, total: course.total },
                                        ]
                                        const totalTasks = dims.reduce((acc, dim) => acc + dim.total, 0)
                                        return (
                                            <SurfaceListCardItem
                                                key={course.globalId}
                                                onPress={() => { setSelectedCourse(course.globalId) }}
                                                hover="underline"
                                            >
                                                <StackH gap={4} principle="content-row"
                                                    explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                                    align="center" items={[
                                                        () => <IconTile size="sm" src={course.thumbnailUrl} icon={<BookOpenIcon aria-hidden focusable="false" />} />,
                                                        () => (
                                                            <StackV gap={3} principle="sibling-stack"
                                                                explain="Same-kind peer stack ΓÇö not group-boundary, because these items are repeating siblings rather than section groups."
                                                                classNames={["min-w-0", "flex-1"]} items={[
                                                                    () => (
                                                                        <StackH gap={3} principle="value-row"
                                                                            explain="Holds a label and its numeric value on one baseline so the count stays readable against the label."
                                                                            justify="between" align="center" items={[
                                                                                () => (
                                                                                    <Typography type="body-sm" weight="semibold" truncate className="min-w-0 flex-1 underline-offset-4 decoration-[var(--separator-tertiary)] group-hover:underline">
                                                                                        {course.label}
                                                                                    </Typography>
                                                                                ),
                                                                                () => <CourseTrialChip isEnrolled={course.isEnrolled} />,
                                                                                () => (
                                                                                    <Typography type="body-xs" color="muted">
                                                                                        {`${course.completionPercent}%`}
                                                                                    </Typography>
                                                                                ),
                                                                            ]} />
                                                                    ),
                                                                    () => (
                                                                        <SegmentBar
                                                                            max={totalTasks || 1}
                                                                            ariaLabel={`${course.label} ┬╖ ${course.completionPercent}%`}
                                                                            segments={dims.map((dim) => ({
                                                                                key: dim.key,
                                                                                label: t(`dashboard.courseProgress.${dim.key}`),
                                                                                value: dim.completed,
                                                                                color: DIM_COLOR[dim.key],
                                                                            }))}
                                                                        />
                                                                    ),
                                                                ]} />
                                                        ),
                                                    ]} />
                                            </SurfaceListCardItem>
                                        )
                                    })}
                                </SurfaceListCard>
                            )}
                        </AsyncContent>
                    ),
                ]} />
        </div>
    )
}

"use client"

import React, { useEffect } from "react"
import { Button, Spinner, Typography } from "@heroui/react"
import { useRouter, useSearchParams } from "next/navigation"
import { useLocale, useTranslations } from "next-intl"
import { pathConfig } from "@/resources/path"

import { OauthAction } from "@/modules/types/enums/oauth-action"
import { OAUTH_ACTION_MESSAGE_KEY_MAP } from "@/modules/utils/oauth-action-message"
import { Spacer } from "@/components/blocks/layout/Spacer"
import { SessionStorage } from "@/modules/storage/session/storage"
import { SessionStorageId } from "@/modules/storage/session/enums/id"
import { type SessionStoragePostLoginRedirect } from "@/modules/storage/session/types/post-login-redirect"
import { StackV } from "@/components/frames/Stack"

export * from "@/modules/types/enums/oauth-action"

/** Props for {@link OauthRedirectPage}. */
export interface OauthRedirectPageProps {
    /**
     * The OAuth lifecycle step this redirect page represents ΓÇö selects the i18n
     * message shown under the spinner. The redirect destination (locale home)
     * and delay are identical for every step.
     */
    action: OauthAction
}

/**
 * OAuth redirect landing ΓÇö shown after a Keycloak provider hand-off
 * (login / logout / generic authenticate). Waits ~1s, then sends the user to
 * the locale home. Presentational shell + the redirect effect.
 *
 * `"use client"`: relies on `useRouter`, `useEffect` and `useLocale`.
 */
export const OauthRedirectPage = ({ action}: OauthRedirectPageProps) => {
    const router = useRouter()
    const locale = useLocale()
    const t = useTranslations()
    const searchParams = useSearchParams()

    // Keycloak (and the OAuth2 spec) hands back a failed/cancelled round-trip on the
    // redirect_uri as `?error=...` (e.g. `access_denied`), never establishing a session.
    // Detect it BEFORE redirecting so we don't drop the user home wearing success chrome.
    const hasOauthError = Boolean(searchParams.get("error"))

    // Hold the user briefly so the Keycloak session settles, then continue on: a sign-in
    // started from the `/login` guard stashed where the visitor was headed (query params
    // don't survive the IdP round-trip); anything else (logout, generic authenticate) goes home.
    // setTimeout (not `sleep().then()`) so the pending redirect is cancelled via cleanup if
    // this page unmounts within the delay ΓÇö `sleep()`'s promise can't be cancelled.
    useEffect(() => {
        // a failed/cancelled hand-off never authenticated the user ΓÇö render the failure
        // state instead of forwarding them on as if signed in.
        if (hasOauthError) {
            return
        }
        const handle = setTimeout(() => {
            let target: string | undefined
            if (action === OauthAction.Login) {
                const stashed = SessionStorage.getItem<SessionStoragePostLoginRedirect>(
                    SessionStorageId.PostLoginRedirect,
                )
                target = stashed?.target
                SessionStorage.removeItem(SessionStorageId.PostLoginRedirect)
            }
            router.push(target ?? pathConfig().locale(locale).build())
        }, 1000)

        return () => clearTimeout(handle)
    }, [action, locale, router, hasOauthError])

    if (hasOauthError) {
        const errorItems = [
            () => (
                <Typography type="h5" weight="semibold" align="center">
                    {t("auth.oauth.failedTitle")}
                </Typography>
            ),
            () => (
                <Typography type="body-sm" color="muted" align="center">
                    {t("auth.oauth.failedDescription")}
                </Typography>
            ),
            () => <Spacer y={3} />,
            () => (
                <Button
                    variant="primary"
                    onPress={() => router.replace(pathConfig().locale(locale).login().build())}
                >
                    {t("auth.oauth.retry")}
                </Button>
            ),
        ]
        return (
            <div className={"flex min-h-[60vh] flex-col items-center justify-center"}>
                <div className="max-w-sm text-center">
                    <StackV
                        gap={3}
                        align="center"
                        principle="sibling-stack"
                        explain="Same-kind peer stack ΓÇö not group-boundary, because these items are repeating siblings rather than section groups."
                        items={errorItems}
                    />
                </div>
            </div>
        )
    }

    const loadingItems = [
        () => (
            <Spinner
                color="accent"
                size="lg"
            />
        ),
        () => <Spacer y={3} />,
        () => (
            <div className="text-sm">
                {t(OAUTH_ACTION_MESSAGE_KEY_MAP[action])}
            </div>
        ),
    ]

    return (
        <div className={"flex min-h-[60vh] flex-col items-center justify-center"}>
            <StackV gap={3} align="center" principle="sibling-stack"
                explain="Same-kind peer stack ΓÇö not group-boundary, because these items are repeating siblings rather than section groups."
                items={loadingItems}  />
        </div>
    )
}

"use client"

