/** Props for {@link PracticeFilters}. */
export type PracticeFiltersProps = Record<string, never>
/**
 * The PracticeHubPage catalog filter bar ΓÇö a title search box plus difficulty / status
 * filter chips (HeroUI Buttons, secondary when active / ghost when not), a sort
 * `Select`, and a group-by-domain toggle. The topic (domain) filter lives in the
 * {@link import("../PracticeRail").PracticeRail} sidebar, not here. Reads + writes
 * the URL-backed filter state itself ({@link usePracticeFilters}); composes blocks
 * + HeroUI only.
 *
 * @param props - optional className for the root element.
 */
export const PracticeFilters = () => {
    const t = useTranslations()
    const { filters, setFilters } = usePracticeFilters()

    return (
        <div className={"flex flex-col gap-4"}>
            {/* title search ΓÇö client-side filter over loaded problems */}
            <SearchField
                aria-label={t("PracticeHubPage.filters.searchPlaceholder")}
                value={filters.q}
                onChange={(value) => setFilters({ q: value })}
            >
                <Label className="sr-only">{t("PracticeHubPage.filters.searchPlaceholder")}</Label>
                <SearchField.Group>
                    <SearchField.SearchIcon />
                    <SearchField.Input placeholder={t("PracticeHubPage.filters.searchPlaceholder")} />
                    <SearchField.ClearButton />
                </SearchField.Group>
            </SearchField>

            {/* difficulty + status chip groups */}
            <StackV gap={4} principle="card-caption"
                explain="Holds caption text under card media so the caption stays attached to the image above it."
                items={[
                    () => (
                        <FlexWrapButtonRadio
                            ariaLabel={t("PracticeHubPage.filters.difficultyAria")}
                            value={filters.difficulty}
                            onChange={(value) => setFilters({ difficulty: value as DifficultyFilter })}
                            items={DIFFICULTY_FILTERS.map((value) => ({
                                value,
                                content: value === "all"
                                    ? t("PracticeHubPage.filters.allDifficulties")
                                    : t(CODING_DIFFICULTY_META[value].labelKey),
                            }))}
                        />
                    ),
                    () => (
                        <FlexWrapButtonRadio
                            ariaLabel={t("PracticeHubPage.filters.statusAria")}
                            value={filters.status}
                            onChange={(value) => setFilters({ status: value as StatusFilter })}
                            items={STATUS_FILTERS.map((value) => ({
                                value,
                                content: t(`PracticeHubPage.filters.status.${value}`),
                            }))}
                        />
                    ),
                ]} />

            {/* sort dropdown + group toggle */}
            <StackH gap={4} principle="content-row"
                explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                items={[
                    () => (
                        <StackV gap={3} principle="sibling-stack"
                            explain="Same-kind peer stack ΓÇö not group-boundary, because these items are repeating siblings rather than section groups."
                            items={[
                                () => <Label className="sr-only">{t("PracticeHubPage.filters.sortAria")}</Label>,
                                () => (
                                    <Select.Root<{ id: string }, "single">
                                        aria-label={t("PracticeHubPage.filters.sortAria")}
                                        selectedKey={filters.sort}
                                        onSelectionChange={(key) => setFilters({ sort: String(key) as SortKey })}
                                    >
                                        <Select.Trigger aria-label={t("PracticeHubPage.filters.sortAria")} className="w-fit min-w-40">
                                            <Select.Value>
                                                {() => (
                                                    <Typography type="body-sm">
                                                        {t(`PracticeHubPage.filters.sort.${filters.sort}`)}
                                                    </Typography>
                                                )}
                                            </Select.Value>
                                            <Select.Indicator />
                                        </Select.Trigger>
                                        <Select.Popover>
                                            <ListBox.Root aria-label={t("PracticeHubPage.filters.sortAria")}>
                                                {SORT_KEYS.map((value) => (
                                                    <ListBox.Item
                                                        key={value}
                                                        id={value}
                                                        textValue={t(`PracticeHubPage.filters.sort.${value}`)}
                                                    >
                                                        {t(`PracticeHubPage.filters.sort.${value}`)}
                                                    </ListBox.Item>
                                                ))}
                                            </ListBox.Root>
                                        </Select.Popover>
                                    </Select.Root>
                                ),
                            ]} />
                    ),
                    () => (
                        <Button
                            size="sm"
                            variant={filters.group ? "secondary" : "ghost"}
                            aria-pressed={filters.group}
                            onPress={() => setFilters({ group: !filters.group })}
                        >
                            {filters.group ? (
                                <SquaresFourIcon aria-hidden focusable="false" className="size-5" />
                            ) : (
                                <RowsIcon aria-hidden focusable="false" className="size-5" />
                            )}
                            {filters.group
                                ? t("PracticeHubPage.filters.grouped")
                                : t("PracticeHubPage.filters.flat")}
                        </Button>
                    ),
                ]} />
        </div>
    )
}

"use client"

import React from "react"
import { Button, ScrollShadow } from "@heroui/react"
import {
    ListChecksIcon,
    TrophyIcon,
} from "@phosphor-icons/react"
import { useTranslations } from "next-intl"
import { CODING_DOMAIN_ORDER } from "@/modules/api/graphql/queries/types/coding"
import { TabsCard } from "@/components/blocks/navigation/TabsCard"
import { StackH } from "@/components/frames/Stack"
import { usePracticeView } from "@/hooks/usePracticeView"
import { usePracticeFilters } from "@/hooks/usePracticeFilters"
import type { PracticeView } from "@/hooks/usePracticeView"
import type { DomainFilter } from "@/modules/types/practice-hub"

/** Props for {@link PracticeMobileNav}. */
export type PracticeMobileNavProps = Record<string, never>
/** All topic options for the mobile chip row: "all" + the canonical domain order. */
const MOBILE_TOPICS: ReadonlyArray<DomainFilter> = ["all", ...CODING_DOMAIN_ORDER]

/**
 * Mobile counterpart of {@link import("..").PracticeRail}: the docs-style rail
 * hides below `lg`, so the mode switch + topic filter fold into scrollable chip
 * rows above the work pane (the master-detail mobile pattern). Reads/writes the
 * same URL state as the rail ({@link usePracticeView} + {@link usePracticeFilters}),
 * so the two stay in lockstep. Topics show only in Problems mode.
 *
 * @param props - {@link PracticeMobileNavProps}
 */
export const PracticeMobileNav = () => {
    const t = useTranslations()
    const { view, setView } = usePracticeView()
    const { filters, setFilters } = usePracticeFilters()

    return (
        <div className={"flex flex-col gap-3 @app-lg:hidden"}>
            {/* mode switch ΓÇö mirrors the desktop rail's TabsCard (see PracticeRail) */}
            <TabsCard
                variant="primary"
                leftTabs={{
                    selectedKey: view,
                    ariaLabel: t("PracticeHubPage.rail.modeAria"),
                    onSelectionChange: (key) => setView(String(key) as PracticeView),
                    items: [
                        {
                            key: "problems",
                            label: (
                                <StackH gap={3} principle="flex-action" as="span"
                                    explain="Groups action controls on one horizontal peer row so they share a single hit baseline."
                                    items={[
                                        () => <ListChecksIcon className="size-4 shrink-0" aria-hidden focusable="false" />,
                                        () => <>{t("PracticeHubPage.tabs.problems")}</>,
                                    ]} />
                            ),
                        },
                        {
                            key: "leaderboard",
                            label: (
                                <StackH gap={3} principle="flex-action" as="span"
                                    explain="Groups action controls on one horizontal peer row so they share a single hit baseline."
                                    items={[
                                        () => <TrophyIcon className="size-4 shrink-0" aria-hidden focusable="false" />,
                                        () => <>{t("PracticeHubPage.tabs.leaderboard")}</>,
                                    ]} />
                            ),
                        },
                    ],
                }}
            />

            {/* topic chips ΓÇö problems mode only */}
            {view === "problems" ? (
                <ScrollShadow
                    orientation="horizontal"
                    hideScrollBar
                    className="overflow-x-auto"
                >
                    <StackH
                        gap={3}
                        principle="chip-row"
                        explain="Lets chips share one wrapping row so related tags stay together without stacking as a column."
                        items={MOBILE_TOPICS.map((domain) => (
                            () => (
                                <Button
                                    size="sm"
                                    variant={filters.domain === domain ? "secondary" : "ghost"}
                                    aria-pressed={filters.domain === domain}
                                    className="shrink-0"
                                    onPress={() => setFilters({ domain })}
                                >
                                    {domain === "all"
                                        ? t("PracticeHubPage.filters.allDomains")
                                        : t(`codingPractice.domain.${domain}`)}
                                </Button>
                            )
                        ))}
                    />
                </ScrollShadow>
            ) : null}
        </div>
    )
}

"use client"

import React, {
    useMemo,
    useState,
} from "react"
import {
    Input,
    Label,
    ListBox,
    ScrollShadow,
    TextField,
    Typography,
} from "@heroui/react"
import {
    ListChecksIcon,
    TrophyIcon,
} from "@phosphor-icons/react"
import { useTranslations } from "next-intl"
import { CODING_DOMAIN_ORDER } from "@/modules/api/graphql/queries/types/coding"
import { TabsCard } from "@/components/blocks/navigation/TabsCard"
import { Box } from "@/components/frames/Box"
import { StackH, StackV } from "@/components/frames/Stack"
import { usePracticeView } from "@/hooks/usePracticeView"
import { usePracticeFilters } from "@/hooks/usePracticeFilters"
import type { PracticeView } from "@/hooks/usePracticeView"
import type { DomainFilter } from "@/modules/types/practice-hub"

/**
 * The PracticeHubPage LEFT RAIL ΓÇö the same docs-style sidebar as the flashcards /
 * content-map rail (a pinned header over a scroll region, full rail height). A
 * mode switch (Problems / Leaderboard) above the course-domain topics as a
 * searchable nav list. The mode drives the URL view ({@link usePracticeView}); the
 * chosen topic drives the catalog domain filter ({@link usePracticeFilters}), so
 * the rail and the work pane share one source of truth. Topics show only in
 * Problems mode (the leaderboard is topic-agnostic). Placed in the rail column by
 * the page shell; reads/writes URL state directly (no data props).
 */
export const PracticeRail = () => {
    const t = useTranslations()
    const { view, setView } = usePracticeView()
    const { filters, setFilters } = usePracticeFilters()
    const [query, setQuery] = useState("")

    /** Resolve a topic's display label ("All topics" or a domain name). */
    const topicLabel = (domain: DomainFilter): string =>
        domain === "all"
            ? t("PracticeHubPage.filters.allDomains")
            : t(`codingPractice.domain.${domain}`)

    // the topic rows: "all" + the canonical domain order, narrowed by the search box
    const topics = useMemo<Array<DomainFilter>>(() => {
        const all: Array<DomainFilter> = ["all", ...CODING_DOMAIN_ORDER]
        const normalized = query.trim().toLowerCase()
        if (!normalized) {
            return all
        }
        return all.filter((domain) => topicLabel(domain).toLowerCase().includes(normalized))
    }, [query, t])

    return (
        <div className="relative flex min-h-0 min-w-0 flex-col gap-3 p-6">
            {/* pinned header: mode switch + topic search */}
            <StackV gap={4} principle="card-caption"
                explain="Holds caption text under card media so the caption stays attached to the image above it."
                items={[
                    () => (
                        <TabsCard
                            variant="primary"
                            leftTabs={{
                                selectedKey: view,
                                ariaLabel: t("PracticeHubPage.rail.modeAria"),
                                onSelectionChange: (key) => setView(String(key) as PracticeView),
                                items: [
                                    {
                                        key: "problems",
                                        label: (
                                            <StackH gap={3} principle="flex-action" as="span"
                                                explain="Groups action controls on one horizontal peer row so they share a single hit baseline."
                                                items={[
                                                    () => <ListChecksIcon className="size-4 shrink-0" aria-hidden focusable="false" />,
                                                    () => <>{t("PracticeHubPage.tabs.problems")}</>,
                                                ]} />
                                        ),
                                    },
                                    {
                                        key: "leaderboard",
                                        label: (
                                            <StackH gap={3} principle="flex-action" as="span"
                                                explain="Groups action controls on one horizontal peer row so they share a single hit baseline."
                                                items={[
                                                    () => <TrophyIcon className="size-4 shrink-0" aria-hidden focusable="false" />,
                                                    () => <>{t("PracticeHubPage.tabs.leaderboard")}</>,
                                                ]} />
                                        ),
                                    },
                                ],
                            }}
                        />
                    ),
                    () => view === "problems" ? (
                        <StackV gap={3} principle="sibling-stack"
                            explain="Same-kind peer stack ΓÇö not group-boundary, because these items are repeating siblings rather than section groups."
                            items={[
                                () => <Label className="px-1 text-xs text-muted" data-principle="control-pad">{t("PracticeHubPage.rail.topicsLabel")}</Label>,
                                () => (
                                    <TextField>
                                        <Input
                                            type="search"
                                            aria-label={t("PracticeHubPage.rail.searchTopic")}
                                            placeholder={t("PracticeHubPage.rail.searchTopic")}
                                            value={query}
                                            onChange={(event) => setQuery(event.target.value)}
                                        />
                                    </TextField>
                                ),
                            ]} />
                    ) : null,
                ]} />

            {/* scroll region: the topic nav list (problems mode only) */}
            {view === "problems" ? (
                <ScrollShadow
                    hideScrollBar
                    className="-mx-1 min-h-0 min-w-0 flex-1 overflow-y-auto px-1" data-principle="control-pad"
                >
                    {topics.length === 0 ? (
                        <Box principle="control-pad" className="px-3 py-2"
                            explain="Control hit-area inset ΓÇö not row-pad, because this pads a single interactive control rather than a full content row.">
                            <Typography type="body-sm" color="muted">
                                {t("PracticeHubPage.rail.searchTopicEmpty", { query: query.trim() })}
                            </Typography>
                        </Box>
                    ) : (
                        <ListBox
                            aria-label={t("PracticeHubPage.rail.topicsAria")}
                            selectionMode="single"
                            disallowEmptySelection
                            selectedKeys={[filters.domain]}
                            onSelectionChange={(keys) => {
                                // controlled single-select ΓåÆ filter the catalog by the chosen topic
                                const key = [...keys][0]
                                if (typeof key === "string") {
                                    setFilters({ domain: key as DomainFilter })
                                }
                            }}
                            className="gap-1 p-0" data-principle="title-subtitle"
                        >
                            {topics.map((domain) => (
                                <ListBox.Item
                                    key={domain}
                                    id={domain}
                                    textValue={topicLabel(domain)}
                                    className="cursor-pointer rounded-2xl px-3 py-2 text-foreground data-[hovered=true]:bg-default-100 data-[selected=true]:bg-accent-soft data-[selected=true]:text-accent-soft-foreground" data-principle="control-pad"
                                >
                                    <Typography type="body-sm" className="min-w-0 flex-1 truncate text-inherit">
                                        {topicLabel(domain)}
                                    </Typography>
                                </ListBox.Item>
                            ))}
                        </ListBox>
                    )}
                </ScrollShadow>
            ) : null}
        </div>
    )
}

"use client"

import React from "react"
import {
    Typography,
    cn,
} from "@heroui/react"
import { useTranslations } from "next-intl"
import {
    CheckCircleIcon,
    CircleHalfIcon,
    CircleIcon,
} from "@phosphor-icons/react"
import { CODING_DIFFICULTY_META } from "@/modules/utils/practice-hub"
import type { ProblemStatus } from "@/modules/types/practice-hub"
import { StatusChip } from "@/components/blocks/chips/StatusChip"
import { SurfaceListCardItem } from "@/components/blocks/cards/SurfaceListCard"
import type { CodingProblem } from "@/modules/api/graphql/queries/types/coding"
import { StackH, StackV } from "@/components/frames/Stack"
import { Box } from "@/components/frames/Box"

/** Props for {@link ProblemRow}. A list-item, so it accepts its data as props. */
export interface ProblemRowProps {
    /** The problem to render. */
    problem: CodingProblem
    /** The viewer's solve status for this problem (drives the status icon). */
    status: ProblemStatus
}

/** Status icon + colour + aria-label key per {@link ProblemStatus}. */
const STATUS_META: Record<
    ProblemStatus,
    { Icon: typeof CircleIcon; className: string; labelKey: string }
> = {
    solved: {
        Icon: CheckCircleIcon,
        className: "text-success-soft-foreground",
        labelKey: "PracticeHubPage.row.status.solved",
    },
    attempted: {
        Icon: CircleHalfIcon,
        className: "text-warning-soft-foreground",
        labelKey: "PracticeHubPage.row.status.attempted",
    },
    unsolved: {
        Icon: CircleIcon,
        className: "text-muted",
        labelKey: "PracticeHubPage.row.status.unsolved",
    },
}

/**
 * One catalog row: a prominent status icon (Γ£ô solved / ΓùÉ attempted / Γùï unsolved),
 * the problem title (underlines on hover) navigating into the solve page, a
 * difficulty {@link StatusChip}, a domain chip, and the point value ΓÇö with topic
 * tags shown secondary below. Renders as a {@link SurfaceListCardItem} (the WHOLE
 * row is the single nav link ΓÇö `hover="underline"` per the go-there row style) so
 * it joins its siblings inside the parent {@link SurfaceListCard}, not a
 * hand-rolled bordered div. Styling lives in the blocks, this only places them.
 *
 * @param props - {@link ProblemRowProps}.
 */
export const ProblemRow = ({
    problem,
    status}: ProblemRowProps) => {
    const t = useTranslations()
    const statusMeta = STATUS_META[status]
    const StatusIcon = statusMeta.Icon
    const difficultyMeta = CODING_DIFFICULTY_META[problem.difficulty]

    return (
        <SurfaceListCardItem
            href={`/PracticeHubPage/${problem.slug}`}
            hover="underline"
        >
            <StackH gap={4} align="center" principle="content-row" classNames={["min-w-0"]}
                explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                items={[
                    () => (
                        <StatusIcon
                            weight={status === "unsolved" ? "regular" : "fill"}
                            aria-label={t(statusMeta.labelKey)}
                            className={cn("size-5 shrink-0", statusMeta.className)}
                        />
                    ),
                    () => (
                        <StackV gap={3} principle="sibling-stack" classNames={["min-w-0", "flex-1"]}
                            explain="Same-kind peer stack ΓÇö not group-boundary, because these items are repeating siblings rather than section groups."
                            items={[
                                () => (
                                    <Typography
                                        type="body-sm"
                                        weight="medium"
                                        truncate
                                        className="w-fit underline-offset-4 decoration-[var(--separator-tertiary)] group-hover:underline"
                                    >
                                        {problem.title}
                                    </Typography>
                                ),
                                ...(problem.tags.length > 0 ? [
                                    () => (
                                        <Box principle="chip-row" className="flex flex-wrap items-center gap-2"
                                            explain="Lets chips share one wrapping row so related tags stay together without stacking as a column.">
                                            {problem.tags.slice(0, 4).map((tag) => (
                                                <Typography key={tag} type="body-xs" color="muted">
                                                    {tag}
                                                </Typography>
                                            ))}
                                            {problem.tags.length > 4 ? (
                                                <Typography
                                                    type="body-xs"
                                                    color="muted"
                                                    title={problem.tags.slice(4).join(", ")}
                                                >
                                                    {t("PracticeHubPage.row.moreTags", {
                                                        count: problem.tags.length - 4,
                                                    })}
                                                </Typography>
                                            ) : null}
                                        </Box>
                                    ),
                                ] : []),
                            ]} />
                    ),
                    () => (
                        <Box principle="push-end" className="ml-auto flex shrink-0 items-center gap-2"
                            explain="Pushes this peer to the trailing edge so trailing meta stays right-aligned in the row.">
                            <StatusChip tone={difficultyMeta.tone}>
                                {t(difficultyMeta.labelKey)}
                            </StatusChip>
                            <StatusChip tone="neutral">
                                {t(`codingPractice.domain.${problem.domain}`)}
                            </StatusChip>
                            <Typography type="body-xs" color="muted">
                                {t("codingPractice.points", { points: problem.points })}
                            </Typography>
                        </Box>
                    ),
                ]} />
        </SurfaceListCardItem>
    )
}

"use client"

import React, {
    useMemo,
} from "react"
import { Chip, Typography } from "@heroui/react"
import { useTranslations } from "next-intl"
import { usePracticeFilters } from "@/hooks/usePracticeFilters"
import { useCodingProblemsSwr } from "@/hooks/useCodingProblemsSwr"
import { useMyCodingProgressSwr } from "@/hooks/useMyCodingProgressSwr"
import {
    deriveStatus,
    filterProblems,
    sortProblems,
} from "@/modules/utils/practice-hub"
import { ProblemRow } from "./ProblemRow"
import { AsyncContent } from "@/components/blocks/async/AsyncContent"
import { Skeleton } from "@/components/blocks/skeleton/Skeleton"
import { SurfaceListCard, SurfaceListCardItem } from "@/components/blocks/cards/SurfaceListCard"
import { CODING_DOMAIN_ORDER, type CodingDomain, type CodingProblem } from "@/modules/api/graphql/queries/types/coding"
import { StackH, StackV } from "@/components/frames/Stack"
import { Box } from "@/components/frames/Box"

/** Props for {@link ProblemCatalog}. */
export type ProblemCatalogProps = Record<string, never>
/** One rendered domain section: the domain plus its (already sorted) problems. */
interface CatalogGroup {
    /** The domain this section groups. */
    domain: CodingDomain
    /** Problems under the domain, in the active sort order. */
    problems: Array<CodingProblem>
}

/**
 * The PracticeHubPage problem list. Loads the whole catalog + the viewer's progress,
 * overlays per-problem status, applies the URL-backed client filters / search /
 * sort, then renders either domain-grouped sections (LeetCode topic style) or a
 * flat sorted list per the group toggle. Every fetch goes through
 * {@link AsyncContent} (loading skeleton, filter-aware empty, retry on error).
 * Composes blocks + the {@link ProblemRow} list-item.
 *
 * @param props - optional className for the root element.
 */
export const ProblemCatalog = () => {
    const t = useTranslations()
    const { filters, isFiltered, clearFilters } = usePracticeFilters()

    const {
        data: problems,
        isLoading,
        error,
        mutate,
    } = useCodingProblemsSwr()
    // progress overlay ΓÇö drives row status + the status filter (anonymous ΓåÆ null)
    const { data: progress } = useMyCodingProgressSwr()

    // apply client filters then sort the survivors
    const filtered = useMemo(
        () => sortProblems(filterProblems(problems ?? [], progress, filters), filters.sort),
        [problems, progress, filters],
    )

    // group the filtered+sorted problems by domain, in canonical domain order
    const groups = useMemo<Array<CatalogGroup>>(() => {
        const byDomain = new Map<CodingDomain, Array<CodingProblem>>()
        filtered.forEach((problem) => {
            const bucket = byDomain.get(problem.domain) ?? []
            bucket.push(problem)
            byDomain.set(problem.domain, bucket)
        })
        return CODING_DOMAIN_ORDER
            .filter((domain) => byDomain.has(domain))
            .map((domain) => ({ domain, problems: byDomain.get(domain) ?? [] }))
    }, [filtered])

    return (
        <AsyncContent
            isLoading={isLoading && !problems}
            // intentionally flat regardless of `filters.group` ΓÇö real layout can be
            // N domain-header sections when grouped, but we keep the skeleton a
            // simple 5-row approximation rather than pre-guessing group shape
            skeleton={(
                <SurfaceListCard>
                    {[0, 1, 2, 3, 4].map((row) => (
                        <SurfaceListCardItem key={row}>
                            <StackH gap={4} align="center" principle="content-row" classNames={["min-w-0"]}
                                explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                items={[
                                    () => <Skeleton className="size-5 shrink-0 rounded-full" />,
                                    () => (
                                        <StackV gap={3} principle="sibling-stack" classNames={["min-w-0", "flex-1"]}
                                            explain="Same-kind peer stack ΓÇö not group-boundary, because these items are repeating siblings rather than section groups."
                                            items={[
                                                () => <Skeleton.Typography type="body-sm" width="1/2" />,
                                                () => (
                                                    <Box principle="chip-row" className="flex flex-wrap items-center gap-2"
                                                        explain="Lets chips share one wrapping row so related tags stay together without stacking as a column.">
                                                        <Skeleton.Typography type="body-xs" width="1/4" />
                                                        <Skeleton.Typography type="body-xs" width="1/4" />
                                                    </Box>
                                                ),
                                            ]} />
                                    ),
                                    () => (
                                        <Box principle="push-end" className="ml-auto flex shrink-0 items-center gap-2"
                                            explain="Pushes this peer to the trailing edge so trailing meta stays right-aligned in the row.">
                                            <Skeleton.Chip />
                                            <Skeleton.Chip />
                                            <Skeleton.Typography type="body-xs" width="1/4" className="w-10" />
                                        </Box>
                                    ),
                                ]} />
                        </SurfaceListCardItem>
                    ))}
                </SurfaceListCard>
            )}
            isEmpty={filtered.length === 0}
            emptyContent={isFiltered
                ? {
                    title: t("PracticeHubPage.catalog.noMatch"),
                    onRetry: clearFilters,
                    retryLabel: t("PracticeHubPage.catalog.clearFilters"),
                }
                : { title: t("codingPractice.empty"), description: t("codingPractice.emptyHint") }}
            error={error}
            errorContent={{
                title: t("PracticeHubPage.catalog.loadError"),
                onRetry: () => { void mutate() },
                retryLabel: t("PracticeHubPage.retry"),
            }}
        >
            {filters.group ? (
                <div className={"flex flex-col gap-6"}>
                    {groups.map((group) => (
                        <StackV key={group.domain} gap={3} principle="sibling-stack" as="section"
                            explain="Same-kind peer stack ΓÇö not group-boundary, because these items are repeating siblings rather than section groups."
                            items={[
                                () => (
                                    <StackH gap={3} principle="flex-action"
                                        explain="Groups action controls on one horizontal peer row so they share a single hit baseline."
                                        items={[
                                            () => (
                                                <Typography type="h5" weight="semibold">
                                                    {t(`codingPractice.domain.${group.domain}`)}
                                                </Typography>
                                            ),
                                            () => (
                                                <Chip size="sm" variant="soft" color="default">
                                                    <Chip.Label>{group.problems.length}</Chip.Label>
                                                </Chip>
                                            ),
                                        ]} />
                                ),
                                () => (
                                    <SurfaceListCard>
                                        {group.problems.map((problem) => (
                                            <ProblemRow
                                                key={problem.id}
                                                problem={problem}
                                                status={deriveStatus(problem.id, progress)}
                                            />
                                        ))}
                                    </SurfaceListCard>
                                ),
                            ]} />
                    ))}
                </div>
            ) : (
                <SurfaceListCard>
                    {filtered.map((problem) => (
                        <ProblemRow
                            key={problem.id}
                            problem={problem}
                            status={deriveStatus(problem.id, progress)}
                        />
                    ))}
                </SurfaceListCard>
            )}
        </AsyncContent>
    )
}

"use client"

import React from "react"
import { Label } from "@heroui/react"
import { useTranslations } from "next-intl"
import { CODING_DIFFICULTY_META } from "@/modules/utils/practice-hub"
import { useQueryUserCodingProgressSwr } from "@/hooks/swr/api/graphql/queries/useQueryUserCodingProgressSwr"
import { useQueryUserCodingRankSwr } from "@/hooks/swr/api/graphql/queries/useQueryUserCodingRankSwr"
import { useQueryUserCodingSkillsSwr } from "@/hooks/swr/api/graphql/queries/useQueryUserCodingSkillsSwr"
import { AsyncContent } from "@/components/blocks/async/AsyncContent"
import { MetricCard } from "@/components/composites/stats/MetricCard"
import { SegmentBar } from "@/components/composites/stats/SegmentBar"
import { Skeleton } from "@/components/blocks/skeleton/Skeleton"
import { useAppSelector } from "@/redux/hooks"
import { CodingDifficulty } from "@/modules/api/graphql/queries/types/coding"
import { Box } from "@/components/frames/Box"
import { StackV } from "@/components/frames/Stack"

/** Props for {@link ProgressCockpit}. */
export type ProgressCockpitProps = Record<string, never>
/** Difficulty order for the distribution SegmentBar (easy ΓåÆ hard). */
const COCKPIT_DIFFICULTY: ReadonlyArray<CodingDifficulty> = [
    CodingDifficulty.Easy,
    CodingDifficulty.Medium,
    CodingDifficulty.Hard,
]

/**
 * The PracticeHubPage cockpit ΓÇö the signed-in user's coding standing at a glance, built
 * from the SAME blocks as the profile Coding tab: a {@link MetricCard} row
 * (solved ┬╖ points ┬╖ rank ┬╖ percentile, the last two hidden when unranked) over a
 * difficulty {@link SegmentBar} (easy/medium/hard solved counts, coding 3-tone
 * scale). Self-contained: reads the signed-in user id from the store and drives
 * its own SWR. Hides entirely for anonymous viewers (no user id ΓåÆ empty cockpit).
 *
 * @param props - optional className for the root element.
 */
export const ProgressCockpit = () => {
    const t = useTranslations()
    // signed-in user id ΓÇö the rank/skills queries key off it (null when anonymous)
    const userId = useAppSelector((state) => state.user.user?.id) ?? null

    const {
        data: progress,
        isLoading,
        error,
        mutate,
    } = useQueryUserCodingProgressSwr(userId)
    const skillsSwr = useQueryUserCodingSkillsSwr(userId)
    const standingSwr = useQueryUserCodingRankSwr(userId)
    const skills = skillsSwr.data
    const standing = standingSwr.data

    const solved = progress?.solvedProblemIds.length ?? 0
    // `totalPoints` is the user's whole spendable Coin balance, NOT a coding-only
    // figure ΓÇö the `coding` leaderboard ranks on distinct problems solved instead
    // (points are a different currency). Labelled "Coin" via `metric.points`.
    const totalPoints = progress?.totalPoints ?? 0

    // 2026-07-12: `skills`/`standing` fire alongside `progress` but the outer
    // skeleton only watches `progress` ΓÇö while they're still in flight, rank/
    // percentile stat cards and the whole difficulty bar used to be silently
    // absent, then pop in a beat after the "solved"/"points" cards had already
    // rendered. Gate each dependent section on its OWN pending state instead of
    // just omitting it.
    const standingPending = standingSwr.isLoading && !standing

    // headline metric row; rank + percentile hide when the user is unranked
    const stats: Array<{ key: string; value: string | null }> = [
        { key: "solved", value: String(solved) },
        { key: "points", value: String(totalPoints) },
    ]
    if (standingPending) {
        stats.push({ key: "rank", value: null }, { key: "percentile", value: null })
    } else {
        if (standing?.rank != null) {
            stats.push({ key: "rank", value: `#${standing.rank}` })
        }
        if (standing?.percentile != null) {
            stats.push({ key: "percentile", value: `${standing.percentile}%` })
        }
    }

    // difficulty distribution (easyΓåÆhard), coloured by the coding 3-tone scale
    const skillsPending = skillsSwr.isLoading && !skills
    const solvedByDifficulty = new Map((skills?.byDifficulty ?? []).map((item) => [item.key, item.solved]))
    const difficultySegments = COCKPIT_DIFFICULTY
        .filter((difficulty) => (solvedByDifficulty.get(difficulty) ?? 0) > 0)
        .map((difficulty) => ({
            key: difficulty,
            label: t(CODING_DIFFICULTY_META[difficulty].labelKey),
            value: solvedByDifficulty.get(difficulty) ?? 0,
            color: CODING_DIFFICULTY_META[difficulty].color,
        }))

    // anonymous viewers never fire the queries (key disabled) ΓÇö bail out
    // instead of `isLoading`/`!userId` feeding `isFirstLoad` forever.
    if (!userId) return null

    // first load in flight only when no progress has resolved yet
    const isFirstLoad = !progress && isLoading

    return (
        <AsyncContent
            isLoading={isFirstLoad}
            skeleton={(
                <div className={"flex flex-col gap-6"}>
                    {/* metric row ΓÇö solved ┬╖ points ┬╖ rank ┬╖ percentile */}
                    <Box principle="content-row" className="grid grid-cols-2 gap-3 @app-sm:grid-cols-4"
                        explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title.">
                        {[0, 1, 2, 3].map((index) => (
                            <Skeleton key={index} className="h-24 w-full rounded-2xl" />
                        ))}
                    </Box>
                    {/* difficulty distribution bar */}
                    <StackV gap={3} principle="sibling-stack"
                        explain="Same-kind peer stack ΓÇö not group-boundary, because these items are repeating siblings rather than section groups."
                        items={[
                            () => <Skeleton.Typography type="body-sm" width="1/4" />,
                            () => <Skeleton.SegmentBar legendItems={3} />,
                        ]} />
                </div>
            )}
            error={error}
            errorContent={{
                title: t("PracticeHubPage.cockpit.loadError"),
                onRetry: () => { void mutate() },
                retryLabel: t("PracticeHubPage.retry"),
            }}
        >
            <div className={"flex flex-col gap-6"}>
                {/* headline metric row ΓÇö pending rank/percentile cards skeleton in place */}
                <Box principle="content-row" className="grid grid-cols-2 gap-3 @app-sm:grid-cols-4"
                    explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title.">
                    {stats.map((stat) => (
                        stat.value === null ? (
                            <Skeleton key={stat.key} className="h-24 w-full rounded-2xl" />
                        ) : (
                            <MetricCard
                                key={stat.key}
                                value={stat.value}
                                label={t(`PracticeHubPage.cockpit.metric.${stat.key}`)}
                            />
                        )
                    ))}
                </Box>

                {/* difficulty distribution ΓÇö skeleton while resolving, hidden once
                    resolved with nothing solved yet, real bar otherwise */}
                {skillsPending ? (
                    <StackV gap={3} principle="sibling-stack"
                        explain="Same-kind peer stack ΓÇö not group-boundary, because these items are repeating siblings rather than section groups."
                        items={[
                            () => <Skeleton.Typography type="body-sm" width="1/4" />,
                            () => <Skeleton.SegmentBar legendItems={3} />,
                        ]} />
                ) : difficultySegments.length > 0 ? (
                    <StackV gap={3} principle="sibling-stack"
                        explain="Same-kind peer stack ΓÇö not group-boundary, because these items are repeating siblings rather than section groups."
                        items={[
                            () => <Label>{t("PracticeHubPage.cockpit.byDifficulty")}</Label>,
                            () => (
                                <SegmentBar
                                    ariaLabel={t("PracticeHubPage.cockpit.byDifficulty")}
                                    segments={difficultySegments}
                                />
                            ),
                        ]} />
                ) : null}
            </div>
        </AsyncContent>
    )
}

"use client"

import React from "react"
import { useTranslations } from "next-intl"
import { useRouter } from "next/navigation"
import { PageHeader } from "@/components/blocks/layout/PageHeader"
import { ResizableRail } from "@/components/blocks/layout/ResizableRail"
import { ResponsiveBreadcrumb } from "@/components/blocks/navigation/ResponsiveBreadcrumb"
import { pathConfig } from "@/resources/path"
import { Box } from "@/components/frames/Box"
import { StackV } from "@/components/frames/Stack"
import { FillAvailable } from "@/components/frames/FillAvailable"
import { PracticeRail } from "./PracticeRail"
import { PracticeMobileNav } from "./PracticeRail/PracticeMobileNav"
import { ProgressCockpit } from "./ProgressCockpit"
import { PracticeFilters } from "./PracticeFilters"
import { ProblemCatalog } from "./ProblemCatalog"
import { CodingLeaderboard } from "./CodingLeaderboard"
import { usePracticeView } from "@/hooks/usePracticeView"

/**
 * `/PracticeHubPage` ΓÇö the LeetCode-style coding-PracticeHubPage page, laid out docs-style: a
 * persistent left {@link PracticeRail} (the mode switch Problems Γçä Leaderboard +
 * the course-domain topics as a nav list) beside a padded work pane. The rail and
 * the pane share one source of truth through the URL (the {@link usePracticeView}
 * mode + the {@link PracticeFilters} topic), so navigation is shareable. Below
 * `lg` the rail folds into the in-pane {@link PracticeMobileNav} chip rows.
 *
 * The pane stacks: a {@link PageHeader}, the {@link ProgressCockpit} (the viewer's
 * solve standing, shown for BOTH views), then the active view ΓÇö **Problems** (the
 * {@link PracticeFilters} bar + {@link ProblemCatalog}) or the global
 * **Leaderboard** ({@link CodingLeaderboard}). Pure composition ΓÇö each child reads
 * its own SWR / URL state; this root only places them and owns the shell.
 */
export const PracticeHubPage = () => {
    const t = useTranslations()
    const router = useRouter()
    const { view } = usePracticeView()

    return (
        // single column on mobile/tablet; rail + content side-by-side from lg up
        <div className="flex w-full flex-col items-start @app-lg:flex-row">
            {/* docs-style left rail ΓÇö sticks under the navbar, viewport-tall, drag-resizable */}
            <ResizableRail
                className="hidden shrink-0 @app-lg:sticky @app-lg:top-16 @app-lg:flex @app-lg:h-[calc(100dvh-4rem)] @app-lg:flex-col @app-lg:self-start"
                storageKey="starci.PracticeHubPage.rail.width"
                defaultWidth={300}
                minWidth={256}
                maxWidth={420}
                ariaLabel={t("PracticeHubPage.rail.modeAria")}
            >
                <FillAvailable at="lg" body={() => <PracticeRail />} />
            </ResizableRail>

            {/* content column ΓÇö owns the canonical p-6 reading padding */}
            <Box principle="page-pad" className="min-h-0 min-w-0 flex-1 p-6"
                explain="Page chrome inset ΓÇö not card-padding, because this pads the whole page rather than a nested card surface.">
                <Box principle="center-measure" className="mx-auto flex max-w-5xl flex-col gap-10"
                    explain="Caps reading width so long copy does not stretch edge-to-edge across the viewport.">
                    <PageHeader
                        breadcrumb={(
                            <ResponsiveBreadcrumb
                                items={[
                                    {
                                        key: "home",
                                        label: t("nav.home"),
                                        onPress: () => router.push(pathConfig().locale().build()),
                                    },
                                    {
                                        key: "current",
                                        label: t("codingPractice.title"),
                                    },
                                ]}
                            />
                        )}
                        title={t("codingPractice.title")}
                        description={t("codingPractice.subtitle")}
                    />

                    <StackV principle="block-boundary"
                        explain="Block-to-block spacing ΓÇö not group-boundary, because this separates major blocks rather than nested section groups."
                        items={[
                            () => <PracticeMobileNav />,
                            () => <ProgressCockpit />,
                            () => (view === "problems" ? (
                                <>
                                    <Box principle="pill-pad" className="sticky top-16 z-40 bg-background py-2"
                                        explain="Pill/chip inset ΓÇö not control-pad, because this pads a compact badge shape rather than a form control.">
                                        <PracticeFilters />
                                    </Box>
                                    <ProblemCatalog />
                                </>
                            ) : (
                                <CodingLeaderboard />
                            )),
                        ]} />
                </Box>
            </Box>
        </div>
    )
}

"use client"

import React from "react"
import {
    Label,
} from "@heroui/react"
import {
    useTranslations,
} from "next-intl"
import {
    useProfileUsername,
} from "@/hooks/profile/useProfileUsername"
import {
    buildDifficultySegments,
} from "@/modules/utils/challenge-difficulty"
import {
    groupByCourse,
} from "@/modules/utils/group-challenges-by-course"
import {
    ChallengeCourseRow,
} from "./ChallengeCourseRow"
import { useQueryUserChallengeStrengthSwr } from "@/hooks/swr/api/graphql/queries/useQueryUserChallengeStrengthSwr"
import { useQueryUserCoursesSwr } from "@/hooks/swr/api/graphql/queries/useQueryUserCoursesSwr"
import { useQueryUserProfileSwr } from "@/hooks/swr/api/graphql/queries/useQueryUserProfileSwr"
import { useQueryUserSolvedChallengesSwr } from "@/hooks/swr/api/graphql/queries/useQueryUserSolvedChallengesSwr"
import { AsyncContent } from "@/components/blocks/async/AsyncContent"
import { LabeledCard } from "@/components/blocks/cards/LabeledCard"
import { StatRibbon } from "@/components/composites/stats/StatRibbon"
import { SegmentBar } from "@/components/composites/stats/SegmentBar"
import { Skeleton } from "@/components/blocks/skeleton/Skeleton"
import { SurfaceListCard, SurfaceListCardItem } from "@/components/blocks/cards/SurfaceListCard"
import { StackH, StackV } from "@/components/frames/Stack"
import type { AllowedClassName } from "@/components/atoms/_allowed-class-name"
import { getLanguageColor, getLanguageLabel } from "@/modules/utils/language"

/** Props for {@link ProfileChallenges}. */
export type ProfileChallengesProps = Record<string, never>
/**
 * Challenges tab ΓÇö the profile owner's graded-challenge proof of work. Leads with
 * a passed count + a 4-tone difficulty {@link SegmentBar} (easyΓåÆgreen /
 * mediumΓåÆyellow / hardΓåÆred / insaneΓåÆpurple), then the submission list rendered as
 * Projects-tab-style rows: one collapsible {@link ChallengeCourseRow} per course
 * (its own difficulty bar + count), expanded on demand to reveal the repo links.
 * Self-contained: reads the username from the route, resolves it to the entity id,
 * and drives its own projection-backed SWR.
 *
 * @param props - optional className for the root element.
 */
export const ProfileChallenges = () => {
    const t = useTranslations()
    // route carries the username; resolve to the entity id the query keys off
    const username = useProfileUsername()
    const { data: user } = useQueryUserProfileSwr(username)
    const userId = user?.id ?? null
    const {
        data,
        isLoading,
        error,
        mutate,
    } = useQueryUserSolvedChallengesSwr(userId)
    // difficulty-weighted challenge strength: global percentile + rank (null until passed)
    const { data: strength } = useQueryUserChallengeStrengthSwr(userId)
    // joined courses ΓåÆ total challenges per course (for the per-course progress bar)
    const { data: coursesData } = useQueryUserCoursesSwr(userId)
    const totalChallengesByCourse = new Map(
        (coursesData ?? []).map((course) => [course.label, course.challengeTotal]),
    )

    const challenges = data ?? []
    // difficulty distribution across all passed challenges (the headline bar)
    const difficultySegments = buildDifficultySegments(challenges)
    // language breadth: count per language, skipping rows with no language
    const langCounts = challenges.reduce<Record<string, number>>((acc, challenge) => {
        if (!challenge.selectedLang) {
            return acc
        }
        acc[challenge.selectedLang] = (acc[challenge.selectedLang] ?? 0) + 1
        return acc
    }, {})
    const langs = Object.entries(langCounts).sort((a, b) => b[1] - a[1])
    // submission list grouped by course (when the backend resolves titles)
    const groups = groupByCourse(challenges)

    // headline metric row (Coding-tab style): passed + XP + percentile + rank.
    // XP is the REAL ledger sum from the backend (NOT a FE sum of scores).
    const metricStats: Array<{ key: string; value: string }> = [
        { key: "passed", value: String(challenges.length) },
    ]
    if (strength?.xp != null) {
        metricStats.push({ key: "xp", value: String(strength.xp) })
    }
    if (strength?.percentile != null) {
        metricStats.push({ key: "percentile", value: `${strength.percentile}%` })
    }
    if (strength?.rank != null) {
        metricStats.push({ key: "rank", value: `#${strength.rank}` })
    }

    const rootClassNames: Array<AllowedClassName> = []


    return (
        <AsyncContent
            isLoading={(isLoading || !userId) && challenges.length === 0}
            skeleton={(
                <StackV gap={6} principle="block-boundary" classNames={rootClassNames}
                    explain="Block-to-block spacing ΓÇö not group-boundary, because this separates major blocks rather than nested section groups."
                    items={[
                        () => (
                            <StackV gap={4} items={[
                                () => <Skeleton.Typography type="body-sm" width="1/4" />,
                                () => <Skeleton className="h-20 w-full rounded-2xl" />,
                            ]} />
                        ),
                        () => (
                            <StackV gap={4} items={[
                                () => <Skeleton.Typography type="body-sm" width="1/4" />,
                                () => (
                                    <SurfaceListCard>
                                        <SurfaceListCardItem>
                                            <Skeleton.SegmentBar legendItems={4} />
                                        </SurfaceListCardItem>
                                        <SurfaceListCardItem>
                                            <Skeleton.SegmentBar legendItems={4} />
                                        </SurfaceListCardItem>
                                    </SurfaceListCard>
                                ),
                            ]} />
                        ),
                        () => (
                            <StackV gap={4} items={[
                                () => <Skeleton.Typography type="body-sm" width="1/4" />,
                                () => (
                                    <SurfaceListCard>
                                        {[0, 1, 2].map((row) => (
                                            <SurfaceListCardItem key={row}>
                                                <StackH gap={4} principle="content-row" align="start"
                                                    explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                                    items={[
                                                        () => <Skeleton className="size-12 shrink-0 rounded-xl" />,
                                                        () => (
                                                            <StackV gap={3} principle="sibling-stack" classNames={["min-w-0", "flex-1"]}
                                                                explain="Same-kind peer stack ΓÇö not group-boundary, because these items are repeating siblings rather than section groups."
                                                                items={[
                                                                    () => <Skeleton.Typography type="body-sm" width="1/2" />,
                                                                    () => <Skeleton.ProgressBar />,
                                                                    () => <Skeleton.Typography type="body-xs" width="1/3" />,
                                                                ]} />
                                                        ),
                                                    ]} />
                                            </SurfaceListCardItem>
                                        ))}
                                    </SurfaceListCard>
                                ),
                            ]} />
                        ),
                    ]} />
            )}
            isEmpty={challenges.length === 0}
            emptyContent={{
                title: t("publicProfile.challengesTab.empty"),
                description: t("publicProfile.challengesTab.emptyHint"),
            }}
            error={challenges.length === 0 ? error : undefined}
            errorContent={{
                title: t("publicProfile.loadError"),
                onRetry: () => { void mutate() },
                retryLabel: t("publicProfile.loadErrorRetry"),
            }}
        >
            <StackV gap={6} principle="block-boundary" classNames={rootClassNames}
                explain="Block-to-block spacing ΓÇö not group-boundary, because this separates major blocks rather than nested section groups."
                items={[
                    () => (
                        <LabeledCard label={t("publicProfile.challengesTab.metricsHeading")} frameless>
                            <StatRibbon
                                items={metricStats.map((stat) => ({
                                    key: stat.key,
                                    value: stat.value,
                                    label: t(`publicProfile.challengesTab.metric.${stat.key}`),
                                }))}
                            />
                        </LabeledCard>
                    ),
                    () => (
                        <LabeledCard
                            label={t("publicProfile.challengesTab.statsHeading")}
                            frameless
                        >
                            <SurfaceListCard>
                                {difficultySegments.length > 0 ? (
                                    <SurfaceListCardItem>
                                        <StackV gap={3} principle="sibling-stack"
                                            explain="Same-kind peer stack ΓÇö not group-boundary, because these items are repeating siblings rather than section groups."
                                            items={[
                                                () => <Label>{t("publicProfile.challengesTab.difficultyHeading")}</Label>,
                                                () => (
                                                    <SegmentBar
                                                        ariaLabel={t("publicProfile.challengesTab.difficultyHeading")}
                                                        segments={difficultySegments}
                                                    />
                                                ),
                                            ]} />
                                    </SurfaceListCardItem>
                                ) : null}
                                {langs.length > 0 ? (
                                    <SurfaceListCardItem>
                                        <StackV gap={3} principle="sibling-stack"
                                            explain="Same-kind peer stack ΓÇö not group-boundary, because these items are repeating siblings rather than section groups."
                                            items={[
                                                () => <Label>{t("publicProfile.challengesTab.languageHeading")}</Label>,
                                                () => (
                                                    <SegmentBar
                                                        ariaLabel={t("publicProfile.challengesTab.languageHeading")}
                                                        segments={langs.map(([lang, count]) => ({
                                                            key: lang,
                                                            label: getLanguageLabel(lang),
                                                            value: count,
                                                            color: getLanguageColor(lang),
                                                        }))}
                                                    />
                                                ),
                                            ]} />
                                    </SurfaceListCardItem>
                                ) : null}
                            </SurfaceListCard>
                        </LabeledCard>
                    ),
                    () => (
                        <LabeledCard
                            label={t("publicProfile.challengesTab.repoHeading")}
                            frameless
                        >
                            <SurfaceListCard>
                                {groups.map((group, groupIndex) => (
                                    <ChallengeCourseRow
                                        key={group.courseTitle ?? `__ungrouped-${groupIndex}`}
                                        username={username}
                                        courseTitle={group.courseTitle}
                                        courseSlug={group.courseSlug}
                                        items={group.items}
                                        totalChallenges={group.courseTitle
                                            ? totalChallengesByCourse.get(group.courseTitle)
                                            : undefined}
                                    />
                                ))}
                            </SurfaceListCard>
                        </LabeledCard>
                    ),
                ]} />
        </AsyncContent>
    )
}

"use client"

import React, {
    useCallback,
    useMemo,
} from "react"
import {
    Card,
} from "@heroui/react"
import {
    useTranslations,
} from "next-intl"
import {
    useSearchParams,
} from "next/navigation"
import type {
    BankDetails,
} from "@/modules/types/sepay-checkout"
import {
    parseBankDetails,
} from "@/modules/utils/parse-bank-details"
import {
    DetailRow,
} from "../DetailRow"
import { Box } from "@/components/frames/Box"
import { StackH, StackV } from "@/components/frames/Stack"

/**
 * Right-hand panel: the price card plus the bank/account/amount/content rows.
 *
 * Self-contained section (single-use): reads its own checkout query params,
 * derives the destination bank from the QR url, and owns the clipboard copy
 * handler ΓÇö so the checkout container only renders `<OrderSummary />` and the
 * logic lives next to where it is used. `"use client"` for the query-params /
 * i18n hooks and the interactive copy rows. The repeated rows are rendered via
 * the presentational {@link DetailRow} (list-style), which takes the local
 * `onCopy` handler as a prop.
 */
export const OrderSummary = () => {
    const t = useTranslations()
    const searchParams = useSearchParams()

    const amount = searchParams.get("amount") || ""
    const referenceId = searchParams.get("ref") || ""
    const courseTitle = searchParams.get("courseTitle") || ""
    const qrUrl = searchParams.get("qr") || ""

    /** Destination bank + account parsed once from the QR url. */
    const bankDetails = useMemo<BankDetails>(
        () => parseBankDetails(qrUrl),
        [
            qrUrl,
        ],
    )

    /** Copy the given text to the clipboard. */
    const onCopy = useCallback(
        (text: string) => {
            void navigator.clipboard.writeText(text)
        },
        [],
    )

    return (
        <StackV identity={{ tier: "page", component: "OrderSummary" }} principle="block-boundary"
            explain="Block-to-block spacing ΓÇö not group-boundary, because this separates major blocks rather than nested section groups."
            items={[
                () => (
                    <Card className="bg-default/40 backdrop-blur-md">
                        <Box principle="card-padding" className="p-6"
                            explain="Card body inset ΓÇö not page-pad, because this is the surface padding of a card rather than the page chrome.">
                            <Card.Content>
                                <h3 className="mb-4 text-lg font-medium">{courseTitle}</h3>
                                <StackH principle="value-row"
                                    explain="Holds a label and its numeric value on one baseline so the count stays readable against the label."
                                    items={[
                                        () => (
                                            <span className="text-3xl font-bold text-primary">
                                                {Number(amount).toLocaleString("vi-VN")}
                                            </span>
                                        ),
                                        () => <span className="text-sm text-muted">VND</span>,
                                    ]} />
                            </Card.Content>
                        </Box>
                    </Card>
                ),

                () => (
                    <Card className="flex-grow bg-default/40 backdrop-blur-md">
                        <Box principle="card-padding" className="p-6"
                            explain="Card body inset ΓÇö not page-pad, because this is the surface padding of a card rather than the page chrome.">
                            <Card.Content>
                                <StackV principle="content-row"
                                    explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                    items={[
                                        () => <DetailRow label={t("payment.sepay.bank")} value={bankDetails.bank} />,
                                        () => (
                                            <DetailRow
                                                copyValue={bankDetails.account}
                                                label={t("payment.sepay.account")}
                                                showCopy
                                                value={bankDetails.account}
                                                onCopy={onCopy}
                                            />
                                        ),
                                        () => (
                                            <DetailRow
                                                copyValue={amount}
                                                label={t("payment.sepay.amount")}
                                                showCopy
                                                value={`${Number(amount).toLocaleString("vi-VN")} VND`}
                                                onCopy={onCopy}
                                            />
                                        ),
                                        () => (
                                            <DetailRow
                                                copyValue={referenceId}
                                                isHighlighted
                                                label={t("payment.sepay.content")}
                                                showCopy
                                                value={referenceId}
                                                onCopy={onCopy}
                                            />
                                        ),
                                    ]} />
                            </Card.Content>
                        </Box>
                    </Card>
                ),
            ]} />
    )
}

"use client"

import React, { useMemo } from "react"
import { Card, CardContent } from "@heroui/react"
import {
    CheckCircleIcon,
    WarningIcon,
    XCircleIcon,
} from "@phosphor-icons/react"
import { useTranslations } from "next-intl"
import type { IconComponent } from "@/components/atoms/chips/Chip"
import { StatusChip } from "@/components/blocks/chips/StatusChip"
import { Box } from "@/components/frames/Box"
import { FillAvailable } from "@/components/frames/FillAvailable"
import { StackH, StackV } from "@/components/frames/Stack"
import { resolveComponentStatusVisual } from "@/modules/utils/system-status-map"
import { ComponentStatus } from "@/modules/api/graphql/queries/enums"
import type { SystemHealthComponent } from "@/modules/api/graphql/queries/types/system-health-status"
import { getTimeAgoLabel, getTimeAgoMessage } from "@/modules/dayjs"

/** Props for {@link ComponentCard}. */
export interface ComponentCardProps {
    /** One probed infrastructure component from GraphQL. */
    component: SystemHealthComponent
}

/** Leading StatusChip icon per infrastructure status (contract E ΓÇö component refs). */
const STATUS_CHIP_ICON: Record<ComponentStatus, IconComponent> = {
    [ComponentStatus.Up]: CheckCircleIcon,
    [ComponentStatus.Degraded]: WarningIcon,
    [ComponentStatus.Down]: XCircleIcon,
}

/**
 * A single infrastructure component card on the public status page ΓÇö status dot
 * + name, a status chip, latency ("12ms"), and a relative last-checked time.
 *
 * List item: keeps its own `component` payload but reads its own status labels
 * + relative-time strings from the i18n hooks (no prop-drilled maps).
 * @param props.component - Probed component snapshot.
 */
export const ComponentCard = ({ component }: ComponentCardProps) => {
    const t = useTranslations()
    const visual = resolveComponentStatusVisual(component.status)
    const statusIcon =
        STATUS_CHIP_ICON[component.status as ComponentStatus] ?? STATUS_CHIP_ICON[ComponentStatus.Down]

    const statusLabel = t(`status.componentStatus.${component.status}`)

    const checkedAgo = useMemo(
        () => getTimeAgoLabel(getTimeAgoMessage(component.checkedAt), t),
        [component.checkedAt, t],
    )

    return (
        <Card className="border border-default bg-surface">
            {/* Vendor CardContent padding cleared so house card-padding owns the inset. */}
            <CardContent className="p-0">
                <Box principle="card-padding" className="p-4"
                    explain="Card body inset ΓÇö not page-pad, because this is the surface padding of a card rather than the page chrome.">
                    <StackV
                        principle="sibling-stack"
                        explain="Same-kind peer stack ΓÇö not group-boundary, because these items are repeating siblings rather than section groups."
                        items={[
                            () => (
                                <StackH
                                    principle="flex-action-between"
                                    explain="Identity and status chip shoved apart on one control row ΓÇö not plain flex-action, because the status reads as the trailing commit."
                                    items={[
                                        () => (
                                            <FillAvailable
                                                at="base"
                                                explain="Component name takes remaining header width beside the status chip so long service ids truncate."
                                                body={() => (
                                                    <StackH
                                                        principle="identity"
                                                        explain="Keeps avatar and identity text as one peer unit so the person label stays beside the face."
                                                        items={[
                                                            () => (
                                                                <span
                                                                    className={`size-2.5 shrink-0 rounded-full ${visual.dotClassName}`}
                                                                    aria-hidden
                                                                />
                                                            ),
                                                            () => (
                                                                <span className="truncate font-mono text-sm font-medium text-foreground">
                                                                    {component.name}
                                                                </span>
                                                            ),
                                                        ]}
                                                    />
                                                )}
                                            />
                                        ),
                                        () => (
                                            <StatusChip tone={visual.tone} icon={statusIcon}>
                                                {statusLabel}
                                            </StatusChip>
                                        ),
                                    ]}
                                />
                            ),
                            () => (
                                <StackH
                                    principle="flex-action-between"
                                    explain="Latency and checked-ago meta shoved apart on one control row ΓÇö not plain flex-action, because the pair reads as escape/commit ends."
                                    items={[
                                        () => (
                                            <span className="tabular-nums text-xs text-muted">
                                                {component.latencyMs === null
                                                    ? "ΓÇö"
                                                    : t("status.latency", { ms: component.latencyMs })}
                                            </span>
                                        ),
                                        () => (
                                            <span className="truncate text-xs text-muted">
                                                {t("status.checked", { ago: checkedAgo })}
                                            </span>
                                        ),
                                    ]}
                                />
                            ),
                            ...(component.message ? [() => (
                                <p className="truncate text-xs text-danger-soft-foreground" title={component.message ?? undefined}>
                                    {component.message}
                                </p>
                            )] : []),
                        ]}
                    />
                </Box>
            </CardContent>
        </Card>
    )
}
